    14→import { TooltipIcon } from '../ui/Tooltip';
    15→import { SkeletonTable } from '../ui/Skeleton';
    16→import { ErrorCard } from '../ui/ErrorDisplay';
    17→
    18→type CommunityWithMetrics = {
    19→  shortCode: string;
    20→  name: string | null;
    21→  status: string | null;
    22→  lotsRemaining: number;
    23→  totalPlattedLots: number;
    24→  agingInventory: number;
    25→  carryCost: number;
    26→  avgAgeOfInventory: number | null;
    27→  activeSpecs: number;
    28→  paceActual: number | null;
    29→  paceGoal: number | null;
    30→  pacePercentage: number | null;
    31→  backlogCount: number;
    32→  targetGp: number | null;
    33→};
    34→
    35→const getStatusColor = (status: string | null) => {
    36→  if (status === 'Active') return 'bg-green-50 text-green-700';
    37→  if (status === 'Planning') return 'bg-amber-50 text-amber-600';
    38→  return 'bg-gray-100 text-gray-500';
    39→};
    40→
    41→const formatPace = (community: CommunityWithMetrics) => {
    42→  if (community.paceGoal === null || community.paceGoal === 0) return '—';
    43→  if (community.paceActual === null) return '—';
    44→
    45→  const percentage = Math.round(
    46→    community.pacePercentage ?? (community.paceActual / community.paceGoal) * 100
    47→  );
    48→
    49→  return `${formatCount(community.paceActual)} of ${formatCount(community.paceGoal)} (${formatCount(percentage)}%)`;
    50→};
    51→
    52→const formatTargetGp = (value: number | null | undefined) => {
    53→  if (value === null || value === undefined) return '—';
    54→  const pct = Math.round(value * 100);
    55→  return `${pct}%`;
