    28→
    29→function computeBins(values: number[], binCount = 12): Bin[] {
    30→  if (values.length === 0) return [];
    31→  const min = Math.min(...values);
    32→  const max = Math.max(...values);
    33→  if (min === max) return [{ label: `$${min.toFixed(0)}`, min, max: max + 1, count: values.length }];
    34→
    35→  const step = (max - min) / binCount;
    36→  const bins: Bin[] = [];
    37→  for (let i = 0; i < binCount; i++) {
    38→    const lo = min + i * step;
    39→    const hi = lo + step;
    40→    bins.push({
    41→      label: `$${lo.toFixed(0)}`,
    42→      min: lo,
    43→      max: hi,
    44→      count: 0,
    45→    });
    46→  }
    47→
    48→  for (const v of values) {
    49→    const idx = Math.min(Math.floor((v - min) / step), binCount - 1);
    50→    bins[idx].count++;
    51→  }
    52→
    53→  return bins;
    54→}
    55→
    56→function computeQuartiles(values: number[]): { q1: number; median: number; q3: number } | null {
    57→  if (values.length < 3) return null;
    58→  const sorted = [...values].sort((a, b) => a - b);
    59→  const mid = Math.floor(sorted.length / 2);
    60→  const median = sorted.length % 2 !== 0 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
    61→  const lowerHalf = sorted.slice(0, mid);
    62→  const upperHalf = sorted.length % 2 !== 0 ? sorted.slice(mid + 1) : sorted.slice(mid);
    63→  const q1mid = Math.floor(lowerHalf.length / 2);
    64→  const q1 = lowerHalf.length % 2 !== 0 ? lowerHalf[q1mid] : (lowerHalf[q1mid - 1] + lowerHalf[q1mid]) / 2;
    65→  const q3mid = Math.floor(upperHalf.length / 2);
    66→  const q3 = upperHalf.length % 2 !== 0 ? upperHalf[q3mid] : (upperHalf[q3mid - 1] + upperHalf[q3mid]) / 2;
    67→  return { q1, median, q3 };
    68→}
