    75→  for (let i = 1; i < bins.length; i++) {
    76→    const dist = Math.abs(value - bins[i].min);
    77→    if (dist < minDist) {
    78→      minDist = dist;
    79→      closest = bins[i];
    80→    }
    81→  }
    82→  return closest.label;
    83→}
