    42→/** Hide comps with $/sqft or DOM more than 50% above the subject property */
    43→const OUTLIER_THRESHOLD = 1.5;
    44→
    45→function filterOutlierComps(
    46→  comps: DiagnosticComp[],
    47→  subjectPpsf: number,
    48→  subjectDom: number,
    49→): { filtered: DiagnosticComp[]; hidden: DiagnosticComp[] } {
    50→  const ppsfCeil = subjectPpsf > 0 ? subjectPpsf * OUTLIER_THRESHOLD : Infinity;
    51→  const domCeil = subjectDom > 0 ? subjectDom * OUTLIER_THRESHOLD : Infinity;
    52→  const filtered: DiagnosticComp[] = [];
    53→  const hidden: DiagnosticComp[] = [];
    54→  for (const c of comps) {
    55→    if ((c.price_per_sqft ?? 0) <= ppsfCeil && (c.dom ?? 0) <= domCeil) {
    56→      filtered.push(c);
    57→    } else {
    58→      hidden.push(c);
    59→    }
    60→  }
    61→  return { filtered, hidden };
    62→}
    63→
    64→function toChartPoints(comps: DiagnosticComp[]): ChartPoint[] {
    65→  return comps.map((c) => ({
