    83→      <p className="text-ink-muted">
    84→        ${d.price.toLocaleString()} &middot; {d.sqft.toLocaleString()} sqft
    85→      </p>
    86→      <p className="text-ink-muted">Match: {((d.match ?? 0) * 100).toFixed(0)}%</p>
    87→      {d.isSubject && <p className="font-medium text-green-600">Subject Property</p>}
