    36→        setClosing(false);
    37→        // Return focus to trigger element
    38→        if (triggerId) {
    39→          const trigger = document.getElementById(triggerId);
    40→          trigger?.focus();
    41→        }
    42→      }, 220); // matches drawer-out 0.2s + buffer
    43→      return () => clearTimeout(timer);
    44→    }
    45→    setWasOpen(open);
    46→  }, [open, triggerId, wasOpen]);
    47→
    48→  // Focus heading when drawer opens
    49→  useEffect(() => {
    50→    if (open) {
    51→      requestAnimationFrame(() => {
    52→        headingRef.current?.focus();
    53→      });
    54→    }
    55→  }, [open]);
    56→
    57→  // Escape key handler
