content.content:
  1→/**
  2→ * Metric threshold configuration for color-coding health indicators.
  3→ *
  4→ * PLACEHOLDER VALUES - Adjust based on David's input.
  5→ * These thresholds determine green/yellow/red coloring in the UI.
  6→ */
  7→
  8→export type ThresholdLevel = 'green' | 'yellow' | 'orange' | 'red' | 'neutral';
  9→
 10→export type MetricThresholds = {
 11→  agingInventory: {
 12→    green: { max: number };
 13→    yellow: { max: number };
 14→    red: { min: number };
 15→  };
 16→  avgAgeOfInventory: {
 17→    green: { max: number };
 18→    yellow: { max: number };
 19→    red: { min: number };
 20→  };
 21→  carryCost: {
 22→    green: { max: number };
 23→    yellow: { max: number };
 24→    red: { min: number };
 25→  };
 26→};
 27→
 28→export const METRIC_THRESHOLDS: MetricThresholds = {
 29→  agingInventory: {
 30→    green: { max: 0 }, // 0 aging = green
 31→    yellow: { max: 3 }, // 1-3 = yellow
 32→    red: { min: 4 }, // 4+ = red
 33→  },
 34→  avgAgeOfInventory: {
 35→    green: { max: 30 }, // < 30 days = green
 36→    yellow: { max: 60 }, // 30-60 days = yellow
 37→    red: { min: 61 }, // > 60 days = red
 38→  },
 39→  carryCost: {
 40→    green: { max: 12000 }, // ~1-2 aging specs at typical price
 41→    yellow: { max: 35000 }, // ~3-5 aging specs
 42→    red: { min: 35001 }, // 6+ aging specs
 43→  },
 44→};
 45→
 46→export function getAgingInventoryLevel(value: number | null): ThresholdLevel {
 47→  if (value === null) return 'neutral';
 48→  const t = METRIC_THRESHOLDS.agingInventory;
 49→  if (value <= t.green.max) return 'green';
 50→  if (value <= t.yellow.max) return 'yellow';
 51→  return 'red';
 52→}
 53→
 54→export function getAvgAgeLevel(value: number | null): ThresholdLevel {
 55→  if (value === null) return 'neutral';
 56→  const t = METRIC_THRESHOLDS.avgAgeOfInventory;
 57→  if (value <= t.green.max) return 'green';
 58→  if (value <= t.yellow.max) return 'yellow';
 59→  return 'red';
 60→}
 61→
 62→export function getCarryCostLevel(value: number | null): ThresholdLevel {
 63→  if (value === null) return 'neutral';
 64→  const t = METRIC_THRESHOLDS.carryCost;
 65→  if (value <= t.green.max) return 'green';
 66→  if (value <= t.yellow.max) return 'yellow';
 67→  return 'red';
 68→}
 69→
 70→/**
 71→ * Determines the color level for pace vs budget based on time-proportional thresholds.
 72→ *
 73→ * The color reflects whether the community is on pace for the elapsed portion of the period:
 74→ * - Green:  pacePercentage ≥ expectedPercentage (on pace or ahead)
 75→ * - Yellow: pacePercentage ≥ expectedPercentage × 0.5 (within 50% of expected)
 76→ * - Red:    pacePercentage < expectedPercentage × 0.5 (off pace)
 77→ * - Neutral: null percentage or non-finite elapsedFraction
 78→ *
 79→ * @param percentage - The actual pace percentage (e.g., 25 for 25% of goal achieved)
 80→ * @param elapsedFraction - The fraction of the period elapsed (e.g., 0.0876 for Feb 1 YTD)
 81→ */
 82→export function getPaceLevel(percentage: number | null, elapsedFraction: number): ThresholdLevel {
 83→  if (percentage === null) return 'neutral';
 84→  if (!Number.isFinite(elapsedFraction)) return 'neutral';
 85→
 86→  const expectedPercentage = elapsedFraction * 100;
 87→
 88→  // Green: on pace or ahead
 89→  if (percentage >= expectedPercentage) return 'green';
 90→
 91→  // Yellow: within 50% of expected
 92→  if (percentage >= expectedPercentage * 0.5) return 'yellow';
 93→
 94→  // Red: off pace (below 50% of expected)
 95→  return 'red';
 96→}
 97→
 98→export function getThresholdClasses(level: ThresholdLevel): {
 99→  bg: string;
100→  text: string;
101→  border: string;
102→} {
103→  switch (level) {
104→    case 'green':
105→      return {
106→        bg: 'bg-green-50',
107→        text: 'text-green-700',
108→        border: 'border-green-200',
109→      };
110→    case 'yellow':
111→      return {
112→        bg: 'bg-yellow-50',
