/**
 * Metric threshold configuration for color-coding health indicators.
 *
 * PLACEHOLDER VALUES - Adjust based on David's input.
 * These thresholds determine green/yellow/red coloring in the UI.
 */

export type ThresholdLevel = 'green' | 'yellow' | 'orange' | 'red' | 'neutral';

export type MetricThresholds = {
  agingInventory: {
    green: { max: number };
    yellow: { max: number };
    red: { min: number };
  };
  avgAgeOfInventory: {
    green: { max: number };
    yellow: { max: number };
    red: { min: number };
  };
  carryCost: {
    green: { max: number };
    yellow: { max: number };
    red: { min: number };
  };
};

export const METRIC_THRESHOLDS: MetricThresholds = {
  agingInventory: {
    green: { max: 0 }, // 0 aging = green
    yellow: { max: 3 }, // 1-3 = yellow
    red: { min: 4 }, // 4+ = red
  },
  avgAgeOfInventory: {
    green: { max: 30 }, // < 30 days = green
    yellow: { max: 60 }, // 30-60 days = yellow
    red: { min: 61 }, // > 60 days = red
  },
  carryCost: {
    green: { max: 12000 }, // ~1-2 aging specs at typical price
    yellow: { max: 35000 }, // ~3-5 aging specs
    red: { min: 35001 }, // 6+ aging specs
  },
};

export function getAgingInventoryLevel(value: number | null): ThresholdLevel {
  if (value === null) return 'neutral';
  const t = METRIC_THRESHOLDS.agingInventory;
  if (value <= t.green.max) return 'green';
  if (value <= t.yellow.max) return 'yellow';
  return 'red';
}

export function getAvgAgeLevel(value: number | null): ThresholdLevel {
  if (value === null) return 'neutral';
  const t = METRIC_THRESHOLDS.avgAgeOfInventory;
  if (value <= t.green.max) return 'green';
  if (value <= t.yellow.max) return 'yellow';
  return 'red';
}

export function getCarryCostLevel(value: number | null): ThresholdLevel {
  if (value === null) return 'neutral';
  const t = METRIC_THRESHOLDS.carryCost;
  if (value <= t.green.max) return 'green';
  if (value <= t.yellow.max) return 'yellow';
  return 'red';
}

/**
 * Determines the color level for pace vs budget based on time-proportional thresholds.
 *
 * The color reflects whether the community is on pace for the elapsed portion of the period:
 * - Green:  pacePercentage ≥ expectedPercentage (on pace or ahead)
 * - Yellow: pacePercentage ≥ expectedPercentage × 0.5 (within 50% of expected)
 * - Red:    pacePercentage < expectedPercentage × 0.5 (off pace)
 * - Neutral: null percentage or non-finite elapsedFraction
 *
 * @param percentage - The actual pace percentage (e.g., 25 for 25% of goal achieved)
 * @param elapsedFraction - The fraction of the period elapsed (e.g., 0.0876 for Feb 1 YTD)
 */
export function getPaceLevel(percentage: number | null, elapsedFraction: number): ThresholdLevel {
  if (percentage === null) return 'neutral';
  if (!Number.isFinite(elapsedFraction)) return 'neutral';

  const expectedPercentage = elapsedFraction * 100;

  // Green: on pace or ahead
  if (percentage >= expectedPercentage) return 'green';

  // Yellow: within 50% of expected
  if (percentage >= expectedPercentage * 0.5) return 'yellow';

  // Red: off pace (below 50% of expected)
  return 'red';
}

export function getThresholdClasses(level: ThresholdLevel): {
  bg: string;
  text: string;
  border: string;
} {
  switch (level) {
    case 'green':
      return {
        bg: 'bg-green-50',
        text: 'text-green-700',
        border: 'border-green-200',
      };
    case 'yellow':
      return {
        bg: 'bg-yellow-50',
        text: 'text-yellow-700',
        border: 'border-yellow-200',
      };
    case 'orange':
      return {
        bg: 'bg-orange-50',
        text: 'text-orange-700',
        border: 'border-orange-200',
      };
    case 'red':
      return {
        bg: 'bg-red-50',
        text: 'text-red-700',
        border: 'border-red-200',
      };
    case 'neutral':
    default:
      return {
        bg: 'bg-gray-50',
        text: 'text-gray-500',
        border: 'border-gray-200',
      };
  }
}

export type PerformanceAlertLevel = 'urgent' | 'action' | 'monitor' | 'optimal' | 'noData';

export function getPerformanceAlertLevel(ratio: number | null): PerformanceAlertLevel {
  if (ratio === null) return 'noData';
  if (ratio >= 2.5) return 'urgent';
  if (ratio >= 1.5) return 'action';
  if (ratio >= 1.0) return 'monitor';
  return 'optimal';
}

export function alertLevelToThreshold(level: PerformanceAlertLevel): ThresholdLevel {
  switch (level) {
    case 'urgent': return 'red';
    case 'action': return 'orange';
    case 'monitor': return 'yellow';
    case 'optimal': return 'green';
    case 'noData': return 'neutral';
  }
}

export const ALERT_LEVEL_CONFIG: Record<PerformanceAlertLevel, {
  label: string;
  action: string;
}> = {
  urgent: {
    label: 'Urgent attention',
    action: 'Action needed in 24-48 hours',
  },
  action: {
    label: 'Action required',
    action: 'Review in 7-14 days',
  },
  monitor: {
    label: 'Monitor closely',
    action: 'Weekly review recommended',
  },
  optimal: {
    label: 'Performing well',
    action: 'No action needed',
  },
  noData: {
    label: 'Insufficient data',
    action: 'Performance data not yet available',
  },
};

