const CIRCUMFERENCE = 2 * Math.PI * 50;

const HEALTHY_THRESHOLD = 65;
const WATCH_THRESHOLD = 40;

function getColor(score: number): string {
  if (score >= HEALTHY_THRESHOLD) return '#10B981';
  if (score >= WATCH_THRESHOLD) return '#F59E0B';
  return '#EF4444';
}

type RadialRingProps = {
  score: number | null;
  size?: number;
  strokeWidth?: number;
  showLabel?: boolean;
  className?: string;
};

export default function RadialRing({
  score,
  size = 112,
  strokeWidth = 8,
  showLabel = true,
  className,
}: RadialRingProps) {
  const value = score ?? 0;
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (value / 100) * circumference;
  const center = size / 2;
  const color = score != null ? getColor(value) : '#cbd5e1';

  return (
    <div
      className={`relative shrink-0 ${className ?? ''}`}
      aria-label={score != null ? `Health score: ${score} out of 100` : 'Health score: no data'}
    >
      <svg
        width={size}
        height={size}
        viewBox={`0 0 ${size} ${size}`}
        role="img"
      >
        <circle
          cx={center}
          cy={center}
          r={radius}
          fill="none"
          stroke="#f1f5f9"
          strokeWidth={strokeWidth}
        />
        {score != null && (
          <circle
            cx={center}
            cy={center}
            r={radius}
            fill="none"
            stroke={color}
            strokeWidth={strokeWidth}
            strokeLinecap="round"
            strokeDasharray={circumference}
            strokeDashoffset={offset}
            transform={`rotate(-90 ${center} ${center})`}
          />
        )}
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <div className="text-3xl font-bold tabular-nums" style={{ color }}>
          {score != null ? score : '—'}
        </div>
        {showLabel && <div className="text-xs text-ink-muted">/ 100</div>}
      </div>
    </div>
  );
}

