interface LoadingStateProps {
  message?: string;
  size?: 'sm' | 'md' | 'lg';
  className?: string;
}

const sizeClasses = {
  sm: 'w-6 h-6 border-2',
  md: 'w-8 h-8 border-3',
  lg: 'w-12 h-12 border-4',
};

export default function LoadingState({
  message,
  size = 'lg',
  className = '',
}: LoadingStateProps) {
  return (
    <div className={`flex flex-col items-center justify-center py-12 ${className}`}>
      <div
        className={`${sizeClasses[size]} border-t-brand border-gray-200 rounded-full animate-spin border-solid`}
        role="status"
        aria-label={message || 'Loading'}
      />
      {message && <p className="text-ink-muted mt-3 text-sm">{message}</p>}
    </div>
  );
}

import { TooltipIcon } from './Tooltip';

const HEALTHY_THRESHOLD = 65;
const WATCH_THRESHOLD = 40;

function getColor(score: number): string {
  if (score >= HEALTHY_THRESHOLD) return '#10B981';
  if (score >= WATCH_THRESHOLD) return '#F59E0B';
  return '#EF4444';
}

type BulletBarProps = {
  label: string;
  score: number | null;
  detail: string;
  tooltip: string;
  displayValue?: string;
  className?: string;
};

export default function BulletBar({
  label,
  score,
  detail,
  tooltip,
  displayValue,
  className,
}: BulletBarProps) {
  const value = score ?? 0;
  const color = score != null ? getColor(value) : '#94a3b8';
  const slug = label.toLowerCase().replace(/\s+/g, '-');

  return (
    <div data-testid={`factor-${slug}`} className={className}>
      <div className="flex items-center justify-between mb-1">
        <span className="text-xs font-medium text-ink-muted inline-flex items-center gap-1">
          {label}
          <TooltipIcon content={tooltip} position="right" testId={`factor-${slug}-tooltip`} size="xs" />
        </span>
        <span className="text-xs font-bold" style={{ color }}>
          {displayValue ?? (score != null ? value : '—')}
        </span>
      </div>
      {/* Bullet chart: qualitative bands + actual bar + target line */}
      <div className="relative h-3.5 rounded-sm overflow-hidden">
        {/* 3-zone background bands: 0-39 red (40%), 40-64 amber (25%), 65-100 green (35%) */}
        <div className="absolute inset-0 flex">
          <div className="h-full" style={{ width: '40%', background: '#fee2e2' }} />
          <div className="h-full" style={{ width: '25%', background: '#fef9c3' }} />
          <div className="h-full" style={{ width: '35%', background: '#d1fae5' }} />
        </div>
        {/* Actual score bar (inset vertically for bullet chart effect) */}
        {score != null && (
          <div
            className="absolute top-0.5 bottom-0.5 left-0 rounded-sm"
            style={{ width: `${Math.max(value, 2)}%`, background: color, opacity: 0.9 }}
          />
        )}

      </div>
      <div className="text-xs text-ink-muted mt-0.5">{detail}</div>
    </div>
  );
}

