import { useEffect, type ReactNode } from 'react';
import { trackEvent } from '../../lib/posthog';

interface EmptyStateAction {
  label: string;
  href?: string;
  onClick?: () => void;
}

interface EmptyStateProps {
  icon?: ReactNode;
  message: string;
  description?: string;
  action?: EmptyStateAction;
  /** Used for PostHog tracking to identify which component rendered empty */
  component?: string;
}

export default function EmptyState({ icon, message, description, action, component }: EmptyStateProps) {
  useEffect(() => {
    trackEvent('empty_state_shown', { component: component ?? 'unknown', message });
  }, [component, message]);

  return (
    <div role="status" className="flex flex-col items-center justify-center py-12 px-4 text-center">
      {icon && (
        <div className="text-ink-muted/40 mb-3" aria-hidden="true">
          <div className="w-10 h-10">{icon}</div>
        </div>
      )}
      <p className="text-ink-muted text-sm font-medium">{message}</p>
      {description && (
        <p className="text-ink-muted/60 text-xs mt-1 max-w-xs">{description}</p>
      )}
      {action && (
        action.href ? (
          <a
            href={action.href}
            className="mt-4 inline-flex items-center px-3 py-1.5 text-sm font-medium text-white bg-brand hover:bg-brand-hover rounded transition-colors ease-out"
          >
            {action.label}
          </a>
        ) : (
          <button
            onClick={action.onClick}
            className="mt-4 inline-flex items-center px-3 py-1.5 text-sm font-medium text-white bg-brand hover:bg-brand-hover rounded transition-colors ease-out cursor-pointer"
          >
            {action.label}
          </button>
        )
      )}
    </div>
  );
}

