  1→import { useState, useCallback, createContext, useContext, type Dispatch } from 'react';
  2→
  3→type ToastType = 'success' | 'error' | 'info' | 'warning';
  4→
  5→interface Toast {
  6→  id: string;
  7→  type: ToastType;
  8→  message: string;
  9→  duration?: number;
 10→}
 11→
 12→type ToastPayload = {
 13→  type: ToastType;
 14→  message: string;
 15→  duration?: number;
 16→};
 17→
 18→interface ToastContextValue {
 19→  toasts: Toast[];
 20→  showToast: Dispatch<ToastPayload>;
 21→  dismissToast: Dispatch<string>;
 22→}
 23→
 24→const ToastContext = createContext<ToastContextValue | null>(null);
 25→
 26→export function useToast() {
 27→  const context = useContext(ToastContext);
 28→  if (!context) {
 29→    throw new Error('useToast must be used within a ToastProvider');
 30→  }
 31→  return context;
 32→}
 33→
 34→interface ToastProviderProps {
 35→  children: React.ReactNode;
 36→}
 37→
 38→export function ToastProvider({ children }: ToastProviderProps) {
 39→  const [toasts, setToasts] = useState<Toast[]>([]);
 40→
 41→  const dismissToast = useCallback((id: string) => {
 42→    setToasts((prev) => prev.filter((t) => t.id !== id));
 43→  }, []);
 44→
 45→  const showToast = useCallback((payload: ToastPayload) => {
 46→    const { type, message, duration = 4000 } = payload;
 47→    const id = `toast-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
 48→    const toast: Toast = { id, type, message, duration };
 49→
 50→    setToasts((prev) => [...prev, toast]);
 51→
 52→    if (duration > 0) {
 53→      setTimeout(() => {
 54→        dismissToast(id);
 55→      }, duration);
 56→    }
 57→  }, [dismissToast]);
 58→
 59→  return (
 60→    <ToastContext.Provider value={{ toasts, showToast, dismissToast }}>
 61→      {children}
 62→      <ToastContainer toasts={toasts} onDismiss={dismissToast} />
 63→    </ToastContext.Provider>
 64→  );
 65→}
 66→
 67→interface ToastContainerProps {
 68→  toasts: Toast[];
 69→  onDismiss: Dispatch<string>;
 70→}
 71→
 72→function ToastContainer({ toasts, onDismiss }: ToastContainerProps) {
 73→  if (toasts.length === 0) return null;
 74→
 75→  return (
 76→    <div className="fixed bottom-4 right-4 z-[60] flex flex-col gap-2 max-w-sm">
 77→      {toasts.map((toast) => (
 78→        <ToastItem key={toast.id} toast={toast} onDismiss={onDismiss} />
 79→      ))}
 80→    </div>
 81→  );
 82→}
 83→
 84→interface ToastItemProps {
 85→  toast: Toast;
 86→  onDismiss: Dispatch<string>;
 87→}
 88→
 89→function ToastItem({ toast, onDismiss }: ToastItemProps) {
 90→  const [isExiting, setIsExiting] = useState(false);
 91→
 92→  const handleDismiss = () => {
 93→    setIsExiting(true);
 94→    setTimeout(() => onDismiss(toast.id), 200);
 95→  };
 96→
 97→  const getStyles = () => {
 98→    switch (toast.type) {
 99→      case 'success':
100→        return 'bg-green-50 border-green-200 text-green-800';
101→      case 'error':
102→        return 'bg-red-50 border-red-200 text-red-800';
103→      case 'warning':
104→        return 'bg-amber-50 border-amber-200 text-amber-800';
105→      case 'info':
106→      default:
107→        return 'bg-blue-50 border-blue-200 text-blue-800';
108→    }
109→  };
110→
111→  const getIcon = () => {
112→    switch (toast.type) {
113→      case 'success':
114→        return (
115→          <svg className="w-5 h-5 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
116→            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
117→          </svg>
118→        );
119→      case 'error':
120→        return (
121→          <svg className="w-5 h-5 text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
122→            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
123→          </svg>
124→        );
125→      case 'warning':
126→        return (
127→          <svg className="w-5 h-5 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
128→            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
129→          </svg>
130→        );
131→      case 'info':
132→      default:
133→        return (
134→          <svg className="w-5 h-5 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
135→            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
136→          </svg>
137→        );
138→    }
139→  };
140→
141→  return (
142→    <div
143→      className={`
144→        flex items-start gap-3 p-4 rounded-lg border shadow-lg
145→        ${getStyles()}
146→        ${isExiting ? 'animate-slide-out' : 'animate-slide-in'}
147→      `}
148→      role="alert"
149→      aria-live="polite"
150→    >
151→      <span className="flex-shrink-0">{getIcon()}</span>
152→      <p className="flex-1 text-sm font-medium">{toast.message}</p>
153→      <button
154→        onClick={handleDismiss}
155→        className="flex-shrink-0 opacity-70 hover:opacity-100 transition-opacity ease-out"
156→        aria-label="Dismiss"
157→      >
158→        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
159→          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
160→        </svg>
161→      </button>
162→    </div>
163→  );
