import { getUserFriendlyError } from '../../lib/errorMessages';

interface ErrorDisplayProps {
  error: unknown;
  onRetry?: () => void;
  className?: string;
}

export default function ErrorDisplay({ error, onRetry, className = '' }: ErrorDisplayProps) {
  const { message, suggestion } = getUserFriendlyError(error);

  return (
    <div
      className={`bg-red-50 border border-red-200 rounded-lg p-4 ${className}`}
      role="alert"
    >
      <div className="flex items-start gap-3">
        <svg
          className="w-5 h-5 text-red-500 flex-shrink-0 mt-0.5"
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={2}
            d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
          />
        </svg>
        <div className="flex-1">
          <p className="text-sm font-medium text-red-800">{message}</p>
          {suggestion && (
            <p className="text-sm text-red-600 mt-1">{suggestion}</p>
          )}
        </div>
        {onRetry && (
          <button
            onClick={onRetry}
            className="text-sm font-medium text-red-600 hover:text-red-800 underline flex-shrink-0"
          >
            Try again
          </button>
        )}
      </div>
    </div>
  );
}

interface ErrorCardProps {
  error: unknown;
  onRetry?: () => void;
  title?: string;
}

export function ErrorCard({ error, onRetry, title = 'Something went wrong' }: ErrorCardProps) {
  const { message, suggestion } = getUserFriendlyError(error);

  return (
    <div className="bg-white rounded-lg shadow-sm p-8 text-center">
      <div className="mx-auto w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4">
        <svg
          className="w-6 h-6 text-red-500"
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={2}
            d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
          />
        </svg>
      </div>
      <h3 className="text-lg font-semibold text-ink mb-2">{title}</h3>
      <p className="text-ink-muted mb-1">{message}</p>
