import {
  alertLevelToThreshold,
  getThresholdClasses,
  type PerformanceAlertLevel,
} from '../../lib/metricThresholds';

const LABEL: Record<PerformanceAlertLevel, string> = {
  urgent: 'Urgent attention',
  action: 'Action required',
  monitor: 'Monitor closely',
  optimal: 'Performing well',
  noData: 'Insufficient data',
};

const DOT_COLOR: Record<PerformanceAlertLevel, string> = {
  urgent: 'bg-red-500',
  action: 'bg-orange-500',
  monitor: 'bg-yellow-400',
  optimal: 'bg-green-500',
  noData: 'bg-gray-300',
};

type StatusIndicatorProps = {
  level: PerformanceAlertLevel;
  showLabel?: boolean;
  size?: 'sm' | 'md';
};

export default function StatusIndicator({ level, showLabel = true, size = 'sm' }: StatusIndicatorProps) {
  const thresholdLevel = alertLevelToThreshold(level);
  const classes = getThresholdClasses(thresholdLevel);
  const dotSize = size === 'sm' ? 'w-2 h-2' : 'w-2.5 h-2.5';

  return (
    <span className="inline-flex items-center gap-1.5">
      <span
        className={`${dotSize} rounded-full ${DOT_COLOR[level]} shrink-0`}
        aria-hidden="true"
      />
      {showLabel && (
        <span className={`text-xs font-medium ${classes.text}`}>
          {LABEL[level]}
        </span>
      )}
    </span>
  );
}

export { LABEL as STATUS_LABELS };

