import { useState, useEffect } from 'react';

interface P3ResultsData {
  paceScore: number;
  profitScore: number;
  personaScore: number;
  weightedScore: number;
  predictedDomDays: number;
  predictedMarginPct: number;
  totalCost: number;
  totalPrice: number;
  gpDollars: number;
  pricePerSqft: number;
  communityAvgPpsf?: number;
}

interface P3Weights {
  pace: number;
  profit: number;
  persona: number;
}

interface AIScoreExplanation {
  paceExplanation: string;
  profitExplanation: string;
  personaExplanation: string;
  topSuggestion: string;
  marketContext: string;
}

interface ScoreContext {
  zipcode: string;
  communityName: string;
  planName: string;
  sqft: number;
  beds: number;
  baths: number;
  optionsTotal: number;
  lotPremium: number;
  targetPersona: string;
}

interface P3ScoreResultsProps {
  results: P3ResultsData | null;
  weights: P3Weights;
  floorPlanName: string;
  lotNumber: string;
  selectedOptionsCount: number;
  loading?: boolean;
  error?: string | null;
  // Additional context for AI explanations
  scoreContext?: ScoreContext;
}

function ScoreBar({ score, label, color, weight }: { score: number; label: string; color: string; weight: number }) {
  const getScoreColor = (score: number) => {
    if (score >= 75) return 'text-green-600';
    if (score >= 50) return 'text-yellow-600';
    return 'text-red-600';
  };

  return (
    <div className="mb-4">
      <div className="flex justify-between items-center mb-1">
        <div className="flex items-center">
          <span className="font-medium text-ink">{label}</span>
          <span className="ml-2 text-xs text-ink-muted">({weight}% weight)</span>
        </div>
        <span className={`font-bold ${getScoreColor(score)}`}>{score.toFixed(0)}</span>
      </div>
      <div className="h-3 bg-gray-200 rounded-full overflow-hidden">
        <div
          className={`h-full ${color} rounded-full transition-all duration-500 ease-out`}
          style={{ width: `${Math.min(100, Math.max(0, score))}%` }}
        />
      </div>
    </div>
  );
}

export default function P3ScoreResults({
  results,
  weights,
  floorPlanName,
  lotNumber,
  selectedOptionsCount,
  loading,
  error,
  scoreContext,
}: P3ScoreResultsProps) {
  const [aiExplanation, setAiExplanation] = useState<AIScoreExplanation | null>(null);
  const [aiLoading, setAiLoading] = useState(false);
  const [aiError, setAiError] = useState<string | null>(null);

  // Fetch AI explanations when results are available
  useEffect(() => {
    if (results && scoreContext) {
      fetchAIExplanation();
    }
  }, [results, scoreContext]);

  async function fetchAIExplanation() {
    if (!results || !scoreContext) return;

    setAiLoading(true);
    setAiError(null);

    try {
      const response = await fetch('/api/ai/explain-scores', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          zipcode: scoreContext.zipcode,
          communityName: scoreContext.communityName,
          planName: scoreContext.planName,
          sqft: scoreContext.sqft,
          beds: scoreContext.beds,
          baths: scoreContext.baths,
          totalPrice: results.totalPrice,
          optionCount: selectedOptionsCount,
          optionsTotal: scoreContext.optionsTotal,
          lotNumber: lotNumber,
          lotPremium: scoreContext.lotPremium,
          paceScore: results.paceScore,
          profitScore: results.profitScore,
          personaScore: results.personaScore,
          weightedScore: results.weightedScore,
          predictedDom: results.predictedDomDays,
          marginPct: results.predictedMarginPct,
          targetPersona: scoreContext.targetPersona,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to get AI explanation');
      }

      const data = await response.json();
      setAiExplanation(data);
    } catch (err) {
      setAiError(err instanceof Error ? err.message : 'Failed to load AI explanation');
    } finally {
      setAiLoading(false);
    }
  }

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <div className="inline-block h-12 w-12 animate-spin rounded-full border-4 border-solid border-brand border-r-transparent mb-4"></div>
        <span className="text-ink-muted">Calculating P3 scores...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 border border-red-200 rounded-lg p-4 text-red-700">
        {error}
      </div>
    );
  }

  if (!results) {
    return (
      <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4 text-yellow-700">
        No results available. Please complete the previous steps.
      </div>
    );
  }

  const getOverallScoreColor = (score: number) => {
    if (score >= 75) return 'text-green-600 bg-green-50 border-green-200';
    if (score >= 50) return 'text-yellow-600 bg-yellow-50 border-yellow-200';
    return 'text-red-600 bg-red-50 border-red-200';
  };

  const getDomAssessment = (dom: number) => {
    if (dom <= 30) return { label: 'Fast', color: 'text-green-600' };
    if (dom <= 60) return { label: 'Average', color: 'text-yellow-600' };
    return { label: 'Slow', color: 'text-red-600' };
  };

  const getMarginAssessment = (margin: number) => {
    if (margin >= 25) return { label: 'Strong', color: 'text-green-600' };
    if (margin >= 18) return { label: 'Good', color: 'text-yellow-600' };
    return { label: 'Thin', color: 'text-red-600' };
  };

  const domAssessment = getDomAssessment(results.predictedDomDays);
  const marginAssessment = getMarginAssessment(results.predictedMarginPct);

  return (
    <div>
      <h2 className="text-xl font-semibold text-ink mb-2">P3 Score Results</h2>
      <p className="text-ink-muted mb-6">
        {floorPlanName} on Lot {lotNumber} with {selectedOptionsCount} optional upgrade{selectedOptionsCount !== 1 ? 's' : ''}
      </p>

      {/* Overall Score */}
      <div className={`text-center p-6 rounded-lg border-2 mb-8 ${getOverallScoreColor(results.weightedScore)}`}>
        <p className="text-sm uppercase tracking-wide mb-2">Weighted P3 Score</p>
        <p className="text-5xl font-bold mb-2">{results.weightedScore.toFixed(1)}</p>
        <p className="text-sm opacity-75">out of 100</p>
      </div>

      {/* Component Scores */}
      <div className="bg-white rounded-lg border border-gray-200 p-6 mb-6">
        <h3 className="text-sm font-medium text-ink-muted mb-4">Component Scores</h3>
        <ScoreBar score={results.paceScore} label="Pace" color="bg-blue-500" weight={weights.pace} />
        <ScoreBar score={results.profitScore} label="Profit" color="bg-green-500" weight={weights.profit} />
        <ScoreBar score={results.personaScore} label="Persona" color="bg-purple-500" weight={weights.persona} />
      </div>

      {/* Predictions */}
      <div className="grid grid-cols-2 gap-4 mb-6">
        <div className="bg-white rounded-lg border border-gray-200 p-4">
          <p className="text-sm text-ink-muted mb-1">Predicted DOM</p>
          <div className="flex items-baseline">
            <span className="text-3xl font-bold text-ink">{results.predictedDomDays}</span>
            <span className="ml-1 text-ink-muted">days</span>
          </div>
          <span className={`text-sm font-medium ${domAssessment.color}`}>{domAssessment.label}</span>
        </div>
        <div className="bg-white rounded-lg border border-gray-200 p-4">
          <p className="text-sm text-ink-muted mb-1">Predicted Margin</p>
          <div className="flex items-baseline">
            <span className="text-3xl font-bold text-ink">{results.predictedMarginPct.toFixed(1)}</span>
            <span className="ml-1 text-ink-muted">%</span>
          </div>
          <span className={`text-sm font-medium ${marginAssessment.color}`}>{marginAssessment.label}</span>
        </div>
      </div>

      {/* Financial Summary */}
      <div className="bg-gray-50 rounded-lg border border-gray-200 p-6">
        <h3 className="text-sm font-medium text-ink-muted mb-4">Financial Summary</h3>
        <div className="space-y-3">
          <div className="flex justify-between">
            <span className="text-ink-muted">Total Price</span>
            <span className="font-semibold text-ink">${results.totalPrice.toLocaleString()}</span>
          </div>
          <div className="flex justify-between">
            <span className="text-ink-muted">Total Cost</span>
            <span className="font-medium text-ink">${results.totalCost.toLocaleString()}</span>
          </div>
          <div className="border-t border-gray-200 pt-3 flex justify-between">
            <span className="text-ink-muted">Gross Profit</span>
            <span className="font-bold text-green-600">${results.gpDollars.toLocaleString()}</span>

