import { useState, useEffect, type Dispatch } from 'react';

interface FloorPlan {
  id: string;
  name: string;
  plan_code?: string;
  square_feet: number;
  bedrooms: number;
  bathrooms_full: number;
  bathrooms_half: number;
  stories: number;
  garage_bays?: number;
}

interface CommunityFloorPlan {
  id: string;
  community_id: string;
  floor_plan_id: string;
  base_cost: number;
  base_price: number;
  target_persona?: string;
  standard_option_ids: string[];
  additional_available_option_ids: string[];
  status: string;
  floor_plan: FloorPlan;
}

interface FloorPlanCardsProps {
  communityId: string;
  selectedPlan: CommunityFloorPlan | null;
  onSelect: Dispatch<CommunityFloorPlan>;
}

export default function FloorPlanCards({ communityId, selectedPlan, onSelect }: FloorPlanCardsProps) {
  const [plans, setPlans] = useState<CommunityFloorPlan[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filters, setFilters] = useState({ beds: 'all', sortBy: 'name' });

  useEffect(() => {
    if (communityId) {
      fetchPlans();
    }
  }, [communityId]);

  async function fetchPlans() {
    try {
      setLoading(true);
      const response = await fetch(`/api/community-floor-plans?communityId=${communityId}`);
      if (!response.ok) throw new Error('Failed to fetch floor plans');
      const data = await response.json();
      setPlans(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load floor plans');
    } finally {
      setLoading(false);
    }
  }

  const filteredPlans = plans
    .filter((p) => {
      if (filters.beds !== 'all') {
        return p.floor_plan.bedrooms === parseInt(filters.beds);
      }
      return true;
    })
    .sort((a, b) => {
      switch (filters.sortBy) {
        case 'price':
          return a.base_price - b.base_price;
        case 'sqft':
          return a.floor_plan.square_feet - b.floor_plan.square_feet;
        case 'beds':
          return a.floor_plan.bedrooms - b.floor_plan.bedrooms;
        default:
          return a.floor_plan.name.localeCompare(b.floor_plan.name);
      }
    });

  const uniqueBedCounts = [...new Set(plans.map((p) => p.floor_plan.bedrooms))].sort();

