  'In Development': 'bg-blue-100 text-blue-500',
  'Close Out': 'bg-gray-100 text-gray-500',
};

type CommunityLoadResult =
  | { kind: 'unauthorized' }
  | { kind: 'not_found' }
  | { kind: 'error'; message: string }
  | { kind: 'ok'; community: Community };

async function loadCommunity(id: string): Promise<CommunityLoadResult> {
  try {
    const { data: { user }, error: userError } = await supabase.auth.getUser();

    if (userError || !user) {
      return { kind: 'unauthorized' };
    }

    const { data, error: fetchError } = await supabase
      .from('communities')
      .select('*')
      .eq('id', id)
      .eq('user_id', user.id)
      .single();

    if (fetchError || !data) {
      return { kind: 'not_found' };
    }

    return { kind: 'ok', community: data as Community };
  } catch {
    return { kind: 'error', message: 'Unable to load community. Please try again.' };
  }
}

