type LegacyTabContentProps = {
  activeTab: TabType;
  community: Community;
};

function LegacyTabContent({ activeTab, community }: LegacyTabContentProps) {
  if (activeTab === 'overview') return <LegacyOverviewTab community={community} />;
  if (activeTab === 'floor-plans') return <CommunityFloorPlans communityId={community.id} communityName={community.name} />;
  if (activeTab === 'lots') return <CommunityLots communityId={community.id} />;
  if (activeTab === 'properties') return <CommunityPropertiesList communityId={community.id} communityName={community.name} />;
  return <CommunitySpecDecisions communityId={community.id} />;
}

function ErrorState({ message }: { message: string }) {
  return (
    <div className="max-w-screen-2xl mx-auto space-y-6">
      <div className="bg-white rounded-lg shadow-sm p-12 text-center">
        <h2 className="text-2xl font-bold text-ink mb-2">Community Not Found</h2>
        <p className="text-ink-muted">{message}</p>
      </div>
    </div>
  );
}

export default function LegacyCommunityDashboard({ id }: LegacyCommunityDashboardProps) {
  const [community, setCommunity] = useState<Community | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<TabType>('overview');

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const tab = params.get('tab');
    if (tab && VALID_TABS.has(tab)) {
      setActiveTab(tab as TabType);
    }
  }, []);

  useEffect(() => {
    let isCancelled = false;

    const fetchCommunity = async () => {
      setLoading(true);
      setError(null);
      const result = await loadCommunity(id);
      if (isCancelled) return;

      if (result.kind === 'unauthorized') {
        window.location.href = '/';
        return;
      }

      if (result.kind === 'not_found') {
        setError('The community you\'re looking for doesn\'t exist or you don\'t have access to it.');
      } else if (result.kind === 'error') {
        setError(result.message);
      } else {
        setCommunity(result.community);
        dispatchBreadcrumbContext({ communityName: result.community.name });
      }

      setLoading(false);
    };

    if (id) {
      void fetchCommunity();
    }

    return () => {
      isCancelled = true;
    };
  }, [id]);

  const handleEdit = () => {
    window.location.href = `/communities/${id}/edit`;
  };

  if (loading) {
    return (
      <div className="max-w-screen-2xl mx-auto space-y-6">
        <div className="bg-white rounded-lg shadow-sm p-12">
          <LoadingState />
        </div>
      </div>
    );
  }

  if (error || !community) {
    return <ErrorState message={error ?? 'Unable to load community. Please try again.'} />;
  }

  return (
    <div className="max-w-screen-2xl mx-auto space-y-6">
      <LegacyHeader community={community} onEdit={handleEdit} />

      <div className="bg-white rounded-lg shadow-sm">
        <div className="px-6 pt-4">
          <TabBar
            tabs={LEGACY_TABS}
            activeTab={activeTab}
            onChange={(tabId) => setActiveTab(tabId as TabType)}
            size="md"
          />
        </div>

        <div className="p-6">
          <LegacyTabContent activeTab={activeTab} community={community} />
        </div>
      </div>
    </div>
  );
}

