import { useEffect, useState } from 'react';
import ErrorState from '../ui/ErrorState';
import LoadingState from '../ui/LoadingState';

type CommunityFloorPlansProps = {
  communityId: string;
  communityName: string;
};

type FloorPlan = {
  id: string;
  name: string;
  square_feet: number;
  bedrooms: number;
  bathrooms_full: number;
  bathrooms_half: number;
  stories: number;
};

type CommunityFloorPlan = {
  id: string;
  base_cost: number;
  base_price: number;
  target_persona?: string;
  status: string;
  estimated_build_days?: number;
  standard_option_ids: string[];
  floor_plan: FloorPlan;
};

export default function CommunityFloorPlans({ communityId, communityName }: CommunityFloorPlansProps) {
  const [floorPlans, setFloorPlans] = useState<CommunityFloorPlan[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchFloorPlans();
  }, [communityId]);

  const fetchFloorPlans = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/community-floor-plans?communityId=${communityId}`);

      if (!response.ok) {
        throw new Error('Failed to fetch floor plans');
      }

      const data = await response.json();
      setFloorPlans(data || []);
    } catch (err) {
      setError('Unable to load floor plans');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active':
        return 'bg-green-50 text-green-700';
      case 'coming_soon':
        return 'bg-blue-100 text-blue-500';
      case 'sold_out':
        return 'bg-gray-100 text-gray-500';
      case 'discontinued':
        return 'bg-red-100 text-red-500';
      default:
        return 'bg-gray-100 text-gray-500';
    }
  };

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      maximumFractionDigits: 0,
    }).format(value);
  };

  const calculateMargin = (cost: number, price: number) => {
    const margin = ((price - cost) / price) * 100;
    return margin.toFixed(1);
  };

  if (loading) {
    return <LoadingState />;
  }

  if (error) {
    return <ErrorState message={error} actionLabel="Try Again" onAction={fetchFloorPlans} />;
  }

  if (floorPlans.length === 0) {
    return (
      <div className="text-center py-12">
        <div className="mb-6">
          <svg
            className="mx-auto h-12 w-12 text-gray-400"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"
            />
          </svg>
        </div>
        <h3 className="text-lg font-medium text-ink mb-2">
          No Floor Plans Assigned
        </h3>
        <p className="text-ink-muted mb-6">
          Assign floor plans to this community to start building specs
        </p>
        <button
          onClick={() => {
            window.location.href = `/communities/${communityId}/floor-plans/assign`;
          }}
          className="bg-brand hover:bg-brand-hover text-white font-semibold px-6 py-3 rounded-lg transition-colors ease-out"
        >
          Assign Floor Plan
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6">
        {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold text-ink">
            Floor Plans for {communityName}
          </h2>
          <p className="text-ink-muted mt-1">
            {floorPlans.length} {floorPlans.length === 1 ? 'plan' : 'plans'} assigned
          </p>
        </div>
        <button
          onClick={() => {
            window.location.href = `/communities/${communityId}/floor-plans/assign`;
          }}
          className="bg-brand hover:bg-brand-hover text-white font-semibold px-6 py-2 rounded-lg transition-colors ease-out"
        >
          + Assign Floor Plan
        </button>
      </div>

      {/* Floor Plans Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {floorPlans.map((cfp) => (
          <div
            key={cfp.id}
            className="bg-white border-2 border-gray-200 rounded-lg p-6 hover:border-brand hover:shadow-lg transition-all ease-out cursor-pointer"
          >
            {/* Status Badge */}
            <div className="flex items-center justify-between mb-4">
              <span className={`inline-block px-3 py-1 rounded-full text-xs font-medium ${getStatusColor(cfp.status)}`}>
                {cfp.status.replace('_', ' ').toUpperCase()}
              </span>
              {cfp.target_persona && (
                <span className="text-xs text-ink-muted">{cfp.target_persona}</span>
              )}
            </div>

            {/* Floor Plan Name */}
            <h3 className="text-lg font-bold text-ink mb-2">
              {cfp.floor_plan.name}
            </h3>

            {/* Specs */}
            <div className="flex items-center space-x-4 text-sm text-ink-muted mb-4">
              <span>{cfp.floor_plan.square_feet.toLocaleString()} SF</span>
              <span>•</span>
              <span>{cfp.floor_plan.bedrooms} Bed</span>
              <span>•</span>
              <span>
                {cfp.floor_plan.bathrooms_full}
                {cfp.floor_plan.bathrooms_half > 0 && `.${cfp.floor_plan.bathrooms_half}`} Bath
              </span>
            </div>

            {/* Pricing */}
            <div className="space-y-2 mb-4">
              <div className="flex items-center justify-between text-sm">
                <span className="text-ink-muted">Base Cost</span>
                <span className="font-medium text-ink">{formatCurrency(cfp.base_cost)}</span>
              </div>
              <div className="flex items-center justify-between text-sm">
                <span className="text-ink-muted">Base Price</span>
                <span className="font-medium text-ink">{formatCurrency(cfp.base_price)}</span>
              </div>
              <div className="flex items-center justify-between text-sm border-t border-gray-200 pt-2">
                <span className="text-ink-muted font-medium">Margin</span>
                <span className="font-bold text-status-success">
                  {calculateMargin(cfp.base_cost, cfp.base_price)}%
                </span>
              </div>
            </div>

            {/* Standard Options Count */}
            {cfp.standard_option_ids && cfp.standard_option_ids.length > 0 && (
              <div className="text-xs text-ink-muted mb-4">
                {cfp.standard_option_ids.length} standard {cfp.standard_option_ids.length === 1 ? 'option' : 'options'} included
              </div>
            )}

            {/* Build Time */}
            {cfp.estimated_build_days && (
              <div className="text-xs text-ink-muted mb-4">
                Est. {cfp.estimated_build_days} days to build
              </div>
            )}

            {/* Actions */}
            <div className="flex items-center space-x-2">
              <button
                onClick={() => {
                  window.location.href = `/communities/${communityId}/floor-plans/edit/${cfp.id}`;
                }}
                className="flex-1 bg-white border border-gray-300 text-ink font-medium px-4 py-2 rounded-lg hover:border-brand hover:text-brand transition-colors ease-out text-sm"
              >
                Edit Pricing
              </button>
              <button className="flex-1 bg-brand hover:bg-brand-hover text-white font-medium px-4 py-2 rounded-lg transition-colors ease-out text-sm">
                View Details
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

import Tooltip from '../ui/Tooltip';

type PricePositionIndicatorProps = {
  propertyPricePerSqft: number | null;
  marketMedianPricePerSqft: number | null;
  compCount?: number;
};

type PositionCategory = 'overpriced' | 'above-market' | 'aligned' | 'below-market';

function getPositionCategory(percentDiff: number): PositionCategory {
  if (percentDiff > 10) return 'overpriced';
  if (percentDiff > 5) return 'above-market';
  if (percentDiff < -5) return 'below-market';
  return 'aligned';
}

function formatPercentage(percentDiff: number): string {
  const sign = percentDiff >= 0 ? '+' : '';
  return `${sign}${Math.round(percentDiff)}%`;
}

const categoryStyles: Record<PositionCategory, string> = {
  overpriced: 'text-red-700 bg-red-50',
  'above-market': 'text-amber-600 bg-amber-50',
  aligned: 'text-green-700 bg-green-50',
  'below-market': 'text-blue-500 bg-blue-100',
};

const categoryLabels: Record<PositionCategory, string> = {
  overpriced: 'Overpriced',
  'above-market': 'Above Market',
  aligned: 'Aligned',
  'below-market': 'Below Market',
};

export default function PricePositionIndicator({
  propertyPricePerSqft,
  marketMedianPricePerSqft,
  compCount,
}: PricePositionIndicatorProps) {
  // Return placeholder if either value is null
  if (propertyPricePerSqft === null || marketMedianPricePerSqft === null) {
    return <span className="text-gray-400">—</span>;
  }

  // Avoid division by zero
  if (marketMedianPricePerSqft === 0) {
    return <span className="text-gray-400">—</span>;
  }

  // Calculate percentage difference: (property - market) / market * 100
  const percentDiff = ((propertyPricePerSqft - marketMedianPricePerSqft) / marketMedianPricePerSqft) * 100;
  const category = getPositionCategory(percentDiff);

  const tooltip = compCount != null && compCount > 0 ? `vs. ${compCount} comps` : undefined;
  const showLowCompCount = compCount != null && compCount >= 1 && compCount <= 2;

  return (
    <span className="inline-flex items-center gap-1">
      <Tooltip
        content={<>
          <strong className="block mb-1">Price Position vs. Market</strong>
          Price per sqft compared to median of sold comps.
          Overpriced: &gt;10% above market. Above Market: 5–10% above. Aligned: within ±5%. Below Market: &gt;5% below.
          {tooltip && <span className="block mt-1 text-white/70">{tooltip}</span>}
        </>}
        position="top"
        width="w-56"
      >
        <span
          className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${categoryStyles[category]}`}
          data-testid="price-position-badge"
        >
          {categoryLabels[category]} {formatPercentage(percentDiff)}
        </span>
      </Tooltip>
      {showLowCompCount && (
        <span className="text-[10px] text-ink-muted/60 font-normal" data-testid="low-comp-count">
          ({compCount} comp{compCount !== 1 ? 's' : ''})
        </span>
      )}
    </span>
  );
}

