import { useEffect, useRef, useState } from 'react';
import { trackEvent } from '../../lib/posthog';
import { formatDate } from '../../lib/formatUtils';
import type { ChangeLog as ChangeLogType, ChangeLogEntry } from '../../lib/diagnosticTypes';

type ChangeLogProps = {
  changeLog: ChangeLogType | null;
  specId: string;
};

function EntryIcon({ type }: { type: ChangeLogEntry['type'] }) {
  const cls = "w-3.5 h-3.5 flex-shrink-0 mt-0.5";
  switch (type) {
    case 'new_active':
      return <svg className={`${cls} text-blue-500`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" /></svg>;
    case 'went_pending':
      return <svg className={`${cls} text-amber-500`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>;
    case 'went_closed':
      return <svg className={`${cls} text-green-500`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>;
    case 'price_change':
      return <svg className={`${cls} text-ink-muted`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>;
    case 'delisted':
      return <svg className={`${cls} text-red-500`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2m7-2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>;
  }
}

function entryLabel(entry: ChangeLogEntry): string {
  const count = entry.count ?? 1;
  const detailsSuffix = entry.details ? ` — ${entry.details}` : '';

  if (entry.type === 'new_active') {
    return `${count} new active listing${count > 1 ? 's' : ''}`;
  }

  if (entry.type === 'went_pending') {
    return `${count} went pending`;
  }

  if (entry.type === 'went_closed') {
    return `${count} closed${detailsSuffix}`;
  }

  if (entry.type === 'delisted') {
    return `${count} delisted`;
  }

  const priceDirection = (entry.price_change ?? 0) < 0 ? 'reduced' : 'increased';
  return entry.address
    ? `${entry.address} price ${priceDirection}${detailsSuffix}`
    : `Price change${detailsSuffix}`;
}

function assessmentColor(assessment: string): string {
  const lower = assessment.toLowerCase();
  if (lower.includes('increas') || lower.includes('pressure') || lower.includes('competi')) {
    return 'text-orange-600';
  }
  if (lower.includes('decreas') || lower.includes('improv') || lower.includes('favor')) {
    return 'text-green-600';
  }
  return 'text-ink-muted';
}

export default function ChangeLog({ changeLog, specId }: ChangeLogProps) {
  const trackedRef = useRef(false);
  const [expanded, setExpanded] = useState(false);

  useEffect(() => {
    if (changeLog && !trackedRef.current) {
      trackedRef.current = true;
      const periodDays = Math.round(
        (new Date(changeLog.period_end).getTime() - new Date(changeLog.period_start).getTime()) /
          (1000 * 60 * 60 * 24),
      );
      trackEvent('diagnostic_changelog_viewed', {
        specId,
        periodDays,
        netActiveChange: changeLog.net_active_change,
      });
    }
  }, [changeLog, specId]);

  if (changeLog == null) {
    return (
      <div data-testid="changelog-first-run" className="text-xs text-ink-muted italic py-2">
        No previous data — change tracking begins next week
      </div>
    );
  }

  return (
    <div data-testid="changelog" className="bg-white border border-gray-200 rounded-lg p-6 shadow-sm">
      {/* Always-visible summary header */}
      <button
        onClick={() => setExpanded((prev) => !prev)}
        aria-expanded={expanded}
        aria-controls="changelog-entries"
        className="w-full flex items-center justify-between text-left"
        data-testid="changelog-toggle"
      >
        <div>
          <p className={`text-xs font-medium ${assessmentColor(changeLog.net_assessment)}`} data-testid="net-assessment">
            {changeLog.net_assessment}
          </p>
          <p className="text-xs text-ink-muted mt-0.5">
            Net active change: {changeLog.net_active_change > 0 ? '+' : ''}{changeLog.net_active_change}
            {' · '}
            Median $/SF: {changeLog.median_ppsf_change_pct > 0 ? '+' : ''}{changeLog.median_ppsf_change_pct.toFixed(1)}%
            {' · '}
            Since {formatDate(changeLog.period_start)}
          </p>
        </div>
        <svg
          aria-hidden="true"
          className={`w-4 h-4 flex-shrink-0 text-ink-muted transition-transform ease-out ${expanded ? 'rotate-180' : ''}`}
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
        >
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
        </svg>
      </button>

      {/* Collapsible entries list */}
      {expanded && (
        <div className="mt-3 pt-2 border-t border-gray-100" id="changelog-entries" data-testid="changelog-entries">
          <ul className="space-y-1.5">
            {changeLog.entries.map((entry, i) => (
              <li key={i} className="flex items-start gap-2 text-xs text-ink">
                <EntryIcon type={entry.type} />
                <span>{entryLabel(entry)}</span>
              </li>
            ))}
          </ul>

          {changeLog.entries.length === 0 && (
            <p className="text-xs text-ink-muted italic">No changes detected in this period.</p>
          )}
        </div>
      )}
    </div>
  );
}

