import { useEffect, useMemo, useState, type Dispatch } from 'react';
import { formatUsd } from '../../lib/formatUtils';
import DataGrid, { type DataGridColumn } from '../ui/DataGrid';
import ErrorState from '../ui/ErrorState';
import LoadingState from '../ui/LoadingState';

type CommunityJobLotsProps = {
  shortCode: string;
  onCountChange?: Dispatch<number>;
};

type JobLotRow = {
  lot: string | null;
  job: string | null;
  address: string | null;
  lot_premium: number | null;
  lot_information: string | null;
  garage: string | null;
  acres: number | null;
  plan: string | null;
  list_price: number | null;
  status: string | null;
  dom: number | null;
  original_price: number | null;
  sqft: number | null;
  beds: number | null;
  baths: string | null;
};

function getStatusStyle(status: string | null): { color: string } {
  switch (status) {
    case 'Model':
      return { color: 'bg-gray-100 text-gray-600' };
    case 'MLS Pending':
      return { color: 'bg-purple-100 text-purple-700' };
    case 'MLS Active':
      return { color: 'bg-amber-50 text-amber-700' };
    case 'Available':
    default:
      return { color: 'bg-green-50 text-green-700' };
  }
}

export default function CommunityJobLots({ shortCode, onCountChange }: CommunityJobLotsProps) {
  const normalizedShortCode = useMemo(() => shortCode.trim().toUpperCase(), [shortCode]);
  const [rows, setRows] = useState<JobLotRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchData = async () => {
    try {
      setLoading(true);
      setError(null);

      const res = await fetch(`/api/communities/${normalizedShortCode}/job-lots`);

      if (res.status === 401) {
        window.location.href = '/';
        return;
      }

      if (!res.ok) {
        setError('Unable to load job/lot data. Please try again.');
        return;
      }

      const data = (await res.json()) as JobLotRow[];
      setRows(data || []);
      onCountChange?.((data || []).length);
    } catch {
      setError('Unable to load job/lot data. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (!normalizedShortCode) return;
    fetchData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [normalizedShortCode]);

  const columns = useMemo<DataGridColumn<JobLotRow>[]>(() => [
    {
      id: 'lot',
      header: 'Lot',
      format: (v) => (v as string) ?? '—',
    },
    {
      id: 'job',
      header: 'Job',
      format: (v) => (v as string) ?? '—',
    },
    {
      id: 'address',
      header: 'Address',
      format: (v) => (v as string) ?? '—',
      defaultSort: 'asc',
    },
    {
      id: 'status',
      header: 'Status',
      render: (row) => {
        const statusStyle = getStatusStyle(row.status);
        return (
          <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${statusStyle.color}`}>
            {row.status ?? '—'}
          </span>
        );
      },

    },
    {
      id: 'lot_premium',
      header: 'Lot Premium',
      format: (v) => formatUsd(v as number | null),
    },
    {
      id: 'garage',
      header: 'Garage',
      format: (v) => (v as string) ?? '—',
    },
    {
      id: 'acres',
      header: 'Acres',
      format: (v) => v != null ? Number(v).toFixed(2) : '—',
    },
  ], []);

  if (loading) {
    return <LoadingState />;
  }

  if (error) {
    return <ErrorState message={error} actionLabel="Try Again" onAction={fetchData} />;
  }

  if (rows.length === 0) {
    return (
      <div className="bg-white border border-gray-200 rounded-lg p-8 text-center">
        <h3 className="text-lg font-bold text-ink mb-2">No job/lot data</h3>
        <p className="text-ink-muted">This community has no lots in the job/lot staging data.</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div>
          <div className="flex items-center gap-2">
            <h3 className="text-lg font-bold text-ink">Job/Lots</h3>
            <span className="relative group/tip">
              <svg className="w-4 h-4 text-ink-muted/50 group-hover/tip:text-ink-muted cursor-help" fill="none" viewBox="0 0 20 20" stroke="currentColor" strokeWidth="2">
                <circle cx="10" cy="10" r="8" />
                <path d="M10 9v4M10 7h.01" strokeLinecap="round" />
              </svg>
              <span className="pointer-events-none absolute left-1/2 -translate-x-1/2 top-full mt-2 z-50 w-60 rounded-md bg-ink px-3 py-2 text-xs font-normal leading-relaxed text-white shadow-lg opacity-0 group-hover/tip:opacity-100 transition-opacity ease-out">
                Available lots excluding sold, backlog, and on-market specs. Enriched with MLS data where a match exists.
              </span>
            </span>
          </div>
          <p className="text-sm text-ink-muted mt-1">{rows.length} available lots</p>
        </div>
      </div>

      <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
        <DataGrid
          data={rows}
          columns={columns}
          searchable
          maxHeight={rows.length <= 100 ? 'none' : '60vh'}
        />
      </div>
    </div>
  );
}

