import { useState, useEffect, type ChangeEvent, type Dispatch, type FormEvent, type SetStateAction } from 'react';
import {
  CommunityNameAddressFields,
  CommunityStatusLotsFields,
} from './CommunityFields';
import LoadingState from '../ui/LoadingState';

type EditCommunityFormProps = {
  communityId: string;
};

type Community = {
  id: string;
  name: string;
  address: string;
  city?: string;
  state?: string;
  zip_code?: string;
  status: string;
  total_lots: number;
  lots_under_control: number;
  absorption_rate?: number;
  active_listings?: number;
  months_supply?: number;
  avg_price_psf?: number;
  competitive_density?: number;
};

type ZipLookupState = 'idle' | 'loading' | 'found' | 'not_found' | 'queued' | 'error';

type CommunityFormSetters = {
  setCommunity: Dispatch<SetStateAction<Community | null>>;
  setName: Dispatch<SetStateAction<string>>;
  setAddress: Dispatch<SetStateAction<string>>;
  setCity: Dispatch<SetStateAction<string>>;
  setState: Dispatch<SetStateAction<string>>;
  setZipCode: Dispatch<SetStateAction<string>>;
  setOriginalZip: Dispatch<SetStateAction<string>>;
  setStatus: Dispatch<SetStateAction<string>>;
  setTotalLots: Dispatch<SetStateAction<string>>;
  setLotsUnderControl: Dispatch<SetStateAction<string>>;
  setAbsorptionRate: Dispatch<SetStateAction<string>>;
  setActiveListings: Dispatch<SetStateAction<string>>;
  setMonthsSupply: Dispatch<SetStateAction<string>>;
  setAvgPricePsf: Dispatch<SetStateAction<string>>;
  setCompetitiveDensity: Dispatch<SetStateAction<string>>;
};

type MarketMetricValues = {
  absorptionRate: string;
  activeListings: string;
  monthsSupply: string;
  avgPricePsf: string;
};

type MarketMetricSetters = {
  setAbsorptionRate: Dispatch<SetStateAction<string>>;
  setActiveListings: Dispatch<SetStateAction<string>>;
  setMonthsSupply: Dispatch<SetStateAction<string>>;
  setAvgPricePsf: Dispatch<SetStateAction<string>>;
};

type ZipLookupContext = {
  zipCode: string;
  originalZip: string;
  metricValues: MarketMetricValues;
  metricSetters: MarketMetricSetters;
  setAiFilledFields: Dispatch<SetStateAction<Set<string>>>;
  setZipLookupState: Dispatch<SetStateAction<ZipLookupState>>;
  setZipLookupMessage: Dispatch<SetStateAction<string>>;
};

type BasicFieldSetters = {
  name: Dispatch<SetStateAction<string>>;
  address: Dispatch<SetStateAction<string>>;
  status: Dispatch<SetStateAction<string>>;
  total_lots: Dispatch<SetStateAction<string>>;
  lots_under_control: Dispatch<SetStateAction<string>>;
};

type CommunityFormValues = {
  name: string;
  address: string;
  city: string;
  state: string;
  zipCode: string;
  status: string;
  totalLots: string;
  lotsUnderControl: string;
  absorptionRate: string;
  activeListings: string;
  monthsSupply: string;
  avgPricePsf: string;
  competitiveDensity: string;
};

const toMetricString = (value: number | null | undefined) =>
  value != null ? String(value) : '';

const applyCommunityData = (data: Community, setters: CommunityFormSetters) => {
  setters.setCommunity(data);
  setters.setName(data.name || '');
  setters.setAddress(data.address || '');
  setters.setCity(data.city || '');
  setters.setState(data.state || '');
  setters.setZipCode(data.zip_code || '');
  setters.setOriginalZip(data.zip_code || '');
  setters.setStatus(data.status || 'Active');
  setters.setTotalLots(String(data.total_lots || ''));
  setters.setLotsUnderControl(String(data.lots_under_control || ''));
  setters.setAbsorptionRate(toMetricString(data.absorption_rate));
  setters.setActiveListings(toMetricString(data.active_listings));
  setters.setMonthsSupply(toMetricString(data.months_supply));
  setters.setAvgPricePsf(toMetricString(data.avg_price_psf));
  setters.setCompetitiveDensity(toMetricString(data.competitive_density));
};

const fetchCommunityForEdit = async (communityId: string): Promise<Community> => {
  const response = await fetch(`/api/communities/${communityId}`);
  if (!response.ok) {
    throw new Error('Failed to fetch community');
  }
  return (await response.json()) as Community;
};

const shouldLookupZipCode = (zipCode: string, originalZip: string) =>
  !!zipCode && zipCode !== originalZip && /^\d{5}$/.test(zipCode);

const applyAutoFilledMetric = (
  incomingValue: number | null | undefined,
  currentValue: string,
  setter: Dispatch<SetStateAction<string>>,
  fieldName: string,
  aiFields: Set<string>,
) => {
  if (incomingValue == null || currentValue) {
    return;
  }
  setter(String(incomingValue));
  aiFields.add(fieldName);
};

const lookupMarketDataByZip = async ({
  zipCode,
  originalZip,
  metricValues,
  metricSetters,
  setAiFilledFields,
  setZipLookupState,
  setZipLookupMessage,
}: ZipLookupContext) => {
  if (!shouldLookupZipCode(zipCode, originalZip)) {
    return;
  }

  setZipLookupState('loading');
  setZipLookupMessage('');

  try {
    const response = await fetch(`/api/market-data/${zipCode}`);
    if (!response.ok) {
      throw new Error('Failed to lookup market data');
    }

    const result = await response.json();
    if (result.found && result.data) {
      const newAiFields = new Set<string>();
      applyAutoFilledMetric(
        result.data.absorption_rate,
        metricValues.absorptionRate,
        metricSetters.setAbsorptionRate,
        'absorptionRate',
        newAiFields,
      );
      applyAutoFilledMetric(
        result.data.active_listings,
        metricValues.activeListings,
        metricSetters.setActiveListings,
        'activeListings',
        newAiFields,
      );
      applyAutoFilledMetric(
        result.data.months_supply,
        metricValues.monthsSupply,
        metricSetters.setMonthsSupply,
        'monthsSupply',
        newAiFields,
      );
      applyAutoFilledMetric(
        result.data.avg_price_psf,
        metricValues.avgPricePsf,
        metricSetters.setAvgPricePsf,
        'avgPricePsf',
        newAiFields,
      );

      setAiFilledFields(newAiFields);
      setZipLookupState('found');
      setZipLookupMessage(`Market data found for ${zipCode}. Metrics auto-filled below.`);
      return;
    }

    const queueResponse = await fetch(`/api/market-data/${zipCode}`, { method: 'POST' });
    if (queueResponse.ok) {
      const queueResult = await queueResponse.json();
      setZipLookupState('queued');
      setZipLookupMessage(
        queueResult.message ||
          `Research queued for ${zipCode}. Data will be available after the next research cycle.`,
      );
      return;
    }

    setZipLookupState('not_found');
    setZipLookupMessage(`No market data available for ${zipCode}. You can enter metrics manually.`);
  } catch (err: any) {
    setZipLookupState('error');
    setZipLookupMessage(err.message || 'Failed to lookup market data');
  }
};

const applyBasicFieldChange = (
  fieldName: string,
  value: string,
  setters: BasicFieldSetters,
) => {
  if (!(fieldName in setters)) {
    return;
  }
  setters[fieldName as keyof BasicFieldSetters](value);
};

const buildCommunityPayload = (values: CommunityFormValues) => ({
  name: values.name.trim(),
  address: values.address.trim(),
  city: values.city.trim() || null,
  state: values.state.trim() || null,
  zip_code: values.zipCode.trim() || null,
  status: values.status,
  total_lots: parseInt(values.totalLots, 10),
  lots_under_control: parseInt(values.lotsUnderControl, 10),
  absorption_rate: values.absorptionRate ? parseFloat(values.absorptionRate) : null,
  active_listings: values.activeListings ? parseInt(values.activeListings, 10) : null,
  months_supply: values.monthsSupply ? parseFloat(values.monthsSupply) : null,
  avg_price_psf: values.avgPricePsf ? parseFloat(values.avgPricePsf) : null,
  competitive_density: values.competitiveDensity ? parseFloat(values.competitiveDensity) : null,
});

const updateCommunity = async (communityId: string, values: CommunityFormValues) => {
  const response = await fetch(`/api/communities/${communityId}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(buildCommunityPayload(values)),
  });

  if (!response.ok) {
    const errorData = await response.json();
    throw new Error(errorData.error || 'Failed to update community');
  }
};

type ActiveZipLookupState = Exclude<ZipLookupState, 'idle'>;

const ZIP_LOOKUP_CONTAINER_CLASSES: Record<ActiveZipLookupState, string> = {
  loading: 'bg-gray-50 border border-gray-200',
  found: 'bg-green-50 border border-green-200',
  queued: 'bg-blue-50 border border-blue-200',
  not_found: 'bg-yellow-50 border border-yellow-200',
  error: 'bg-red-50 border border-red-200',
};

const ZIP_LOOKUP_TEXT_CLASSES: Record<ActiveZipLookupState, string> = {
  loading: 'text-gray-600',
  found: 'text-green-700',
  queued: 'text-blue-700',
  not_found: 'text-yellow-700',
  error: 'text-red-700',
};

const ZipLookupIcon = ({ state }: { state: ActiveZipLookupState }) => {
  if (state === 'loading') {
    return (
      <div className="w-4 h-4 border-2 border-t-brand border-gray-200 rounded-full animate-spin mr-2" />
    );
  }
  if (state === 'found') return <span className="mr-2 text-green-600">✓</span>;
  if (state === 'queued') return <span className="mr-2 text-blue-600">ℹ</span>;
  if (state === 'not_found') return <span className="mr-2 text-yellow-600">!</span>;
  return <span className="mr-2 text-red-600">✕</span>;
};

const ZipLookupStatusBanner = ({
  state,
  message,
}: {
  state: ActiveZipLookupState;
  message: string;
}) => (
  <div className={`rounded-lg p-3 ${ZIP_LOOKUP_CONTAINER_CLASSES[state]}`}>
    <div className="flex items-center">
      <ZipLookupIcon state={state} />
      <span className={`text-sm ${ZIP_LOOKUP_TEXT_CLASSES[state]}`}>
        {state === 'loading' ? 'Looking up market data...' : message}
      </span>
    </div>
  </div>
);

const AiFieldBadge = ({ visible }: { visible: boolean }) => {
  if (!visible) return null;
  return (
    <span className="ml-2 px-2 py-0.5 bg-purple-100 text-purple-700 text-xs rounded-full font-medium">
