  const [absorptionRate, setAbsorptionRate] = useState('');
  const [activeListings, setActiveListings] = useState('');
  const [monthsSupply, setMonthsSupply] = useState('');
  const [avgPricePsf, setAvgPricePsf] = useState('');
  const [competitiveDensity, setCompetitiveDensity] = useState('');

