    const loadCommunity = async () => {
      try {
        setLoadingData(true);
        const data = await fetchCommunityForEdit(communityId);
        applyCommunityData(data, {
          setCommunity,
          setName,
          setAddress,
          setCity,
          setState,
          setZipCode,
          setOriginalZip,
          setStatus,
          setTotalLots,
          setLotsUnderControl,
          setAbsorptionRate,
          setActiveListings,
          setMonthsSupply,
          setAvgPricePsf,
          setCompetitiveDensity,
