import { useState, useEffect, type Dispatch } from 'react';

interface FloorPlan {
  id: string;
  name: string;
  plan_code?: string;
  square_feet: number;
  bedrooms: number;
  bathrooms_full: number;
  bathrooms_half: number;
  stories: number;
  garage_bays?: number;
}

interface CommunityFloorPlan {
  id: string;
  community_id: string;
  floor_plan_id: string;
  base_cost: number;
  base_price: number;
  target_persona?: string;
  standard_option_ids: string[];
  additional_available_option_ids: string[];
  status: string;
  floor_plan: FloorPlan;
}

interface FloorPlanCardsProps {
  communityId: string;
  selectedPlan: CommunityFloorPlan | null;
  onSelect: Dispatch<CommunityFloorPlan>;
}

export default function FloorPlanCards({ communityId, selectedPlan, onSelect }: FloorPlanCardsProps) {
  const [plans, setPlans] = useState<CommunityFloorPlan[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filters, setFilters] = useState({ beds: 'all', sortBy: 'name' });

  useEffect(() => {
    if (communityId) {
      fetchPlans();
    }
  }, [communityId]);

  async function fetchPlans() {
    try {
      setLoading(true);
      const response = await fetch(`/api/community-floor-plans?communityId=${communityId}`);
      if (!response.ok) throw new Error('Failed to fetch floor plans');
      const data = await response.json();
      setPlans(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load floor plans');
    } finally {
      setLoading(false);
    }
  }

  const filteredPlans = plans
    .filter((p) => {
      if (filters.beds !== 'all') {
        return p.floor_plan.bedrooms === parseInt(filters.beds);
      }
      return true;
    })
    .sort((a, b) => {
      switch (filters.sortBy) {
        case 'price':
          return a.base_price - b.base_price;
        case 'sqft':
          return a.floor_plan.square_feet - b.floor_plan.square_feet;
        case 'beds':
          return a.floor_plan.bedrooms - b.floor_plan.bedrooms;
        default:
          return a.floor_plan.name.localeCompare(b.floor_plan.name);
      }
    });

  const uniqueBedCounts = [...new Set(plans.map((p) => p.floor_plan.bedrooms))].sort();

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="inline-block h-8 w-8 animate-spin rounded-full border-4 border-solid border-brand border-r-transparent"></div>
        <span className="ml-3 text-ink-muted">Loading floor plans...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 border border-red-200 rounded-lg p-4 text-red-700">
        {error}
      </div>
    );
  }

  if (plans.length === 0) {
    return (
      <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-6 text-center">
        <h3 className="text-lg font-medium text-yellow-800 mb-2">No Floor Plans Assigned</h3>
        <p className="text-yellow-700 mb-4">
          This community doesn't have any floor plans assigned yet.
          Assign floor plans from your library first.
        </p>
        <a
          href={`/communities/${communityId}`}
          className="inline-flex items-center px-4 py-2 bg-brand text-white rounded-lg hover:bg-brand-hover transition-colors ease-out"
        >
          Go to Community
        </a>
      </div>
    );
  }

  return (
    <div>
      <h2 className="text-xl font-semibold text-ink mb-2">Select Floor Plan</h2>
      <p className="text-ink-muted mb-4">
        Choose a floor plan for this spec home. Prices shown are community-specific.
      </p>

      {/* Filters */}
      <div className="flex flex-wrap gap-4 mb-6">
        <div>
          <label className="block text-xs text-ink-muted mb-1">Bedrooms</label>
          <select
            value={filters.beds}
            onChange={(e) => setFilters({ ...filters, beds: e.target.value })}
            className="px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-brand focus:border-transparent"
          >
            <option value="all">All</option>
            {uniqueBedCounts.map((beds) => (
              <option key={beds} value={beds}>
                {beds} BR
              </option>
            ))}
          </select>
        </div>
        <div>
          <label className="block text-xs text-ink-muted mb-1">Sort By</label>
          <select
            value={filters.sortBy}
            onChange={(e) => setFilters({ ...filters, sortBy: e.target.value })}
            className="px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-brand focus:border-transparent"
          >
            <option value="name">Name</option>
            <option value="price">Price</option>
            <option value="sqft">Square Feet</option>
            <option value="beds">Bedrooms</option>
          </select>
        </div>
      </div>

      {/* Floor Plan Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredPlans.map((cfp) => {
          const isSelected = selectedPlan?.id === cfp.id;
          const fp = cfp.floor_plan;
          const bathrooms = fp.bathrooms_full + (fp.bathrooms_half * 0.5);

          return (
            <button
              key={cfp.id}
              onClick={() => onSelect(cfp)}
              className={`text-left p-4 rounded-lg border-2 transition-all ease-out ${
                isSelected
                  ? 'border-brand bg-brand/5 ring-2 ring-brand/20'
                  : 'border-gray-200 hover:border-brand/50 hover:bg-gray-50'
              }`}
            >
              <div className="flex items-start justify-between mb-3">
                <div>
                  <h3 className="font-semibold text-ink">{fp.name}</h3>
                  {fp.plan_code && (
                    <span className="text-xs text-ink-muted">({fp.plan_code})</span>
                  )}
                </div>
                {isSelected && (
                  <span className="flex-shrink-0 w-5 h-5 bg-brand rounded-full flex items-center justify-center">
                    <svg className="w-3 h-3 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                    </svg>
                  </span>
                )}
              </div>

              {/* Specs */}
              <div className="flex items-center gap-3 text-sm text-ink-muted mb-3">
                <span>{fp.square_feet.toLocaleString()} sqft</span>
                <span className="text-gray-300">|</span>
                <span>{fp.bedrooms} BR / {bathrooms} BA</span>
                {fp.stories > 1 && (
                  <>
                    <span className="text-gray-300">|</span>
                    <span>{fp.stories} Story</span>
                  </>
                )}
              </div>

              {/* Price */}
              <div className="flex items-baseline justify-between mb-3">
                <span className="text-2xl font-bold text-ink">
                  ${cfp.base_price.toLocaleString()}
                </span>
                <span className="text-sm text-ink-muted">
                  ${Math.round(cfp.base_price / fp.square_feet)}/sqft
                </span>
              </div>

              {/* Standard Options */}
              {cfp.standard_option_ids && cfp.standard_option_ids.length > 0 && (
                <div className="pt-3 border-t border-gray-100">
                  <p className="text-xs text-ink-muted mb-1">
                    Includes {cfp.standard_option_ids.length} standard option{cfp.standard_option_ids.length !== 1 ? 's' : ''}
                  </p>
                </div>
              )}

              {/* Target Persona */}
              {cfp.target_persona && (
                <div className="mt-2">
                  <span className="inline-block px-2 py-1 bg-purple-100 text-purple-700 text-xs rounded-full">
                    {cfp.target_persona}
                  </span>
                </div>
              )}
            </button>
          );
        })}
      </div>

      {filteredPlans.length === 0 && (
        <div className="text-center py-8 text-ink-muted">
          No floor plans match your filters. Try adjusting the filters above.
        </div>
      )}
    </div>
  );
}

