function P3ImpactBadge({ impact, type }: { impact: number; type: 'pace' | 'profit' | 'persona' }) {
  if (impact === 0) return null;
  const colors = {
    pace: impact > 0 ? 'bg-blue-100 text-blue-700' : 'bg-blue-50 text-blue-400',
    profit: impact > 0 ? 'bg-green-100 text-green-700' : 'bg-green-50 text-green-400',
    persona: impact > 0 ? 'bg-purple-100 text-purple-700' : 'bg-purple-50 text-purple-400',
  };
  const labels = { pace: 'Pace', profit: 'Profit', persona: 'Persona' };

  return (
    <span className={`text-xs px-1.5 py-0.5 rounded ${colors[type]}`}>
      {impact > 0 ? '+' : ''}{impact} {labels[type]}
    </span>
  );

