import { useState, useEffect, type Dispatch } from 'react';
import { P3_PRESETS } from '../../../lib/p3Engine';

interface P3Weights {
  pace: number;
  profit: number;
  persona: number;
}

interface P3WeightSlidersProps {
  weights: P3Weights;
  selectedPreset: string | null;
  onWeightsChange: Dispatch<{ weights: P3Weights; preset: string | null }>;
}

const PRESET_INFO = {
  speedDemon: { icon: '🚀', label: 'Speed Demon' },
  marginMaster: { icon: '💰', label: 'Margin Master' },
  personaPerfect: { icon: '🎯', label: 'Persona Perfect' },
  balanced: { icon: '⚖️', label: 'Balanced' },
  hotMarket: { icon: '🔥', label: 'Hot Market' },
  slowMarket: { icon: '🐢', label: 'Slow Market' },
};

export default function P3WeightSliders({ weights, selectedPreset, onWeightsChange }: P3WeightSlidersProps) {
  const [localWeights, setLocalWeights] = useState<P3Weights>(weights);
  const [activeSlider, setActiveSlider] = useState<keyof P3Weights | null>(null);

  const total = localWeights.pace + localWeights.profit + localWeights.persona;
  const isValid = total === 100;

  useEffect(() => {
    setLocalWeights(weights);
  }, [weights]);

  const handleSliderChange = (key: keyof P3Weights, value: number) => {
    const newWeights = { ...localWeights, [key]: value };
    setLocalWeights(newWeights);

    const newTotal = newWeights.pace + newWeights.profit + newWeights.persona;
    if (newTotal === 100) {
      onWeightsChange({ weights: newWeights, preset: null });
    }
  };

  const handlePresetSelect = (presetKey: string) => {
    const preset = P3_PRESETS[presetKey as keyof typeof P3_PRESETS];
    if (preset) {
      const newWeights = { pace: preset.pace, profit: preset.profit, persona: preset.persona };
      setLocalWeights(newWeights);
      onWeightsChange({ weights: newWeights, preset: presetKey });
    }
  };

  const autoBalance = () => {
    const remaining = 100 - localWeights[activeSlider!];
    const otherKeys = Object.keys(localWeights).filter(k => k !== activeSlider) as (keyof P3Weights)[];
    const each = Math.floor(remaining / 2);
    const newWeights = {
      ...localWeights,
      [otherKeys[0]]: each,
      [otherKeys[1]]: remaining - each,
    };
    setLocalWeights(newWeights);
    onWeightsChange({ weights: newWeights, preset: null });
  };

  return (
    <div>
      <h2 className="text-xl font-semibold text-ink mb-2">Configure Your P3 Strategy</h2>
      <p className="text-ink-muted mb-6">
        Set your priorities for Pace, Profit, and Persona. Weights must total 100%.
      </p>

      {/* Presets */}
      <div className="mb-8">
        <h3 className="text-sm font-medium text-ink-muted mb-3">Quick Presets</h3>
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3">
          {Object.entries(P3_PRESETS).map(([key]) => {
            const info = PRESET_INFO[key as keyof typeof PRESET_INFO];
            const isSelected = selectedPreset === key;

            return (
              <button
                key={key}
                onClick={() => handlePresetSelect(key)}
                className={`p-3 rounded-lg border-2 transition-all ease-out text-center ${
                  isSelected
                    ? 'border-brand bg-brand/5'
                    : 'border-gray-200 bg-white hover:border-brand/50'
                }`}
              >
                <div className="text-xl mb-1">{info.icon}</div>
                <div className={`text-xs font-medium ${isSelected ? 'text-brand' : 'text-ink'}`}>
                  {info.label}
                </div>
              </button>
            );
          })}
        </div>
      </div>

      {/* Sliders */}
      <div className="bg-white rounded-lg border border-gray-200 p-6 mb-6">
        <div className="space-y-6">
          {/* Pace */}
          <div>
            <div className="flex justify-between items-center mb-2">
              <div>
                <span className="font-medium text-ink">Pace</span>
                <span className="text-sm text-ink-muted ml-2">(Sales Velocity)</span>
              </div>
              <span className={`text-lg font-bold ${localWeights.pace > 50 ? 'text-blue-600' : 'text-ink'}`}>
                {localWeights.pace}%
              </span>
            </div>
            <input
              type="range"
              min="10"
              max="80"
              value={localWeights.pace}
              onChange={(e) => handleSliderChange('pace', parseInt(e.target.value))}
              onFocus={() => setActiveSlider('pace')}
              className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-600"
            />
            <p className="text-xs text-ink-muted mt-1">
              Higher = Prioritize faster sales and lower DOM
            </p>
          </div>

          {/* Profit */}
          <div>
            <div className="flex justify-between items-center mb-2">
              <div>
                <span className="font-medium text-ink">Profit</span>
                <span className="text-sm text-ink-muted ml-2">(Margin Protection)</span>
              </div>
              <span className={`text-lg font-bold ${localWeights.profit > 50 ? 'text-green-600' : 'text-ink'}`}>
                {localWeights.profit}%
              </span>
            </div>
            <input
              type="range"
              min="10"
              max="80"
              value={localWeights.profit}
              onChange={(e) => handleSliderChange('profit', parseInt(e.target.value))}
              onFocus={() => setActiveSlider('profit')}
              className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-green-600"
            />
            <p className="text-xs text-ink-muted mt-1">
              Higher = Prioritize gross profit margin %
            </p>
          </div>

          {/* Persona */}
          <div>
            <div className="flex justify-between items-center mb-2">
              <div>
                <span className="font-medium text-ink">Persona</span>
                <span className="text-sm text-ink-muted ml-2">(Buyer Fit)</span>
              </div>
              <span className={`text-lg font-bold ${localWeights.persona > 50 ? 'text-purple-600' : 'text-ink'}`}>
                {localWeights.persona}%
              </span>
            </div>
            <input
              type="range"
              min="10"
              max="80"
              value={localWeights.persona}
              onChange={(e) => handleSliderChange('persona', parseInt(e.target.value))}
              onFocus={() => setActiveSlider('persona')}
              className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-purple-600"
            />
            <p className="text-xs text-ink-muted mt-1">
              Higher = Prioritize matching ideal buyer profile
            </p>
          </div>
        </div>
      </div>

      {/* Total Indicator */}
      <div className={`p-4 rounded-lg border-2 ${
        isValid
          ? 'bg-green-50 border-green-200'
          : 'bg-red-50 border-red-200'
      }`}>
        <div className="flex items-center justify-between">
          <div className="flex items-center">
            {isValid ? (
              <svg className="w-5 h-5 text-green-600 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
              </svg>
            ) : (
              <svg className="w-5 h-5 text-red-600 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
              </svg>
            )}
            <span className={`font-medium ${isValid ? 'text-green-700' : 'text-red-700'}`}>
              Total: {total}%
            </span>
          </div>
          {!isValid && activeSlider && (
            <button
              onClick={autoBalance}
              className="text-sm text-brand hover:text-brand-hover font-medium"
            >
              Auto-balance
            </button>
          )}
        </div>
        {!isValid && (
          <p className="text-sm text-red-600 mt-2">
            Adjust sliders so weights total exactly 100%
          </p>
        )}
      </div>

      {/* Selected preset description */}
      {selectedPreset && P3_PRESETS[selectedPreset as keyof typeof P3_PRESETS] && (
        <div className="mt-4 p-3 bg-brand/5 border border-brand/20 rounded-lg">
          <p className="text-sm text-ink">
            <span className="font-medium">Strategy:</span>{' '}
            {P3_PRESETS[selectedPreset as keyof typeof P3_PRESETS].reason}
          </p>
        </div>
      )}
    </div>
  );
}

