import { useState, type Dispatch } from 'react';

interface Community {
  id: string;
  name: string;
}

interface FloorPlan {
  id: string;
  name: string;
  square_feet: number;
  bedrooms: number;
  bathrooms_full: number;
  bathrooms_half: number;
}

interface CommunityFloorPlan {
  id: string;
  base_price: number;
  floor_plan: FloorPlan;
}

interface Lot {
  id: string;
  lot_number: string;
  width: number;
  depth: number;
  premium_price: number;
}

interface Option {
  id: string;
  option_code: string;
  description: string;
  default_price_adder: number;
}

interface P3Weights {
  pace: number;
  profit: number;
  persona: number;
}

interface P3Results {
  paceScore: number;
  profitScore: number;
  personaScore: number;
  weightedScore: number;
  predictedDomDays: number;
  predictedMarginPct: number;
  totalCost: number;
  totalPrice: number;
  gpDollars: number;
}

interface DecisionFinalizeProps {
  community: Community;
  communityFloorPlan: CommunityFloorPlan;
  lot: Lot;
  standardOptions: Option[];
  selectedOptions: Option[];
  weights: P3Weights;
  weightsPreset: string | null;
  results: P3Results;
  onSave: Dispatch<string>;
  onStartOver: () => void;
}

export default function DecisionFinalize({
  community,
  communityFloorPlan,
  lot,
  standardOptions,
  selectedOptions,
  weights,
  weightsPreset,
  results,
  onSave,
  onStartOver,
}: DecisionFinalizeProps) {
  const [notes, setNotes] = useState('');
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fp = communityFloorPlan.floor_plan;
  const bathrooms = fp.bathrooms_full + (fp.bathrooms_half * 0.5);
  const optionsPriceAdd = selectedOptions.reduce((sum, opt) => sum + opt.default_price_adder, 0);

  const handleSave = async () => {
    setSaving(true);
    setError(null);
    try {
      await onSave(notes);
      setSaved(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save decision');
    } finally {
      setSaving(false);
    }
  };

  if (saved) {
    return (
      <div className="text-center space-y-6 py-8">
        <div className="text-6xl">✅</div>
        <h2 className="text-3xl font-semibold text-ink">Decision Saved!</h2>
        <p className="text-ink-muted">
          Your spec decision has been saved successfully.
        </p>
        <div className="bg-white border border-gray-200 rounded-lg p-6 max-w-md mx-auto">
          <div className="space-y-3 text-left">
            <div className="flex items-center justify-between">
              <span className="text-ink-muted">Floor Plan:</span>
              <span className="font-semibold text-ink">{fp.name}</span>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-ink-muted">Lot:</span>
              <span className="font-semibold text-ink">{lot.lot_number}</span>
            </div>
            <div className="flex items-center justify-between border-t border-gray-100 pt-3">
              <span className="text-ink-muted">Total Price:</span>
              <span className="font-bold text-xl text-green-600">${results.totalPrice.toLocaleString()}</span>
            </div>
          </div>
        </div>
        <div className="flex items-center justify-center space-x-4 pt-4">
          <button
            onClick={onStartOver}
            className="px-6 py-2 border-2 border-brand text-brand rounded-lg font-medium hover:bg-orange-50 transition-colors ease-out"
          >
            Start New Wizard
          </button>
          <a
            href={`/communities/${community.id}`}
            className="px-6 py-2 bg-brand text-white rounded-lg font-medium hover:bg-brand-hover transition-colors ease-out"
          >
            View Community
          </a>
        </div>
      </div>
    );
  }

  return (
    <div>
      <h2 className="text-xl font-semibold text-ink mb-2">Review & Save Decision</h2>
      <p className="text-ink-muted mb-6">
        Review your spec configuration and save your decision.
      </p>

      {/* Summary Card */}
      <div className="bg-white rounded-lg border border-gray-200 overflow-hidden mb-6">
        {/* Header */}
        <div className="bg-brand text-white p-4">
          <h3 className="text-lg font-bold">{fp.name}</h3>
          <p className="text-white/80">
            {community.name} · Lot {lot.lot_number}
          </p>
        </div>

        {/* Details */}
        <div className="p-4 space-y-4">
          {/* Floor Plan Details */}
          <div>
            <h4 className="text-sm font-medium text-ink-muted mb-2">Floor Plan</h4>
            <div className="flex flex-wrap gap-3 text-sm">
              <span className="px-2 py-1 bg-gray-100 rounded">{fp.square_feet.toLocaleString()} sqft</span>
              <span className="px-2 py-1 bg-gray-100 rounded">{fp.bedrooms} BR / {bathrooms} BA</span>
              <span className="px-2 py-1 bg-gray-100 rounded">Base: ${communityFloorPlan.base_price.toLocaleString()}</span>
            </div>
          </div>

          {/* Lot Details */}
          <div>
            <h4 className="text-sm font-medium text-ink-muted mb-2">Lot</h4>
            <div className="flex flex-wrap gap-3 text-sm">
              <span className="px-2 py-1 bg-gray-100 rounded">Lot {lot.lot_number}</span>
              <span className="px-2 py-1 bg-gray-100 rounded">{lot.width}'×{lot.depth}'</span>
              {lot.premium_price > 0 ? (
                <span className="px-2 py-1 bg-gray-100 rounded">+${lot.premium_price.toLocaleString()} premium</span>
              ) : (
                <span className="px-2 py-1 bg-green-100 text-green-700 rounded">No premium</span>
