import { useState, useEffect, type Dispatch } from 'react';
import EmptyState from '../../ui/EmptyState';

interface Option {
  id: string;
  option_code: string;
  description: string;
  category: string;
  subcategory?: string;
  base_cost: number;
  default_price_adder: number;
  p3_impact_pace: number;
  p3_impact_profit: number;
  p3_impact_persona: number;
}

interface CommunityFloorPlan {
  id: string;
  standard_option_ids: string[];
  additional_available_option_ids: string[];
  floor_plan: {
    available_option_ids?: string[];
  };
}

interface OptionCheckboxesProps {
  communityFloorPlan: CommunityFloorPlan;
  selectedOptionIds: string[];
  onSelectionChange: Dispatch<{ optionIds: string[]; options: Option[] }>;
}

export default function OptionCheckboxes({
  communityFloorPlan,
  selectedOptionIds,
  onSelectionChange,
}: OptionCheckboxesProps) {
  const [allOptions, setAllOptions] = useState<Option[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [expandedCategories, setExpandedCategories] = useState<Set<string>>(new Set());

  useEffect(() => {
    fetchOptions();
  }, [communityFloorPlan]);

  async function fetchOptions() {
    try {
      setLoading(true);
      const response = await fetch('/api/option-library');
      if (!response.ok) throw new Error('Failed to fetch options');
      const data = await response.json();
      setAllOptions(data);

      // Auto-expand categories with selected options
      const categories = new Set<string>();
      data.forEach((opt: Option) => {
        if (selectedOptionIds.includes(opt.id)) {
          categories.add(opt.category);
        }
      });
      setExpandedCategories(categories);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load options');
    } finally {
      setLoading(false);
    }
  }

  // Get all available option IDs for this floor plan
  const allAvailableIds = new Set([
    ...(communityFloorPlan.floor_plan.available_option_ids || []),
    ...(communityFloorPlan.additional_available_option_ids || []),
  ]);

  const standardIds = new Set(communityFloorPlan.standard_option_ids || []);

  // Filter to only available options
  const availableOptions = allOptions.filter((opt) => allAvailableIds.has(opt.id));

  // Separate standard vs optional
  const standardOptions = availableOptions.filter((opt) => standardIds.has(opt.id));
  const optionalOptions = availableOptions.filter((opt) => !standardIds.has(opt.id));

  // Group optional by category
  const optionsByCategory = optionalOptions.reduce((acc, opt) => {
    if (!acc[opt.category]) acc[opt.category] = [];
    acc[opt.category].push(opt);
    return acc;
  }, {} as Record<string, Option[]>);

  const categories = Object.keys(optionsByCategory).sort();

  // Calculate totals
  const selectedOptions = optionalOptions.filter((opt) => selectedOptionIds.includes(opt.id));
  const totalAddedCost = selectedOptions.reduce((sum, opt) => sum + opt.base_cost, 0);
  const totalPriceIncrease = selectedOptions.reduce((sum, opt) => sum + opt.default_price_adder, 0);

  const toggleOption = (optionId: string) => {
    let newIds: string[];
    if (selectedOptionIds.includes(optionId)) {
      newIds = selectedOptionIds.filter((id) => id !== optionId);
    } else {
      newIds = [...selectedOptionIds, optionId];
    }
    const newOptions = optionalOptions.filter((opt) => newIds.includes(opt.id));
    onSelectionChange({ optionIds: newIds, options: newOptions });
  };

  const toggleCategory = (category: string) => {
    const newExpanded = new Set(expandedCategories);
    if (newExpanded.has(category)) {
      newExpanded.delete(category);
    } else {
      newExpanded.add(category);
    }
    setExpandedCategories(newExpanded);
  };

  function P3ImpactBadge({ impact, type }: { impact: number; type: 'pace' | 'profit' | 'persona' }) {
    if (impact === 0) return null;
    const colors = {
      pace: impact > 0 ? 'bg-blue-100 text-blue-700' : 'bg-blue-50 text-blue-400',
      profit: impact > 0 ? 'bg-green-100 text-green-700' : 'bg-green-50 text-green-400',
      persona: impact > 0 ? 'bg-purple-100 text-purple-700' : 'bg-purple-50 text-purple-400',
    };
    const labels = { pace: 'Pace', profit: 'Profit', persona: 'Persona' };

    return (
      <span className={`text-xs px-1.5 py-0.5 rounded ${colors[type]}`}>
        {impact > 0 ? '+' : ''}{impact} {labels[type]}
      </span>
    );
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="inline-block h-8 w-8 animate-spin rounded-full border-4 border-solid border-brand border-r-transparent"></div>
        <span className="ml-3 text-ink-muted">Loading options...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 border border-red-200 rounded-lg p-4 text-red-700">
        {error}
      </div>
    );
  }

  return (
    <div>
      <h2 className="text-xl font-semibold text-ink mb-2">Select Options</h2>
      <p className="text-ink-muted mb-4">
        Choose optional upgrades for this spec. Standard options are already included.
      </p>

      {/* Running Total */}
      <div className="bg-brand/5 border border-brand/20 rounded-lg p-4 mb-6">
        <div className="flex justify-between items-center">
          <div>
            <span className="text-sm text-ink-muted">Selected Upgrades:</span>
            <span className="ml-2 font-semibold text-ink">{selectedOptions.length}</span>
          </div>
          <div className="text-right">
            <div className="text-sm text-ink-muted">
              Added Cost: <span className="font-medium text-ink">${totalAddedCost.toLocaleString()}</span>
            </div>
            <div className="text-sm text-ink-muted">
              Price Increase: <span className="font-medium text-green-600">+${totalPriceIncrease.toLocaleString()}</span>
            </div>
          </div>
        </div>
      </div>

      {/* Standard Options */}
      {standardOptions.length > 0 && (
        <div className="mb-6">
          <h3 className="text-sm font-medium text-ink-muted mb-3 flex items-center">
            <svg className="w-4 h-4 mr-1 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
            </svg>
            Standard Options (Included in Base Price)
          </h3>
          <div className="bg-green-50 border border-green-200 rounded-lg p-3">
            <div className="flex flex-wrap gap-2">
              {standardOptions.map((opt) => (
                <span
                  key={opt.id}
                  className="inline-flex items-center px-3 py-1 bg-white border border-green-300 rounded-full text-sm text-green-800"
                >
                  <svg className="w-3 h-3 mr-1" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                  </svg>
                  {opt.description}
                </span>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Optional Upgrades by Category */}
      {categories.length === 0 ? (
        <EmptyState
          message="No options available"
          description="No optional upgrades available for this floor plan."
          component="OptionCheckboxes"
        />
      ) : (
        <div className="space-y-4">
          {categories.map((category) => {
            const categoryOptions = optionsByCategory[category];
            const isExpanded = expandedCategories.has(category);
            const selectedInCategory = categoryOptions.filter((opt) =>
              selectedOptionIds.includes(opt.id)
            ).length;

            return (
              <div key={category} className="border border-gray-200 rounded-lg overflow-hidden">
                <button
                  onClick={() => toggleCategory(category)}
                  className="w-full flex items-center justify-between p-4 bg-gray-50 hover:bg-gray-100 transition-colors ease-out"
                >
                  <div className="flex items-center">
                    <svg
                      className={`w-4 h-4 mr-2 text-ink-muted transition-transform ease-out ${isExpanded ? 'rotate-90' : ''}`}
                      fill="none"
                      stroke="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                    </svg>
                    <span className="font-medium text-ink">{category}</span>
                    <span className="ml-2 text-sm text-ink-muted">
                      ({categoryOptions.length} option{categoryOptions.length !== 1 ? 's' : ''})
                    </span>
                  </div>
                  {selectedInCategory > 0 && (
                    <span className="px-2 py-1 bg-brand text-white text-xs rounded-full">
                      {selectedInCategory} selected
                    </span>
                  )}
                </button>

                {isExpanded && (
                  <div className="p-4 space-y-3">
                    {categoryOptions.map((opt) => {
                      const isSelected = selectedOptionIds.includes(opt.id);

                      return (
                        <label
                          key={opt.id}
                          className={`flex items-start p-3 rounded-lg border-2 cursor-pointer transition-all ease-out ${
                            isSelected
                              ? 'border-brand bg-brand/5'
                              : 'border-gray-200 hover:border-gray-300'
                          }`}
                        >
                          <input
                            type="checkbox"
                            checked={isSelected}
                            onChange={() => toggleOption(opt.id)}
                            className="mt-1 w-4 h-4 text-brand border-gray-300 rounded focus:ring-brand"
                          />
                          <div className="ml-3 flex-1">
                            <div className="flex items-start justify-between">
                              <div>
                                <span className="font-medium text-ink">{opt.description}</span>
                                <span className="ml-2 text-xs text-ink-muted">({opt.option_code})</span>
                              </div>
                              <div className="text-right ml-4">
                                <div className="text-sm font-medium text-ink">
                                  +${opt.default_price_adder.toLocaleString()}
                                </div>
                                <div className="text-xs text-ink-muted">
                                  Cost: ${opt.base_cost.toLocaleString()}
                                </div>
                              </div>
                            </div>
                            <div className="flex flex-wrap gap-1 mt-2">
                              <P3ImpactBadge impact={opt.p3_impact_pace} type="pace" />
                              <P3ImpactBadge impact={opt.p3_impact_profit} type="profit" />
                              <P3ImpactBadge impact={opt.p3_impact_persona} type="persona" />
                            </div>
                          </div>
                        </label>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState, type ReactNode } from 'react';

interface Community {
  id: string;
  name: string;
  zip?: string;
  absorption_rate?: number;
  active_listings?: number;
  months_supply?: number;
  avg_price_psf?: number;
  competitive_density?: number;
}

interface AIMarketInsights {
  marketAssessment: string;
  opportunities: string[];
  risks: string[];
  recommendedP3Bias: 'pace' | 'profit' | 'persona' | 'balanced';
  narrative: string;
  cached?: boolean;
  updatedAt?: string;
}

interface MarketInsightsDisplayProps {
  community: Community;
}

type Bias = AIMarketInsights['recommendedP3Bias'];

const BIAS_DETAILS: Record<Bias, { icon: string; label: string }> = {
  pace: { icon: '🚀', label: 'Prioritize Pace' },
  profit: { icon: '💰', label: 'Prioritize Profit' },
  persona: { icon: '🎯', label: 'Prioritize Persona' },
  balanced: { icon: '⚖️', label: 'Balanced Approach' },
};

function getMarketAssessment(community: Community): { label: string; color: string; description: string } {
  const absorption = community.absorption_rate || 0;
  const monthsSupply = community.months_supply || 6;

  if (absorption >= 3 && monthsSupply < 4) {
    return {
      label: 'Hot Market',
      color: 'bg-red-100 text-red-800 border-red-200',
      description: 'High demand, low inventory. Consider prioritizing pace to capture market momentum.',
    };
  } else if (absorption >= 2 && monthsSupply < 6) {
    return {
      label: 'Active Market',
      color: 'bg-orange-100 text-orange-800 border-orange-200',
      description: 'Balanced demand and supply. Good conditions for spec building.',
    };
  } else if (absorption >= 1.5) {
    return {
      label: 'Moderate Market',
      color: 'bg-yellow-100 text-yellow-800 border-yellow-200',
      description: 'Steady activity. Focus on differentiation through persona targeting.',
    };
  } else {
    return {
      label: 'Slow Market',
      color: 'bg-blue-100 text-blue-800 border-blue-200',
      description: 'Lower absorption. Prioritize margins and perfect buyer matching.',
    };
  }
}

function MetricCard({ label, value, subtext, icon }: { label: string; value: string; subtext?: string; icon: ReactNode }) {
  return (
    <div className="bg-white rounded-lg border border-gray-200 p-4">
      <div className="flex items-start justify-between">
        <div>
          <p className="text-sm text-ink-muted mb-1">{label}</p>
          <p className="text-2xl font-bold text-ink">{value}</p>
          {subtext && <p className="text-xs text-ink-muted mt-1">{subtext}</p>}
        </div>
        <div className="text-brand opacity-50">{icon}</div>
      </div>
    </div>
  );
}

function competitiveDensityMessage(value: number): string {
  if (value > 7) return 'High competition - differentiation is critical';
  if (value > 4) return 'Moderate competition - standard positioning should work';
  return 'Low competition - opportunity for premium pricing';
}

type AiInsightsSectionProps = {
  zip?: string;
  insights: AIMarketInsights | null;
  loading: boolean;
  error: string | null;
  onRetry: () => void;
};

function AiInsightsBody({ insights }: { insights: AIMarketInsights }) {
  const biasDetail = insights ? BIAS_DETAILS[insights.recommendedP3Bias] : null;

  return (
    <div className="space-y-4">
      <p className="text-sm text-blue-900">{insights.narrative}</p>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
        {insights.opportunities.length > 0 && (
          <div className="bg-green-50 rounded-lg p-3 border border-green-200">
            <h4 className="text-xs font-semibold text-green-800 uppercase tracking-wide mb-2">Opportunities</h4>
            <ul className="space-y-1">
              {insights.opportunities.map((opportunity, index) => (
                <li key={index} className="text-sm text-green-700 flex items-start">
                  <span className="text-green-500 mr-1">✓</span>
                  {opportunity}
                </li>
              ))}
            </ul>
          </div>
        )}
        {insights.risks.length > 0 && (
          <div className="bg-amber-50 rounded-lg p-3 border border-amber-200">
            <h4 className="text-xs font-semibold text-amber-800 uppercase tracking-wide mb-2">Risks</h4>
            <ul className="space-y-1">
              {insights.risks.map((risk, index) => (
                <li key={index} className="text-sm text-amber-700 flex items-start">
                  <span className="text-amber-500 mr-1">!</span>
                  {risk}
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>

      {biasDetail && (
        <div className="flex items-center justify-between bg-white/50 rounded-lg p-3">
          <div>
            <span className="text-xs font-medium text-blue-700 uppercase tracking-wide">AI Recommendation</span>
            <p className="text-sm font-semibold text-blue-900">
              {biasDetail.icon} {biasDetail.label}
            </p>
          </div>
          <span className="text-xs text-blue-600">Based on current market conditions</span>
        </div>
      )}
    </div>
  );
}

function renderAiSectionContent(
  zip: string | undefined,
  insights: AIMarketInsights | null,
  loading: boolean,
  error: string | null,
  onRetry: () => void,
) {
  if (!zip) {
    return (
      <p className="text-sm text-blue-700">
        Add a ZIP code to this community to enable AI-powered market analysis.
      </p>
    );
  }

  if (loading) {
    return (
      <div className="flex items-center">
        <div className="inline-block h-4 w-4 animate-spin rounded-full border-2 border-solid border-blue-600 border-r-transparent mr-2"></div>
        <span className="text-sm text-blue-700">Analyzing market data...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="text-sm text-red-600">
        {error}
        <button onClick={onRetry} className="ml-2 text-blue-600 hover:text-blue-800 underline">
          Retry
        </button>
      </div>
    );
  }

  if (!insights) {
    return (
      <p className="text-sm text-blue-700">
        AI analysis will appear here once market data is loaded.
      </p>
    );
  }

  return <AiInsightsBody insights={insights} />;
}

function AiInsightsSection({ zip, insights, loading, error, onRetry }: AiInsightsSectionProps) {
  return (
    <div className="mt-6 p-4 bg-gradient-to-r from-blue-50 to-blue-50 border border-blue-200 rounded-lg">
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center">
          <svg className="w-5 h-5 text-blue-600 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" />
          </svg>
          <span className="font-medium text-blue-800">AI Market Analysis</span>
        </div>
        {insights?.cached && (
          <span className="text-xs text-blue-600">
            Updated {insights.updatedAt ? new Date(insights.updatedAt).toLocaleDateString() : 'recently'}
          </span>
        )}
      </div>

      {renderAiSectionContent(zip, insights, loading, error, onRetry)}
    </div>
  );
}

export default function MarketInsightsDisplay({ community }: MarketInsightsDisplayProps) {
  const [aiInsights, setAiInsights] = useState<AIMarketInsights | null>(null);
  const [aiLoading, setAiLoading] = useState(false);
  const [aiError, setAiError] = useState<string | null>(null);

  const assessment = getMarketAssessment(community);
  const hasMarketData = community.absorption_rate || community.months_supply || community.avg_price_psf;

  // Fetch AI insights when community has a zip code
  useEffect(() => {
    if (community.zip) {
      fetchAIInsights(community.zip);
    }
  }, [community.zip]);

  async function fetchAIInsights(zipcode: string) {
    setAiLoading(true);
    setAiError(null);

    try {
      const response = await fetch(`/api/ai/market-insights?zipcode=${zipcode}`);
      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || 'Failed to fetch AI insights');
      }
      const data = await response.json();
      setAiInsights(data);
    } catch (err) {
      setAiError(err instanceof Error ? err.message : 'Failed to load AI insights');
    } finally {
      setAiLoading(false);
    }
  }

  return (
