  id: string;
  lot_number: string;
  width: number;
  depth: number;
  premium_price: number;
}

interface Option {
  id: string;
  option_code: string;
  description: string;
  default_price_adder: number;
}

interface P3Weights {
  pace: number;
  profit: number;
  persona: number;
}

