  predictedMarginPct: number;
  totalCost: number;
  totalPrice: number;
  gpDollars: number;
}

interface DecisionFinalizeProps {
  community: Community;
  communityFloorPlan: CommunityFloorPlan;
  lot: Lot;
  standardOptions: Option[];
  selectedOptions: Option[];
  weights: P3Weights;
  weightsPreset: string | null;
  results: P3Results;
  onSave: Dispatch<string>;
  onStartOver: () => void;
}

export default function DecisionFinalize({
  community,
  communityFloorPlan,
  lot,
  standardOptions,
  selectedOptions,
  weights,
  weightsPreset,
  results,
  onSave,
  onStartOver,
}: DecisionFinalizeProps) {
  const [notes, setNotes] = useState('');
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fp = communityFloorPlan.floor_plan;
  const bathrooms = fp.bathrooms_full + (fp.bathrooms_half * 0.5);
  const optionsPriceAdd = selectedOptions.reduce((sum, opt) => sum + opt.default_price_adder, 0);

  const handleSave = async () => {
    setSaving(true);
    setError(null);
    try {
      await onSave(notes);
      setSaved(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save decision');
    } finally {
      setSaving(false);
    }
  };

  if (saved) {
    return (
      <div className="text-center space-y-6 py-8">
        <div className="text-6xl">✅</div>
        <h2 className="text-3xl font-semibold text-ink">Decision Saved!</h2>
        <p className="text-ink-muted">
          Your spec decision has been saved successfully.
        </p>
        <div className="bg-white border border-gray-200 rounded-lg p-6 max-w-md mx-auto">
          <div className="space-y-3 text-left">
            <div className="flex items-center justify-between">
              <span className="text-ink-muted">Floor Plan:</span>
              <span className="font-semibold text-ink">{fp.name}</span>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-ink-muted">Lot:</span>
              <span className="font-semibold text-ink">{lot.lot_number}</span>
            </div>
            <div className="flex items-center justify-between border-t border-gray-100 pt-3">
              <span className="text-ink-muted">Total Price:</span>
              <span className="font-bold text-xl text-green-600">${results.totalPrice.toLocaleString()}</span>
            </div>
          </div>
        </div>
        <div className="flex items-center justify-center space-x-4 pt-4">
          <button
            onClick={onStartOver}
            className="px-6 py-2 border-2 border-brand text-brand rounded-lg font-medium hover:bg-orange-50 transition-colors ease-out"
          >
            Start New Wizard
          </button>
          <a
            href={`/communities/${community.id}`}
            className="px-6 py-2 bg-brand text-white rounded-lg font-medium hover:bg-brand-hover transition-colors ease-out"
          >
            View Community
          </a>
        </div>
      </div>
    );
  }

  return (
    <div>
      <h2 className="text-xl font-semibold text-ink mb-2">Review & Save Decision</h2>
      <p className="text-ink-muted mb-6">
        Review your spec configuration and save your decision.
      </p>

      {/* Summary Card */}
      <div className="bg-white rounded-lg border border-gray-200 overflow-hidden mb-6">
        {/* Header */}
        <div className="bg-brand text-white p-4">
          <h3 className="text-lg font-bold">{fp.name}</h3>
          <p className="text-white/80">
            {community.name} · Lot {lot.lot_number}
          </p>
        </div>

        {/* Details */}
        <div className="p-4 space-y-4">
          {/* Floor Plan Details */}
          <div>
            <h4 className="text-sm font-medium text-ink-muted mb-2">Floor Plan</h4>
            <div className="flex flex-wrap gap-3 text-sm">
              <span className="px-2 py-1 bg-gray-100 rounded">{fp.square_feet.toLocaleString()} sqft</span>
              <span className="px-2 py-1 bg-gray-100 rounded">{fp.bedrooms} BR / {bathrooms} BA</span>
              <span className="px-2 py-1 bg-gray-100 rounded">Base: ${communityFloorPlan.base_price.toLocaleString()}</span>
            </div>
          </div>

          {/* Lot Details */}
          <div>
            <h4 className="text-sm font-medium text-ink-muted mb-2">Lot</h4>
            <div className="flex flex-wrap gap-3 text-sm">
              <span className="px-2 py-1 bg-gray-100 rounded">Lot {lot.lot_number}</span>
              <span className="px-2 py-1 bg-gray-100 rounded">{lot.width}'×{lot.depth}'</span>
              {lot.premium_price > 0 ? (
                <span className="px-2 py-1 bg-gray-100 rounded">+${lot.premium_price.toLocaleString()} premium</span>
              ) : (
                <span className="px-2 py-1 bg-green-100 text-green-700 rounded">No premium</span>
              )}
            </div>
          </div>

          {/* Standard Options */}
          {standardOptions.length > 0 && (
            <div>
              <h4 className="text-sm font-medium text-ink-muted mb-2">Standard Options (Included)</h4>
              <div className="flex flex-wrap gap-2">
                {standardOptions.map((opt) => (
                  <span key={opt.id} className="inline-flex items-center px-2 py-1 bg-green-50 border border-green-200 rounded text-sm text-green-700">
                    <svg className="w-3 h-3 mr-1" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                    </svg>
                    {opt.description}
                  </span>
                ))}
              </div>
            </div>
          )}

          {/* Selected Upgrades */}
          {selectedOptions.length > 0 && (
            <div>
              <h4 className="text-sm font-medium text-ink-muted mb-2">Selected Upgrades (+${optionsPriceAdd.toLocaleString()})</h4>
              <div className="space-y-1">
                {selectedOptions.map((opt) => (
                  <div key={opt.id} className="flex justify-between text-sm">
                    <span className="text-ink">{opt.description}</span>
                    <span className="text-ink-muted">+${opt.default_price_adder.toLocaleString()}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* P3 Strategy */}
          <div>
            <h4 className="text-sm font-medium text-ink-muted mb-2">P3 Strategy</h4>
            <div className="flex items-center gap-4 text-sm">
              <span className="px-2 py-1 bg-blue-100 text-blue-700 rounded">Pace: {weights.pace}%</span>
              <span className="px-2 py-1 bg-green-100 text-green-700 rounded">Profit: {weights.profit}%</span>
              <span className="px-2 py-1 bg-blue-100 text-blue-700 rounded">Persona: {weights.persona}%</span>
              {weightsPreset && (
                <span className="text-ink-muted capitalize">({weightsPreset.replace(/([A-Z])/g, ' $1').trim()})</span>
              )}
            </div>
          </div>
        </div>

        {/* Financial Summary */}
        <div className="bg-gray-50 p-4 border-t border-gray-200">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-center">
            <div>
              <p className="text-xs text-ink-muted">Total Price</p>
              <p className="text-lg font-bold text-ink">${results.totalPrice.toLocaleString()}</p>
            </div>
            <div>
              <p className="text-xs text-ink-muted">Gross Profit</p>
              <p className="text-lg font-bold text-green-600">${results.gpDollars.toLocaleString()}</p>
            </div>
            <div>
              <p className="text-xs text-ink-muted">P3 Score</p>
              <p className="text-lg font-bold text-brand">{results.weightedScore.toFixed(0)}</p>
            </div>
            <div>
              <p className="text-xs text-ink-muted">Est. DOM</p>
              <p className="text-lg font-bold text-ink">{results.predictedDomDays} days</p>
            </div>
          </div>
        </div>
      </div>

      {/* Notes */}
      <div className="mb-6">
        <label className="block text-sm font-medium text-ink mb-2">
          Decision Notes (Optional)
        </label>
        <textarea
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          placeholder="Add any notes about this spec decision..."
          rows={4}
          className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-brand focus:border-transparent resize-none"
        />
      </div>

      {/* Error */}
      {error && (
        <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg text-red-700">
          {error}
        </div>
      )}

      {/* Actions */}
      <div className="flex justify-between items-center">
        <button
          onClick={onStartOver}
          className="px-4 py-2 text-ink-muted hover:text-ink transition-colors ease-out"
        >
          Start Over
        </button>
        <button
          onClick={handleSave}
          disabled={saving}
          className="px-8 py-3 bg-brand text-white rounded-lg hover:bg-brand-hover transition-colors ease-out font-medium disabled:opacity-50 disabled:cursor-not-allowed flex items-center"
        >
          {saving ? (
            <>
              <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin mr-2"></div>
              Saving...
            </>
          ) : (
            <>
              <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
              </svg>
              Save Decision
            </>
          )}
        </button>
      </div>
    </div>
  );
}

import { useState, useEffect, type Dispatch } from 'react';
import type { BrixAnalysisResult, ExistingData } from '../../../../lib/importers/brixValidator';
import { runFullAnalysis } from '../../../../lib/importers/brixValidator';
import type { BrixFilesState } from './BrixFileUploadStep';
import type { BrixMappingsState } from './BrixColumnMappingStep';

interface BrixAnalysisStepProps {
  files: BrixFilesState;
  mappings: BrixMappingsState;
  analysis: BrixAnalysisResult | null;
  onAnalysisComplete: Dispatch<BrixAnalysisResult>;
  onNext: () => void;
  onBack: () => void;
}

interface EntitySummaryCardProps {
  title: string;
  icon: string;
  toCreate: number;
  toUpdate: number;
  errors: number;
  items?: { label: string; count: number }[];
  expanded?: boolean;
  onToggle?: () => void;
}

function EntitySummaryCard({
  title,
  icon,
  toCreate,
  toUpdate,
  errors,
  items,
  expanded,
  onToggle,
}: EntitySummaryCardProps) {
  const total = toCreate + toUpdate;

  return (
    <div className="bg-white rounded-lg border border-gray-200 overflow-hidden">
      <div
        className={`p-4 ${onToggle ? 'cursor-pointer hover:bg-gray-50' : ''}`}
        onClick={onToggle}
      >
        <div className="flex items-start justify-between">
          <div className="flex items-center space-x-3">
            <span className="text-2xl">{icon}</span>
            <div>
              <h3 className="font-medium text-ink">{title}</h3>
              <div className="flex items-center space-x-4 text-sm text-ink-muted mt-1">
                {toCreate > 0 && (
                  <span className="text-green-600">+{toCreate.toLocaleString()} new</span>
                )}
                {toUpdate > 0 && (
                  <span className="text-blue-600">{toUpdate.toLocaleString()} updates</span>
                )}
                {errors > 0 && (
                  <span className="text-red-600">{errors} errors</span>
                )}
                {total === 0 && <span>No changes</span>}
              </div>
            </div>
          </div>
          {onToggle && (
            <span className="text-gray-400">{expanded ? '▼' : '▶'}</span>
          )}
        </div>
      </div>

      {expanded && items && items.length > 0 && (
        <div className="border-t border-gray-200 p-4 bg-gray-50">
          <div className="space-y-2 max-h-40 overflow-y-auto">
            {items.slice(0, 10).map((item, idx) => (
              <div key={idx} className="flex items-center justify-between text-sm">
                <span className="text-ink truncate">{item.label}</span>
                {item.count > 0 && (
                  <span className="text-ink-muted">{item.count} lots</span>
                )}
              </div>
            ))}
            {items.length > 10 && (
              <div className="text-sm text-ink-muted">
                ...and {items.length - 10} more
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export default function BrixAnalysisStep({
  files,
  mappings,
  analysis,
  onAnalysisComplete,
  onNext,
  onBack,
}: BrixAnalysisStepProps) {
  const [isLoading, setIsLoading] = useState(false);
  const [expandedCard, setExpandedCard] = useState<string | null>(null);

  // Fetch existing data and run analysis
  useEffect(() => {
    if (!analysis) {
      loadExistingDataAndAnalyze();
    }
  }, []);

  const loadExistingDataAndAnalyze = async () => {
    setIsLoading(true);

    try {
      // Fetch existing data from all relevant tables
      const [communitiesRes, floorPlansRes, optionsRes, propertiesRes] = await Promise.all([
        fetch('/api/communities'),
        fetch('/api/floor-plans?active=false'),
        fetch('/api/option-library?active=false'),
        fetch('/api/properties?all=true'),
      ]);

      const communities = communitiesRes.ok ? await communitiesRes.json() : [];
      const floorPlans = floorPlansRes.ok ? await floorPlansRes.json() : [];
      const optionsData = optionsRes.ok ? await optionsRes.json() : { options: [] };
      const options = optionsData.options || optionsData || [];
      const properties = propertiesRes.ok ? await propertiesRes.json() : [];

      // Build lookup maps
      const existing: ExistingData = {
        communities: new Map(
          (communities || []).map((c: any) => [c.name.toLowerCase(), { id: c.id, name: c.name }])
        ),
        floorPlans: new Map(
          (floorPlans || []).map((fp: any) => [
            (fp.plan_code || fp.name).toLowerCase(),
            { id: fp.id, name: fp.name, plan_code: fp.plan_code }
          ])
        ),
        options: new Map(
          (options || []).map((o: any) => [o.option_code.toLowerCase(), { id: o.id, option_code: o.option_code }])
        ),
        lots: new Map(), // Lots are fetched per-community, skip for now
        properties: new Map(
          (properties || []).map((p: any) => [p.job_id.toLowerCase(), { id: p.id, job_id: p.job_id }])
        ),
      };

      // Run analysis
      const result = runFullAnalysis(
        {
          planData: { parseResult: files.planData.parseResult },
          jobLotData: { parseResult: files.jobLotData.parseResult },
          salesPrice: { parseResult: files.salesPrice.parseResult },
        },
        mappings,
        existing
      );

      onAnalysisComplete(result);
    } catch (error) {
      console.error('Failed to load existing data:', error);
    } finally {
      setIsLoading(false);
    }
  };

  if (isLoading || !analysis) {
    return (
      <div className="space-y-6">
        <div>
          <h2 className="text-2xl font-semibold text-ink mb-2">
            Analyzing Data
          </h2>
          <p className="text-ink-muted">
            Checking for duplicates and preparing import preview...
          </p>
        </div>
        <div className="flex items-center justify-center py-12">
          <div className="text-center">
            <div className="text-6xl mb-4 animate-pulse">🔍</div>
            <div className="text-ink-muted">Analyzing your data...</div>
          </div>
        </div>
      </div>
    );
  }

  const { summary } = analysis;
  const hasConflicts =
    analysis.floorPlans.toUpdate.length > 0 ||
    analysis.communities.toUpdate.length > 0 ||
    analysis.options.toUpdate.length > 0 ||
    analysis.properties.toUpdate.length > 0;

  // Build community items for expandable view
  const communityItems = analysis.communities.toCreate.map(c => ({
    label: c.name,
    count: c.total_lots,
  }));

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-semibold text-ink mb-2">
          Analysis Complete
        </h2>
        <p className="text-ink-muted">
          Review what will be imported. Records with conflicts will be updated.
        </p>
      </div>

      {/* Summary Banner */}
      <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
        <div className="flex items-center justify-between">
          <div>
            <div className="font-medium text-blue-900">
              {summary.totalNewRecords.toLocaleString()} new records to create
            </div>
            {summary.totalUpdates > 0 && (
              <div className="text-sm text-blue-700">
                {summary.totalUpdates.toLocaleString()} existing records will be updated
              </div>
            )}
          </div>
          {summary.totalErrors > 0 && (
            <div className="text-red-600 font-medium">
              {summary.totalErrors} errors found
            </div>
          )}
        </div>
      </div>

      {/* Entity Cards */}
      <div className="space-y-3">
        {files.jobLotData.parseResult && (
          <EntitySummaryCard
            title="Communities"
            icon="🏘️"
            toCreate={analysis.communities.toCreate.length}
            toUpdate={analysis.communities.toUpdate.length}
            errors={analysis.communities.errors.length}
            items={communityItems}
            expanded={expandedCard === 'communities'}
            onToggle={() => setExpandedCard(expandedCard === 'communities' ? null : 'communities')}
          />
        )}

        {files.planData.parseResult && (
          <EntitySummaryCard
            title="Floor Plans"
            icon="📐"
            toCreate={analysis.floorPlans.toCreate.length}
            toUpdate={analysis.floorPlans.toUpdate.length}
            errors={analysis.floorPlans.errors.length}
          />
        )}

        {files.salesPrice.parseResult && (
          <>
            <EntitySummaryCard
              title="Options"
              icon="🔧"
              toCreate={analysis.options.toCreate.length}
              toUpdate={analysis.options.toUpdate.length}
              errors={analysis.options.errors.length}
            />

            {/* Option Relationships Card - shown when proj/plan columns are mapped */}
            {analysis.optionRelationships && analysis.optionRelationships.stats.plansToUpdate > 0 && (
              <div className="bg-blue-50 rounded-lg border border-blue-200 overflow-hidden">
                <div className="p-4">
                  <div className="flex items-start justify-between">
                    <div className="flex items-center space-x-3">
                      <span className="text-2xl">🔗</span>
                      <div>
                        <h3 className="font-medium text-ink">Option Relationships</h3>
                        <div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-sm text-ink-muted mt-1">
                          {analysis.optionRelationships.stats.plansToUpdate > 0 && (
                            <span className="text-blue-600">
                              {analysis.optionRelationships.stats.plansToUpdate} floor plans to update
                            </span>
                          )}
                          {analysis.optionRelationships.stats.communityPlansToCreate > 0 && (
                            <span className="text-green-600">
                              +{analysis.optionRelationships.stats.communityPlansToCreate} community-plan links
                            </span>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Details */}
                  <div className="mt-3 pt-3 border-t border-blue-200 grid grid-cols-2 gap-4 text-sm">
                    <div>
                      <div className="text-ink-muted">Standard Options ($0)</div>
                      <div className="font-medium text-green-700">
                        {analysis.optionRelationships.stats.standardOptionCount} included in base
                      </div>
                    </div>
                    <div>
                      <div className="text-ink-muted">Additional Options (&gt;$0)</div>
                      <div className="font-medium text-brand">
                        {analysis.optionRelationships.stats.additionalOptionCount} buyer pays
                      </div>
                    </div>
                    {analysis.optionRelationships.stats.pricingOverridesCount > 0 && (
                      <div className="col-span-2">
                        <div className="text-ink-muted">Pricing Overrides</div>
                        <div className="font-medium text-purple-600">
                          {analysis.optionRelationships.stats.pricingOverridesCount} community-specific prices
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            )}
          </>
        )}

        {files.jobLotData.parseResult && (
          <>
            <EntitySummaryCard
              title="Lots"
              icon="📍"
              toCreate={analysis.lots.toCreate.length}
              toUpdate={analysis.lots.toUpdate.length}
              errors={analysis.lots.errors.length}
            />

            <EntitySummaryCard
              title="Properties"
              icon="🏠"
              toCreate={analysis.properties.toCreate.length}
              toUpdate={analysis.properties.toUpdate.length}
              errors={analysis.properties.errors.length}
            />
          </>
        )}
      </div>

      {/* Conflict Warning */}
      {hasConflicts && (
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
          <div className="font-medium text-yellow-900 mb-1">Duplicates Found</div>
          <div className="text-sm text-yellow-800">
            {summary.totalUpdates} existing records will be updated with new data.
            You can review and change this behavior in the next step.
          </div>
        </div>
      )}

      {/* Navigation */}
      <div className="flex items-center justify-between pt-4">
        <button
          onClick={onBack}
          className="px-6 py-2 border border-gray-300 text-ink-muted rounded-lg font-medium hover:bg-gray-50"
        >
          Back
        </button>
        <button
          onClick={onNext}
          disabled={summary.totalNewRecords === 0 && summary.totalUpdates === 0}
          className={`
            px-6 py-2 rounded-lg font-medium transition-colors ease-out
            ${summary.totalNewRecords > 0 || summary.totalUpdates > 0
              ? 'bg-brand text-white hover:bg-brand-hover'
              : 'bg-gray-200 text-gray-500 cursor-not-allowed'
            }
          `}
        >
          {hasConflicts ? 'Review Conflicts' : 'Start Import'}
        </button>
      </div>
    </div>
  );
}

