import { useEffect, useState } from 'react';
import { dispatchBreadcrumbContext } from '../../lib/breadcrumbUtils';
import { supabase } from '../../lib/supabase';
import type { Property, PropertyOption } from '../../types/property';
import EmptyState from '../ui/EmptyState';
import LoadingState from '../ui/LoadingState';

type PropertyWithCommunity = Property & {
  community_name?: string | null;
};

type PropertyDashboardProps = {
  id: string;
};

const PROPERTY_STATUS_STYLES: Record<string, string> = {
  Available: 'bg-green-50 text-green-700',
  'Under Construction': 'bg-blue-50 text-blue-700',
  Sold: 'bg-gray-100 text-gray-600',
  'Inventory/Spec': 'bg-amber-50 text-amber-600',
};

const propertyStatusClass = (status: string | null) =>
  (status && PROPERTY_STATUS_STYLES[status]) || 'bg-gray-100 text-gray-500';

const formatCurrencyValue = (value: number | null) => {
  if (value == null) return '—';
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(value);
};

const formatNumericValue = (value: number | null) => {
  if (value == null) return '—';
  return new Intl.NumberFormat('en-US').format(value);
};

const propertyAddress = (property: PropertyWithCommunity) =>
  [property.street_address, property.city, property.state, property.zip_code]
    .filter(Boolean)
    .join(', ') || 'No address provided';

type CommunityLinkProps = {
  property: PropertyWithCommunity;
  editHref: string;
};

const CommunityLink = ({ property, editHref }: CommunityLinkProps) => {
  if (property.community_name) {
    return (
      <div className="flex items-center space-x-2">
        <span className="text-sm text-ink-muted">Community:</span>
        <a
          href={`/communities/${property.community_id}`}
          className="text-brand hover:text-brand-hover font-medium transition-colors ease-out"
