      <button
        onClick={() => {
          window.location.href = editHref;
        }}
        className="text-brand hover:text-brand-hover text-sm font-medium transition-colors ease-out"
      >
        Link to Community
      </button>
    </div>
  );
};

type PropertyOptionsSectionProps = {
  options: PropertyOption[];
  editHref: string;
};

