        <tbody>
          {options.map((option) => (
            <tr key={option.id} className="border-t border-gray-200">
              <td className="px-4 py-3 text-ink font-medium">{option.option_code}</td>
              <td className="px-4 py-3 text-ink-muted">{option.description}</td>
              <td className="px-4 py-3 text-right text-ink-muted">{option.quantity}</td>
              <td className="px-4 py-3 text-right text-ink-muted">{formatCurrencyValue(option.unit_price)}</td>
              <td className="px-4 py-3 text-right text-ink font-medium">{formatCurrencyValue(option.price)}</td>
              <td className="px-4 py-3 text-center">
