import { useState, useEffect, type Dispatch } from 'react';
import type { ColumnMapping, ParseResult, ParsedRow } from '../../../lib/importers/excelParser';
import { autoMapColumns } from '../../../lib/importers/excelParser';

interface ColumnMappingStepProps {
  parseResult: ParseResult;
  onMappingComplete: Dispatch<ColumnMapping[]>;
  onNext: () => void;
  onBack: () => void;
}

type FieldConfig = {
  field: string;
  label: string;
  required: boolean;
};

const REQUIRED_FIELDS = [
  { field: 'option_code', label: 'Option Code', required: true },
  { field: 'description', label: 'Description', required: true },
  { field: 'category', label: 'Category', required: true },
];

const OPTIONAL_FIELDS = [
  { field: 'subcategory', label: 'Subcategory', required: false },
  { field: 'base_cost', label: 'Base Cost/Price', required: false },
  { field: 'notes', label: 'Notes', required: false },
];

type MappingRowProps = {
  field: FieldConfig;
  headers: string[];
  usedColumns: Set<string>;
  mappedColumn: string;
  emptyLabel: string;
  onChange: (sourceColumn: string) => void;
};

function MappingRow({ field, headers, usedColumns, mappedColumn, emptyLabel, onChange }: MappingRowProps) {
  return (
    <div className="grid grid-cols-2 gap-4 items-center">
      <label className={`text-sm font-medium ${field.required ? 'text-ink' : 'text-ink-muted'}`}>
        {field.label}
        {field.required && <span className="text-red-500 ml-1">*</span>}
      </label>
      <select
        value={mappedColumn}
        onChange={(e) => onChange(e.target.value)}
        className="px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-brand"
      >
        <option value="">{emptyLabel}</option>
        {headers.map(header => (
          <option
            key={header}
            value={header}
            disabled={usedColumns.has(header) && mappedColumn !== header}
          >
            {header}
          </option>
        ))}
      </select>
    </div>
  );
}

export default function ColumnMappingStep({
  parseResult,
  onMappingComplete,
  onNext,
  onBack,
}: ColumnMappingStepProps) {
  const [mappings, setMappings] = useState<ColumnMapping[]>([]);
  const [previewData, setPreviewData] = useState<ParsedRow[]>([]);

  useEffect(() => {
    // Auto-map columns on mount
    const autoMappings = autoMapColumns(parseResult.headers, parseResult.detectedFormat);
    setMappings(autoMappings);

    // Set preview data (first 3 rows)
    setPreviewData(parseResult.rows.slice(0, 3));
  }, [parseResult]);

  const handleMappingChange = (targetField: string, sourceColumn: string) => {
    setMappings(prev => {
      // Remove existing mapping for this target field
      const filtered = prev.filter(m => m.targetField !== targetField);

      // Add new mapping if source is selected
      if (sourceColumn !== '') {
        filtered.push({ targetField, sourceColumn });
      }

      return filtered;
    });
  };

  const getMappedColumn = (targetField: string): string => {
    const mapping = mappings.find(m => m.targetField === targetField);
    return mapping?.sourceColumn || '';
  };

  const getUsedColumns = (): Set<string> => {
    return new Set(mappings.map(m => m.sourceColumn));
  };

  const isValid = (): boolean => {
    // Check that all required fields are mapped
    return REQUIRED_FIELDS.every(field =>
      mappings.some(m => m.targetField === field.field)
    );
  };

  const handleNext = () => {
    if (isValid()) {
      onMappingComplete(mappings);
      onNext();
    }
  };

  const usedColumns = getUsedColumns();

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-semibold text-ink mb-2">
          Map Columns
        </h2>
        <p className="text-ink-muted">
          {parseResult.detectedFormat === 'brix'
            ? 'BRIX format detected! Columns have been auto-mapped. Review and adjust if needed.'
            : 'Match your file columns to the option library fields.'}
        </p>
      </div>

      {/* Format Detection Badge */}
      <div className="flex items-center space-x-3">
        <span className="text-sm text-ink-muted">Detected format:</span>
        <span className={`
          px-3 py-1 rounded-full text-xs font-medium
          ${parseResult.detectedFormat === 'brix' ? 'bg-green-100 text-green-800' : 'bg-blue-100 text-blue-800'}
        `}>
          {parseResult.detectedFormat === 'brix' ? '✓ BRIX' : parseResult.detectedFormat.toUpperCase()}
        </span>
      </div>

      {/* Column Mapping Form */}
      <div className="bg-white border border-gray-200 rounded-lg p-6 space-y-4">
        <div className="font-medium text-ink mb-4">Required Fields</div>

        {REQUIRED_FIELDS.map(field => (
          <MappingRow
            key={field.field}
            field={field}
            headers={parseResult.headers}
            usedColumns={usedColumns}
            mappedColumn={getMappedColumn(field.field)}
            emptyLabel="-- Select Column --"
            onChange={(value) => handleMappingChange(field.field, value)}
          />
        ))}

        <div className="border-t border-gray-200 pt-4 mt-6">
          <div className="font-medium text-ink mb-4">Optional Fields</div>

          {OPTIONAL_FIELDS.map(field => (
            <div key={field.field} className="mt-4">
              <MappingRow
                field={field}
                headers={parseResult.headers}
                usedColumns={usedColumns}
                mappedColumn={getMappedColumn(field.field)}
                emptyLabel="-- Skip / None --"
                onChange={(value) => handleMappingChange(field.field, value)}
              />
            </div>
          ))}
        </div>
      </div>

      {/* Preview Table */}
      <div className="bg-white border border-gray-200 rounded-lg p-4">
        <div className="font-medium text-ink mb-3">Preview (first 3 rows)</div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-gray-200">
                <th className="text-left py-2 px-3 font-medium text-ink-muted">Field</th>
                <th className="text-left py-2 px-3 font-medium text-ink-muted">Row 1</th>
                <th className="text-left py-2 px-3 font-medium text-ink-muted">Row 2</th>
                <th className="text-left py-2 px-3 font-medium text-ink-muted">Row 3</th>
              </tr>
            </thead>
            <tbody>
              {[...REQUIRED_FIELDS, ...OPTIONAL_FIELDS].map(field => {
                const sourceColumn = getMappedColumn(field.field);
                return (
                  <tr key={field.field} className="border-b border-gray-100">
                    <td className="py-2 px-3 font-medium text-ink">
                      {field.label}
                      {field.required && <span className="text-red-500 ml-1">*</span>}
                    </td>
                    {previewData.map((row, idx) => (
                      <td key={idx} className="py-2 px-3 text-ink-muted">
                        {sourceColumn && row[sourceColumn]
                          ? String(row[sourceColumn]).substring(0, 50) + (String(row[sourceColumn]).length > 50 ? '...' : '')
                          : <span className="text-gray-400 italic">not mapped</span>
                        }
                      </td>
                    ))}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {/* Validation Message */}
      {!isValid() && (
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
          <div className="flex items-start space-x-3">
            <div className="text-yellow-600 text-xl">⚠️</div>
            <div>
              <div className="font-medium text-yellow-900">Required fields missing</div>
              <div className="text-sm text-yellow-800 mt-1">
                Please map all required fields (Option Code, Description, Category) before continuing.
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Navigation */}
      <div className="flex items-center justify-between pt-4">
        <button
          onClick={onBack}
          className="px-4 py-2 text-ink-muted hover:text-ink font-medium"
        >
          ← Back
        </button>
        <button
          onClick={handleNext}
          disabled={!isValid()}
          className={`
            px-6 py-2 rounded-lg font-medium transition-colors ease-out
            ${isValid()
              ? 'bg-brand text-white hover:bg-brand-hover'
              : 'bg-gray-300 text-gray-500 cursor-not-allowed'
            }
          `}
        >
          Next: Configure Import →
        </button>
      </div>
    </div>
  );
}

import { useState, useEffect, type Dispatch } from 'react';
import { checkFeasibility, type FloorPlan } from '../../../lib/p3Engine';

interface Lot {
  id: string;
  lot_number: string;
  width: number;
  depth: number;
  premium_cost: number;
  premium_price: number;
  status: string;
  constraints?: string[];
  notes?: string;
}

interface LotSelectorProps {
  communityId: string;
  floorPlan: FloorPlan;
  selectedLot: Lot | null;
  onSelect: Dispatch<Lot>;
}

export default function LotSelector({ communityId, floorPlan, selectedLot, onSelect }: LotSelectorProps) {
  const [lots, setLots] = useState<Lot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showUnavailable, setShowUnavailable] = useState(false);
  const [sortBy, setSortBy] = useState<'number' | 'size' | 'premium'>('number');

  useEffect(() => {
    if (communityId) {
      fetchLots();
    }
  }, [communityId]);

  async function fetchLots() {
    try {
      setLoading(true);
      const response = await fetch(`/api/lots?communityId=${communityId}`);
      if (!response.ok) throw new Error('Failed to fetch lots');
      const data = await response.json();
      setLots(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load lots');
    } finally {
      setLoading(false);
    }
  }

  // Check compatibility for each lot
  const lotsWithCompatibility = lots.map((lot) => {
    const feasibility = checkFeasibility(floorPlan, lot);
    return {
      ...lot,
      compatible: feasibility.feasible,
      reasons: feasibility.reasons,
    };
  });

  // Filter and sort
  const filteredLots = lotsWithCompatibility
    .filter((lot) => {
      if (!showUnavailable && lot.status !== 'available') return false;
      return true;
    })
    .sort((a, b) => {
      switch (sortBy) {
        case 'size':
          return (b.width * b.depth) - (a.width * a.depth);
        case 'premium':
          return a.premium_price - b.premium_price;
        default:
          return a.lot_number.localeCompare(b.lot_number, undefined, { numeric: true });
      }
    });

  const compatibleLots = filteredLots.filter((lot) => lot.compatible);
  const incompatibleLots = filteredLots.filter((lot) => !lot.compatible);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="inline-block h-8 w-8 animate-spin rounded-full border-4 border-solid border-brand border-r-transparent"></div>
        <span className="ml-3 text-ink-muted">Loading lots...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 border border-red-200 rounded-lg p-4 text-red-700">
        {error}
      </div>
    );
  }

  if (lots.length === 0) {
    return (
      <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-6 text-center">
        <h3 className="text-lg font-medium text-yellow-800 mb-2">No Lots Found</h3>
        <p className="text-yellow-700 mb-4">
          This community doesn't have any lots added yet. Add lots first.
        </p>
        <a
          href={`/communities/${communityId}/lots/add`}
          className="inline-flex items-center px-4 py-2 bg-brand text-white rounded-lg hover:bg-brand-hover transition-colors ease-out"
        >
          Add Lots
        </a>
      </div>
    );
  }

  return (
    <div>
