        </div>
      )}
    </div>
  );
}

import { useState, useEffect, type Dispatch } from 'react';
import type { ValidationResult, OptionRow } from '../../../lib/importers/optionValidator';
import { validateOptions, hasValidationIssue, getRowValidationMessages } from '../../../lib/importers/optionValidator';

type ImportPayload = {
  rowsToImport: OptionRow[];
  duplicateActions: Map<string, 'skip' | 'overwrite'>;
};

interface PreviewValidationStepProps {
  rows: OptionRow[];
  existingOptionCodes: string[];
  duplicateStrategy: 'skip' | 'overwrite' | 'ask';
  onImport: Dispatch<ImportPayload>;
  onBack: () => void;
}

type FilterType = 'all' | 'valid' | 'errors' | 'warnings' | 'zero_price' | 'duplicates';
type ValidationStats = ValidationResult['stats'];

const isDuplicateWarning = (warning: { field: string; message: string }) =>
  warning.field === 'option_code' && warning.message.includes('already exists');

const rowMatchesDuplicateFilter = (index: number, validationResult: ValidationResult) =>
  validationResult.warnings.some(
    (warning) => warning.row === index + 1 && isDuplicateWarning(warning),
  );

const rowMatchesFilter = (
  row: OptionRow,
  index: number,
  filter: FilterType,
  validationResult: ValidationResult,
) => {
  if (filter === 'valid') {
    return !hasValidationIssue(index, validationResult);
  }
  if (filter === 'errors') {
    return hasValidationIssue(index, validationResult, 'error');
  }
  if (filter === 'warnings') {
    return hasValidationIssue(index, validationResult, 'warning');
  }
  if (filter === 'zero_price') {
    return row.base_cost === 0;
  }
  if (filter === 'duplicates') {
    return rowMatchesDuplicateFilter(index, validationResult);
  }
  return true;
};

const getFilteredRowsForType = (
  rows: OptionRow[],
  filter: FilterType,
  validationResult: ValidationResult,
): { row: OptionRow; index: number }[] =>
  rows
    .map((row, index) => ({ row, index }))
    .filter(({ row, index }) => rowMatchesFilter(row, index, filter, validationResult));

const canImportRows = (
  validationResult: ValidationResult | null,
  isImporting: boolean,
  duplicateStrategy: 'skip' | 'overwrite' | 'ask',
  duplicateActionsSize: number,
) => {
  if (!validationResult || isImporting) return false;
  if (validationResult.stats.validRows === 0) return false;

  if (duplicateStrategy !== 'ask') return true;
  const duplicateCount = validationResult.warnings.filter(isDuplicateWarning).length;
  return duplicateCount <= duplicateActionsSize;
};

const buildDuplicateActionsFromValidation = (
  validationResult: ValidationResult,
  duplicateStrategy: 'skip' | 'overwrite' | 'ask',
) => {
  if (duplicateStrategy === 'ask') {
    return new Map<string, 'skip' | 'overwrite'>();
  }

  const actions = new Map<string, 'skip' | 'overwrite'>();
  validationResult.warnings.forEach((warning) => {
    if (!isDuplicateWarning(warning)) return;
    const optionCode = warning.value as string;
    actions.set(optionCode, duplicateStrategy);
  });
  return actions;
};

const buildRowsToImport = (rows: OptionRow[], validationResult: ValidationResult) => {
  const errorRows = new Set(validationResult.errors.map((error) => error.row - 1));
  return rows.filter((_, index) => !errorRows.has(index));
};

type ValidationRowsTableProps = {
  filteredRows: { row: OptionRow; index: number }[];
  validationResult: ValidationResult;
  duplicateStrategy: 'skip' | 'overwrite' | 'ask';
  filter: FilterType;
  duplicateActions: Map<string, 'skip' | 'overwrite'>;
  onDuplicateAction: (optionCode: string, action: 'skip' | 'overwrite') => void;
};

const rowBackgroundClass = (hasError: boolean, hasWarning: boolean, hasInfo: boolean) => {
  if (hasError) return 'bg-red-50';
  if (hasWarning) return 'bg-yellow-50';
  if (hasInfo) return 'bg-blue-50';
  return '';
};

const messageSeverityClass = (severity: 'error' | 'warning' | 'info') => {
  if (severity === 'error') return 'text-red-700';
  if (severity === 'warning') return 'text-yellow-700';
  return 'text-blue-700';
};

const ValidationRowsTable = ({
  filteredRows,
  validationResult,
  duplicateStrategy,
  filter,
  duplicateActions,
  onDuplicateAction,
}: ValidationRowsTableProps) => (
  <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
    <div className="overflow-x-auto max-h-96 overflow-y-auto">
      <table className="w-full text-sm">
        <thead className="bg-gray-50 sticky top-0">
          <tr>
            <th className="text-left py-3 px-4 font-medium text-ink-muted w-12">#</th>
            <th className="text-left py-3 px-4 font-medium text-ink-muted">Code</th>
            <th className="text-left py-3 px-4 font-medium text-ink-muted">Description</th>
            <th className="text-left py-3 px-4 font-medium text-ink-muted">Category</th>
            <th className="text-left py-3 px-4 font-medium text-ink-muted">Cost</th>
            <th className="text-left py-3 px-4 font-medium text-ink-muted">Adder</th>
            <th className="text-left py-3 px-4 font-medium text-ink-muted">Status</th>
            {duplicateStrategy === 'ask' && filter === 'duplicates' && (
              <th className="text-left py-3 px-4 font-medium text-ink-muted">Action</th>
            )}
          </tr>
        </thead>
        <tbody>
          {filteredRows.map(({ row, index }) => {
            const messages = getRowValidationMessages(index, validationResult);
            const hasError = hasValidationIssue(index, validationResult, 'error');
            const hasWarning = hasValidationIssue(index, validationResult, 'warning');
            const hasInfo = hasValidationIssue(index, validationResult, 'info');
            const isDuplicate = messages.some((message) => isDuplicateWarning(message));

            return (
              <tr
                key={index}
                className={`border-t border-gray-100 ${rowBackgroundClass(hasError, hasWarning, hasInfo)}`}
              >
                <td className="py-3 px-4 text-ink-muted">{index + 1}</td>
                <td className="py-3 px-4 font-mono text-xs">{row.option_code}</td>
                <td className="py-3 px-4 max-w-xs truncate">{row.description}</td>
                <td className="py-3 px-4">{row.category}</td>
                <td className="py-3 px-4">
                  <span className={row.base_cost === 0 ? 'text-yellow-700 font-medium' : ''}>
                    ${row.base_cost?.toFixed(2) || '0.00'}
                  </span>
                </td>
                <td className="py-3 px-4">${row.default_price_adder?.toFixed(2) || '0.00'}</td>
                <td className="py-3 px-4">
                  {messages.length > 0 ? (
                    <div className="space-y-1">
                      {messages.map((message, idx) => (
                        <div
                          key={idx}
                          className={`text-xs ${messageSeverityClass(message.severity)}`}
                        >
                          {message.message}
                        </div>
                      ))}
                    </div>
                  ) : (
                    <span className="text-green-600 text-xs">✓ Valid</span>
                  )}
                </td>
                {duplicateStrategy === 'ask' && filter === 'duplicates' && isDuplicate && (
                  <td className="py-3 px-4">
                    <select
                      value={duplicateActions.get(row.option_code || '') || ''}
                      onChange={(e) => onDuplicateAction(row.option_code || '', e.target.value as 'skip' | 'overwrite')}
                      className="px-2 py-1 border border-gray-300 rounded text-xs focus:outline-none focus:ring-2 focus:ring-brand"
                    >
                      <option value="">-- Choose --</option>
                      <option value="skip">Skip</option>
                      <option value="overwrite">Overwrite</option>
                    </select>
                  </td>
                )}
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  </div>
);

type ValidationFilterTabsProps = {
  filter: FilterType;
  setFilter: Dispatch<FilterType>;
  stats: ValidationStats;
};

const ValidationFilterTabs = ({
  filter,
  setFilter,
  stats,
}: ValidationFilterTabsProps) => (
  <div className="flex items-center space-x-2 overflow-x-auto pb-2">
    <button
      onClick={() => setFilter('all')}
      className={`px-4 py-2 rounded-lg font-medium whitespace-nowrap ${
        filter === 'all' ? 'bg-brand text-white' : 'bg-gray-100 text-ink-muted hover:bg-gray-200'
      }`}
    >
      All ({stats.totalRows})
    </button>
    <button
      onClick={() => setFilter('valid')}
      className={`px-4 py-2 rounded-lg font-medium whitespace-nowrap ${
        filter === 'valid' ? 'bg-green-600 text-white' : 'bg-green-50 text-green-700 hover:bg-green-100'
      }`}
    >
      ✓ Valid ({stats.validRows})
    </button>
    {stats.errorRows > 0 && (
      <button
        onClick={() => setFilter('errors')}
        className={`px-4 py-2 rounded-lg font-medium whitespace-nowrap ${
          filter === 'errors' ? 'bg-red-600 text-white' : 'bg-red-50 text-red-700 hover:bg-red-100'
        }`}
      >
        ⚠️ Errors ({stats.errorRows})
      </button>
    )}
    {stats.duplicateCount > 0 && (
      <button
        onClick={() => setFilter('duplicates')}
        className={`px-4 py-2 rounded-lg font-medium whitespace-nowrap ${
          filter === 'duplicates' ? 'bg-blue-600 text-white' : 'bg-blue-50 text-blue-700 hover:bg-blue-100'
        }`}
      >
        📋 Duplicates ({stats.duplicateCount})
      </button>
    )}
    {stats.missingPriceCount > 0 && (
      <button
        onClick={() => setFilter('zero_price')}
        className={`px-4 py-2 rounded-lg font-medium whitespace-nowrap ${
          filter === 'zero_price' ? 'bg-yellow-600 text-white' : 'bg-yellow-50 text-yellow-700 hover:bg-yellow-100'
        }`}
      >
        💰 $0 Prices ({stats.missingPriceCount})
      </button>
    )}
  </div>
);

export default function PreviewValidationStep({
  rows,
  existingOptionCodes,
  duplicateStrategy,
  onImport,
  onBack,
}: PreviewValidationStepProps) {
  const [validationResult, setValidationResult] = useState<ValidationResult | null>(null);
  const [isValidating, setIsValidating] = useState(true);
  const [filter, setFilter] = useState<FilterType>('all');
  const [duplicateActions, setDuplicateActions] = useState<Map<string, 'skip' | 'overwrite'>>(new Map());
  const [isImporting, setIsImporting] = useState(false);

  useEffect(() => {
    performValidation();
  }, [rows, existingOptionCodes]);

  const performValidation = async () => {
    setIsValidating(true);
    const result = await validateOptions(rows, existingOptionCodes);
    setValidationResult(result);
    setIsValidating(false);
    setDuplicateActions(buildDuplicateActionsFromValidation(result, duplicateStrategy));
  };

  const handleDuplicateAction = (optionCode: string, action: 'skip' | 'overwrite') => {
    setDuplicateActions(prev => {
      const newMap = new Map(prev);
      newMap.set(optionCode, action);
      return newMap;
    });
  };

  const getFilteredRows = (): { row: OptionRow; index: number }[] => {
    if (!validationResult) return [];
    return getFilteredRowsForType(rows, filter, validationResult);
  };

  const handleImport = () => {
    if (!validationResult) return;
    const rowsToImport = buildRowsToImport(rows, validationResult);

    setIsImporting(true);
    onImport({ rowsToImport, duplicateActions });
  };

  const canImport = (): boolean => {
    return canImportRows(validationResult, isImporting, duplicateStrategy, duplicateActions.size);
  };

  const filteredRows = getFilteredRows();

  if (isValidating) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="text-center space-y-4">
          <div className="text-6xl">⏳</div>
          <div className="text-lg font-medium text-ink">Validating data...</div>
        </div>
      </div>
    );
  }

  if (!validationResult) {
    return null;
  }

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-semibold text-ink mb-2">
          Review & Import
        </h2>
        <p className="text-ink-muted">
          Review the validation results and confirm import.
        </p>
      </div>

      {/* Summary Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-white border border-gray-200 rounded-lg p-4">
          <div className="text-2xl font-bold text-ink">{validationResult.stats.totalRows}</div>
          <div className="text-sm text-ink-muted">Total Rows</div>
        </div>

        <div className="bg-green-50 border border-green-200 rounded-lg p-4">
          <div className="text-2xl font-bold text-green-700">{validationResult.stats.validRows}</div>
          <div className="text-sm text-green-800">Valid Rows</div>
        </div>

        {validationResult.stats.errorRows > 0 && (
          <div className="bg-red-50 border border-red-200 rounded-lg p-4">
            <div className="text-2xl font-bold text-red-700">{validationResult.stats.errorRows}</div>
            <div className="text-sm text-red-800">Errors</div>
          </div>
        )}

        {validationResult.stats.missingPriceCount > 0 && (
          <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
            <div className="text-2xl font-bold text-yellow-700">{validationResult.stats.missingPriceCount}</div>
            <div className="text-sm text-yellow-800">$0.00 Prices</div>
          </div>
        )}

        {validationResult.stats.duplicateCount > 0 && (
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
            <div className="text-2xl font-bold text-blue-700">{validationResult.stats.duplicateCount}</div>
            <div className="text-sm text-blue-800">Duplicates</div>
          </div>
        )}
      </div>

      <ValidationFilterTabs
        filter={filter}
        setFilter={setFilter}
        stats={validationResult.stats}
      />

      <ValidationRowsTable
        filteredRows={filteredRows}
        validationResult={validationResult}
        duplicateStrategy={duplicateStrategy}
        filter={filter}
        duplicateActions={duplicateActions}
        onDuplicateAction={handleDuplicateAction}
      />

      {/* Import Summary */}
      <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
        <div className="font-medium text-blue-900 mb-2">📊 Import Summary</div>
        <div className="text-sm text-blue-800 space-y-1">
          <div>• {validationResult.stats.validRows} options will be imported</div>
          {validationResult.stats.errorRows > 0 && (
            <div>• {validationResult.stats.errorRows} rows will be skipped due to errors</div>
          )}
          {validationResult.stats.missingPriceCount > 0 && (
            <div>• {validationResult.stats.missingPriceCount} options have $0.00 prices (you can filter and update them later)</div>
          )}
        </div>
      </div>

      {/* Validation Warnings */}
      {!canImport() && (
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
          <div className="flex items-start space-x-3">
            <div className="text-yellow-600 text-xl">⚠️</div>
            <div>
              <div className="font-medium text-yellow-900">Action Required</div>
              <div className="text-sm text-yellow-800 mt-1">
                {duplicateStrategy === 'ask' && duplicateActions.size < validationResult.stats.duplicateCount
                  ? 'Please choose an action (skip or overwrite) for all duplicate option codes.'
                  : 'Cannot import: All rows have errors or no valid rows found.'
                }
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Navigation */}
      <div className="flex items-center justify-between pt-4">
        <button
          onClick={onBack}
          disabled={isImporting}
          className="px-4 py-2 text-ink-muted hover:text-ink font-medium disabled:opacity-50"
        >
          ← Back
        </button>
        <button
          onClick={handleImport}
          disabled={!canImport() || isImporting}
          className="px-6 py-2 rounded-lg font-medium transition-colors ease-out bg-brand text-white hover:bg-brand-hover disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {isImporting ? 'Importing...' : `Import ${validationResult.stats.validRows} Options`}
        </button>
      </div>
    </div>
  );
}

import { useState, useEffect, type Dispatch } from 'react';
import EmptyState from '../../ui/EmptyState';

interface Option {
  id: string;
  option_code: string;
  description: string;
  category: string;
  subcategory?: string;
  base_cost: number;
  default_price_adder: number;
  p3_impact_pace: number;
  p3_impact_profit: number;
  p3_impact_persona: number;
}

interface CommunityFloorPlan {
  id: string;
  standard_option_ids: string[];
  additional_available_option_ids: string[];
  floor_plan: {
    available_option_ids?: string[];
  };
}

interface OptionCheckboxesProps {
  communityFloorPlan: CommunityFloorPlan;
  selectedOptionIds: string[];
  onSelectionChange: Dispatch<{ optionIds: string[]; options: Option[] }>;
}

export default function OptionCheckboxes({
  communityFloorPlan,
  selectedOptionIds,
  onSelectionChange,
}: OptionCheckboxesProps) {
  const [allOptions, setAllOptions] = useState<Option[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [expandedCategories, setExpandedCategories] = useState<Set<string>>(new Set());

  useEffect(() => {
    fetchOptions();
  }, [communityFloorPlan]);

  async function fetchOptions() {
    try {
      setLoading(true);
      const response = await fetch('/api/option-library');
      if (!response.ok) throw new Error('Failed to fetch options');
      const data = await response.json();
      setAllOptions(data);

      // Auto-expand categories with selected options
      const categories = new Set<string>();
      data.forEach((opt: Option) => {
        if (selectedOptionIds.includes(opt.id)) {
          categories.add(opt.category);
        }
      });
      setExpandedCategories(categories);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load options');
    } finally {
      setLoading(false);
    }
  }

  // Get all available option IDs for this floor plan
  const allAvailableIds = new Set([
    ...(communityFloorPlan.floor_plan.available_option_ids || []),
    ...(communityFloorPlan.additional_available_option_ids || []),
  ]);

  const standardIds = new Set(communityFloorPlan.standard_option_ids || []);

  // Filter to only available options
  const availableOptions = allOptions.filter((opt) => allAvailableIds.has(opt.id));

  // Separate standard vs optional
  const standardOptions = availableOptions.filter((opt) => standardIds.has(opt.id));
  const optionalOptions = availableOptions.filter((opt) => !standardIds.has(opt.id));

  // Group optional by category
  const optionsByCategory = optionalOptions.reduce((acc, opt) => {
    if (!acc[opt.category]) acc[opt.category] = [];
    acc[opt.category].push(opt);
    return acc;
  }, {} as Record<string, Option[]>);

  const categories = Object.keys(optionsByCategory).sort();

  // Calculate totals
  const selectedOptions = optionalOptions.filter((opt) => selectedOptionIds.includes(opt.id));
  const totalAddedCost = selectedOptions.reduce((sum, opt) => sum + opt.base_cost, 0);
  const totalPriceIncrease = selectedOptions.reduce((sum, opt) => sum + opt.default_price_adder, 0);

  const toggleOption = (optionId: string) => {
    let newIds: string[];
    if (selectedOptionIds.includes(optionId)) {
      newIds = selectedOptionIds.filter((id) => id !== optionId);
    } else {
      newIds = [...selectedOptionIds, optionId];
    }
    const newOptions = optionalOptions.filter((opt) => newIds.includes(opt.id));
    onSelectionChange({ optionIds: newIds, options: newOptions });
  };

  const toggleCategory = (category: string) => {
    const newExpanded = new Set(expandedCategories);
    if (newExpanded.has(category)) {
      newExpanded.delete(category);
    } else {
      newExpanded.add(category);
    }
    setExpandedCategories(newExpanded);
  };

  function P3ImpactBadge({ impact, type }: { impact: number; type: 'pace' | 'profit' | 'persona' }) {
    if (impact === 0) return null;
    const colors = {
      pace: impact > 0 ? 'bg-blue-100 text-blue-700' : 'bg-blue-50 text-blue-400',
      profit: impact > 0 ? 'bg-green-100 text-green-700' : 'bg-green-50 text-green-400',
      persona: impact > 0 ? 'bg-blue-100 text-blue-700' : 'bg-blue-50 text-blue-400',
    };
    const labels = { pace: 'Pace', profit: 'Profit', persona: 'Persona' };

    return (
      <span className={`text-xs px-1.5 py-0.5 rounded ${colors[type]}`}>
        {impact > 0 ? '+' : ''}{impact} {labels[type]}
      </span>
    );
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="inline-block h-8 w-8 animate-spin rounded-full border-4 border-solid border-brand border-r-transparent"></div>
        <span className="ml-3 text-ink-muted">Loading options...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 border border-red-200 rounded-lg p-4 text-red-700">
        {error}
      </div>
    );
  }

  return (
    <div>
      <h2 className="text-xl font-semibold text-ink mb-2">Select Options</h2>
      <p className="text-ink-muted mb-4">
        Choose optional upgrades for this spec. Standard options are already included.
      </p>

      {/* Running Total */}
      <div className="bg-brand/5 border border-brand/20 rounded-lg p-4 mb-6">
        <div className="flex justify-between items-center">
          <div>
            <span className="text-sm text-ink-muted">Selected Upgrades:</span>
            <span className="ml-2 font-semibold text-ink">{selectedOptions.length}</span>
          </div>
          <div className="text-right">
            <div className="text-sm text-ink-muted">
              Added Cost: <span className="font-medium text-ink">${totalAddedCost.toLocaleString()}</span>
            </div>
            <div className="text-sm text-ink-muted">
              Price Increase: <span className="font-medium text-green-600">+${totalPriceIncrease.toLocaleString()}</span>
            </div>
          </div>
        </div>
      </div>

      {/* Standard Options */}
      {standardOptions.length > 0 && (
        <div className="mb-6">
          <h3 className="text-sm font-medium text-ink-muted mb-3 flex items-center">
            <svg className="w-4 h-4 mr-1 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
            </svg>
            Standard Options (Included in Base Price)
          </h3>
          <div className="bg-green-50 border border-green-200 rounded-lg p-3">
            <div className="flex flex-wrap gap-2">
              {standardOptions.map((opt) => (
                <span
                  key={opt.id}
                  className="inline-flex items-center px-3 py-1 bg-white border border-green-300 rounded-full text-sm text-green-800"
                >
                  <svg className="w-3 h-3 mr-1" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                  </svg>
                  {opt.description}
                </span>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Optional Upgrades by Category */}
      {categories.length === 0 ? (
        <EmptyState
          message="No options available"
          description="No optional upgrades available for this floor plan."
          component="OptionCheckboxes"
        />
      ) : (
        <div className="space-y-4">
          {categories.map((category) => {
            const categoryOptions = optionsByCategory[category];
            const isExpanded = expandedCategories.has(category);
            const selectedInCategory = categoryOptions.filter((opt) =>
              selectedOptionIds.includes(opt.id)
            ).length;

            return (
              <div key={category} className="border border-gray-200 rounded-lg overflow-hidden">
                <button
                  onClick={() => toggleCategory(category)}
                  className="w-full flex items-center justify-between p-4 bg-gray-50 hover:bg-gray-100 transition-colors ease-out"
                >
                  <div className="flex items-center">
                    <svg
                      className={`w-4 h-4 mr-2 text-ink-muted transition-transform ease-out ${isExpanded ? 'rotate-90' : ''}`}
                      fill="none"
                      stroke="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                    </svg>
                    <span className="font-medium text-ink">{category}</span>
                    <span className="ml-2 text-sm text-ink-muted">
                      ({categoryOptions.length} option{categoryOptions.length !== 1 ? 's' : ''})
                    </span>
                  </div>
                  {selectedInCategory > 0 && (
                    <span className="px-2 py-1 bg-brand text-white text-xs rounded-full">
                      {selectedInCategory} selected
                    </span>
                  )}
                </button>

                {isExpanded && (
                  <div className="p-4 space-y-3">
                    {categoryOptions.map((opt) => {
                      const isSelected = selectedOptionIds.includes(opt.id);

                      return (
                        <label
                          key={opt.id}
                          className={`flex items-start p-3 rounded-lg border-2 cursor-pointer transition-all ease-out ${
                            isSelected
                              ? 'border-brand bg-brand/5'
                              : 'border-gray-200 hover:border-gray-300'
                          }`}
                        >
                          <input
                            type="checkbox"
                            checked={isSelected}
                            onChange={() => toggleOption(opt.id)}
                            className="mt-1 w-4 h-4 text-brand border-gray-300 rounded focus:ring-brand"
                          />
                          <div className="ml-3 flex-1">
                            <div className="flex items-start justify-between">
                              <div>
                                <span className="font-medium text-ink">{opt.description}</span>
                                <span className="ml-2 text-xs text-ink-muted">({opt.option_code})</span>
                              </div>
                              <div className="text-right ml-4">
                                <div className="text-sm font-medium text-ink">
                                  +${opt.default_price_adder.toLocaleString()}
                                </div>
                                <div className="text-xs text-ink-muted">
                                  Cost: ${opt.base_cost.toLocaleString()}
                                </div>
                              </div>
                            </div>
                            <div className="flex flex-wrap gap-1 mt-2">
                              <P3ImpactBadge impact={opt.p3_impact_pace} type="pace" />
                              <P3ImpactBadge impact={opt.p3_impact_profit} type="profit" />
                              <P3ImpactBadge impact={opt.p3_impact_persona} type="persona" />
                            </div>
                          </div>
                        </label>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

