  1→import { useState } from 'react';
  2→import { supabase } from '../../lib/supabase';
  3→import {
  4→  CommunityNameAddressFields,
  5→  CommunityStatusLotsFields,
  6→} from './CommunityFields';
  7→
  8→type FormData = {
  9→  name: string;
 10→  address: string;
 11→  status: string;
 12→  total_lots: string;
 13→  lots_under_control: string;
 14→};
 15→
 16→type FormErrors = {
 17→  name?: string;
 18→  address?: string;
 19→  status?: string;
 20→  total_lots?: string;
 21→  lots_under_control?: string;
 22→};
 23→
 24→const validateCommunityName = (value: string): string | undefined => {
 25→  const trimmed = value.trim();
 26→  if (!trimmed) return 'Community name is required';
 27→  if (trimmed.length < 2) return 'Community name must be at least 2 characters';
 28→  if (trimmed.length > 100) return 'Community name must be less than 100 characters';
 29→  return undefined;
 30→};
 31→
 32→const validateAddress = (value: string): string | undefined => {
 33→  if (!value) return 'Street address is required';
 34→  if (value.length > 255) return 'Street address must be less than 255 characters';
 35→  return undefined;
 36→};
 37→
 38→const validateRequiredLots = (value: string, requiredMessage: string): string | undefined => {
 39→  if (!value) return requiredMessage;
 40→  const num = parseInt(value, 10);
 41→  if (isNaN(num) || !Number.isInteger(parseFloat(value))) return 'Must be a whole number';
 42→  if (num < 0) return 'Cannot be negative';
 43→  if (num > 999999) return 'Cannot exceed 999,999';
 44→  return undefined;
 45→};
 46→
 47→export default function AddCommunityForm() {
 48→  const [formData, setFormData] = useState<FormData>({
 49→    name: '',
 50→    address: '',
 51→    status: 'Active',
 52→    total_lots: '',
 53→    lots_under_control: '',
 54→  });
 55→  const [errors, setErrors] = useState<FormErrors>({});
 56→  const [loading, setLoading] = useState(false);
 57→  const [submitError, setSubmitError] = useState<string | null>(null);
 58→
 59→  const validateField = (fieldName: keyof FormData, value: string): string | undefined => {
 60→    if (fieldName === 'name') {
 61→      return validateCommunityName(value);
 62→    }
 63→
 64→    if (fieldName === 'address') {
 65→      return validateAddress(value);
 66→    }
 67→
 68→    if (fieldName === 'status') {
 69→      if (!value) return 'Status is required';
 70→      return undefined;
 71→    }
 72→
 73→    if (fieldName === 'total_lots') {
 74→      return validateRequiredLots(value, 'Total lots is required');
 75→    }
 76→
 77→    if (fieldName === 'lots_under_control') {
 78→      const lotsError = validateRequiredLots(value, 'Lots under control is required');
 79→      if (lotsError) return lotsError;
 80→      const lotsUnderControl = parseInt(value, 10);
 81→      const totalLots = parseInt(formData.total_lots, 10);
 82→      if (!isNaN(totalLots) && lotsUnderControl > totalLots) {
 83→        return 'Lots under control cannot exceed total lots';
 84→      }
 85→    }
 86→
 87→    return undefined;
 88→  };
 89→
 90→  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
 91→    const { name, value } = e.target;
 92→    setFormData({
 93→      ...formData,
 94→      [name]: value,
 95→    });
 96→    // Clear error for this field when user starts typing
 97→    if (errors[name as keyof FormErrors]) {
 98→      setErrors({
 99→        ...errors,
100→        [name]: undefined,
101→      });
102→    }
103→  };
104→
105→  const handleBlur = (e: React.FocusEvent<HTMLInputElement | HTMLSelectElement>) => {
106→    const { name, value } = e.target;
107→    const error = validateField(name as keyof FormData, value);
108→    if (error) {
109→      setErrors({
110→        ...errors,
111→        [name]: error,
112→      });
113→    }
114→  };
115→
116→  const validateAllFields = (): boolean => {
117→    const newErrors: FormErrors = {};
118→    let isValid = true;
119→
120→    (Object.keys(formData) as Array<keyof FormData>).forEach((fieldName) => {
121→      const error = validateField(fieldName, formData[fieldName]);
122→      if (error) {
123→        newErrors[fieldName] = error;
124→        isValid = false;
125→      }
126→    });
127→
128→    setErrors(newErrors);
129→    return isValid;
130→  };
131→
132→  const handleSubmit = async (e: React.FormEvent) => {
133→    e.preventDefault();
134→    setSubmitError(null);
135→
136→    // Validate all fields
137→    if (!validateAllFields()) {
138→      return;
139→    }
140→
141→    setLoading(true);
142→
143→    try {
144→      // Get current authenticated user
145→      const { data: { user }, error: userError } = await supabase.auth.getUser();
146→
147→      if (userError || !user) {
148→        setSubmitError('Your session has expired. Please sign in again.');
149→        setTimeout(() => {
150→          window.location.href = '/';
151→        }, 2000);
152→        return;
153→      }
154→
155→      // Insert community
156→      const { data, error: insertError } = await supabase
157→        .from('communities')
158→        .insert({
159→          user_id: user.id,
160→          name: formData.name.trim(),
161→          address: formData.address,
162→          status: formData.status,
163→          total_lots: parseInt(formData.total_lots),
164→          lots_under_control: parseInt(formData.lots_under_control),
165→        })
166→        .select()
167→        .single();
168→
169→      if (insertError) throw insertError;
170→
171→      // Success - navigate to new community dashboard
172→      window.location.href = `/communities/${data.id}`;
173→    } catch (err: any) {
174→      console.error('Error creating community:', err);
175→      setSubmitError('Failed to create community. Please try again.');
176→      setLoading(false);
177→    }
178→  };
179→
180→  const handleCancel = () => {
181→    window.location.href = '/communities';
182→  };
183→
184→  return (
185→    <div className="max-w-2xl mx-auto space-y-6">
186→      {/* Form Card */}
187→      <div className="bg-white rounded-lg shadow-sm p-8">
188→        <h1 className="text-3xl font-bold text-ink mb-6">Add New Community</h1>
189→
190→        {submitError && (
191→          <div className="bg-red-50 text-red-600 p-4 rounded-lg mb-6">
192→            {submitError}
193→          </div>
194→        )}
195→
196→        <form onSubmit={handleSubmit} className="space-y-6">
197→          <CommunityNameAddressFields
198→            values={formData}
199→            errors={errors}
200→            onChange={handleChange}
201→            onBlur={handleBlur}
202→          />
203→          <CommunityStatusLotsFields
204→            values={formData}
205→            errors={errors}
206→            onChange={handleChange}
207→            onBlur={handleBlur}
208→          />
209→
210→          {/* Submit Buttons */}
211→          <div className="flex gap-4 pt-4">
212→            <button
213→              type="button"
214→              onClick={handleCancel}
215→              disabled={loading}
216→              className="flex-1 bg-white border-2 border-ink-muted text-ink-muted font-semibold px-6 py-3 rounded-lg hover:bg-gray-50 transition-colors ease-out disabled:opacity-50 disabled:cursor-not-allowed"
217→            >
218→              Cancel
219→            </button>
220→            <button
221→              type="submit"
222→              disabled={loading}
223→              className="flex-1 bg-brand hover:bg-brand-hover text-white font-semibold px-6 py-3 rounded-lg transition-colors ease-out disabled:opacity-50 disabled:cursor-not-allowed"
224→            >
225→              {loading ? 'Adding...' : 'Add Community'}
226→            </button>
227→          </div>
228→        </form>
229→
230→        {/* Bulk Import Link */}
231→        <div className="mt-8 pt-8 border-t border-gray-200">
232→          <a
233→            href="/admin/import"
234→            className="block w-full text-center border-2 border-dashed border-brand text-brand hover:bg-brand hover:text-white font-semibold px-6 py-4 rounded-lg transition-colors ease-out"
235→          >
236→            📁 Import Multiple Communities from ERP
237→          </a>
238→        </div>
239→      </div>
240→    </div>
241→  );
242→}
