  1→import { useState, useEffect, useRef, useId, type ReactNode } from 'react';
  2→import { createPortal } from 'react-dom';
  3→
  4→type DrawerProps = {
  5→  open: boolean;
  6→  onClose: () => void;
  7→  title: string;
  8→  subtitle?: string;
  9→  triggerId?: string;
 10→  children: ReactNode;
 11→  'data-testid'?: string;
 12→};
 13→
 14→export default function Drawer({
 15→  open,
 16→  onClose,
 17→  title,
 18→  subtitle,
 19→  triggerId,
 20→  children,
 21→  'data-testid': testId,
 22→}: DrawerProps) {
 23→  const titleId = useId();
 24→  const headingRef = useRef<HTMLHeadingElement>(null);
 25→  const [closing, setClosing] = useState(false);
 26→  const [wasOpen, setWasOpen] = useState(false);
 27→
 28→  // Track whether the drawer is rendering (open or closing animation)
 29→  const shouldRender = open || closing;
 30→
 31→  // Handle open → close transition: play exit animation before unmounting
 32→  useEffect(() => {
 33→    if (!open && wasOpen) {
 34→      setClosing(true);
 35→      const timer = setTimeout(() => {
 36→        setClosing(false);
 37→        // Return focus to trigger element
 38→        if (triggerId) {
 39→          const trigger = document.getElementById(triggerId);
 40→          trigger?.focus();
 41→        }
 42→      }, 220); // matches drawer-out 0.2s + buffer
 43→      return () => clearTimeout(timer);
 44→    }
 45→    setWasOpen(open);
 46→  }, [open, triggerId, wasOpen]);
 47→
 48→  // Focus heading when drawer opens
 49→  useEffect(() => {
 50→    if (open) {
 51→      requestAnimationFrame(() => {
 52→        headingRef.current?.focus();
 53→      });
 54→    }
 55→  }, [open]);
 56→
 57→  // Escape key handler
 58→  useEffect(() => {
 59→    if (!open) return;
 60→    const onKey = (e: KeyboardEvent) => {
 61→      if (e.key === 'Escape') {
 62→        onClose();
 63→      }
 64→    };
 65→    document.addEventListener('keydown', onKey);
 66→    return () => document.removeEventListener('keydown', onKey);
 67→  }, [open, onClose]);
 68→
 69→  if (!shouldRender) return null;
 70→
 71→  const animClass = open && !closing ? 'animate-drawer-in' : 'animate-drawer-out';
 72→
 73→  return createPortal(
 74→    <aside
 75→      role="complementary"
 76→      aria-labelledby={titleId}
 77→      data-testid={testId}
 78→      className={`fixed top-0 right-0 h-full w-[480px] max-w-full z-40 bg-white flex flex-col shadow-[-4px_0_16px_rgba(0,0,0,0.08)] ${animClass}`}
 79→    >
 80→      {/* Header */}
 81→      <div className="flex items-start justify-between px-5 pt-5 pb-3 border-b border-gray-200">
 82→        <div className="min-w-0">
 83→          <h2
 84→            ref={headingRef}
 85→            id={titleId}
 86→            className="text-lg font-semibold text-ink truncate"
 87→            tabIndex={-1}
 88→          >
 89→            {title}
 90→          </h2>
 91→          {subtitle && (
 92→            <p className="text-sm text-ink-muted mt-0.5 truncate">{subtitle}</p>
 93→          )}
 94→        </div>
 95→        <button
 96→          type="button"
 97→          aria-label="Close drawer"
 98→          onClick={onClose}
 99→          className="ml-3 p-1 rounded-md text-ink-muted hover:text-ink hover:bg-gray-100 transition-colors ease-out flex-shrink-0"
100→        >
101→          <svg
102→            className="w-5 h-5"
103→            fill="none"
104→            stroke="currentColor"
105→            viewBox="0 0 24 24"
106→            aria-hidden="true"
107→          >
108→            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
109→          </svg>
110→        </button>
111→      </div>
112→
113→      {/* Scrollable content */}
114→      <div className="flex-1 overflow-y-auto px-5 py-4">
115→        {children}
116→      </div>
117→    </aside>,
118→    document.body,
119→  );
120→}
