  4→
  5→interface FileUploadStepProps {
  6→  onFileParsed: Dispatch<ParseResult>;
  7→  onNext: () => void;
  8→}
  9→
 10→export default function FileUploadStep({ onFileParsed, onNext }: FileUploadStepProps) {
 11→  const [isDragging, setIsDragging] = useState(false);
 12→  const [isProcessing, setIsProcessing] = useState(false);
 13→  const [error, setError] = useState<string | null>(null);
 14→  const [uploadedFile, setUploadedFile] = useState<File | null>(null);
 15→
 16→  const handleFile = async (file: File) => {
 17→    // Validate file type
 18→    const validExtensions = ['.csv', '.xlsx', '.xls'];
 19→    const fileExtension = '.' + file.name.split('.').pop()?.toLowerCase();
 20→
 21→    if (!validExtensions.includes(fileExtension)) {
 22→      setError('Invalid file type. Please upload a CSV or Excel file (.csv, .xlsx, .xls)');
 23→      return;
 24→    }
 25→
 26→    setError(null);
 27→    setIsProcessing(true);
 28→    setUploadedFile(file);
 29→
 30→    try {
 31→      const result = await parseFile(file);
 32→
 33→      if (result.rows.length === 0) {
 34→        setError('No data found in file. Please check your file and try again.');
 35→        setIsProcessing(false);
 36→        return;
 37→      }
 38→
 39→      onFileParsed(result);
 40→      setIsProcessing(false);
 41→
 42→      // Auto-advance to next step after short delay
 43→      setTimeout(() => {
 44→        onNext();
 45→      }, 500);
 46→    } catch (err) {
 47→      setError(err instanceof Error ? err.message : 'Failed to parse file');
 48→      setIsProcessing(false);
 49→    }
 50→  };
 51→
 52→  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
 53→    e.preventDefault();
 54→    setIsDragging(false);
 55→
 56→    const files = e.dataTransfer.files;
 57→    if (files.length > 0) {
 58→      handleFile(files[0]);
 59→    }
 60→  };
 61→
 62→  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
 63→    e.preventDefault();
 64→    setIsDragging(true);
 65→  };
 66→
 67→  const handleDragLeave = () => {
 68→    setIsDragging(false);
 69→  };
 70→
 71→  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
 72→    const files = e.target.files;
 73→    if (files && files.length > 0) {
 74→      handleFile(files[0]);
 75→    }
 76→  };
 77→
 78→  return (
 79→    <div className="space-y-6">
 80→      <div>
 81→        <h2 className="text-2xl font-semibold text-ink mb-2">
 82→          Upload File
 83→        </h2>
 84→        <p className="text-ink-muted">
 85→          Upload a CSV or Excel file containing your option library data.
 86→        </p>
 87→      </div>
 88→
 89→      {/* Drag and Drop Area */}
 90→      <div
 91→        onDrop={handleDrop}
 92→        onDragOver={handleDragOver}
 93→        onDragLeave={handleDragLeave}
 94→        className={`
 95→          relative border-2 border-dashed rounded-lg p-12 text-center transition-colors ease-out
 96→          ${isDragging ? 'border-brand bg-orange-50' : 'border-gray-300 bg-white'}
 97→          ${isProcessing ? 'opacity-50 pointer-events-none' : 'cursor-pointer hover:border-brand'}
 98→        `}
 99→      >
100→        <input
101→          type="file"
102→          accept=".csv,.xlsx,.xls"
103→          onChange={handleFileSelect}
104→          className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
105→          disabled={isProcessing}
106→        />
107→
108→        <div className="space-y-4">
109→          {isProcessing ? (
110→            <>
111→              <div className="text-6xl">⏳</div>
112→              <div className="text-lg font-medium text-ink">
113→                Processing file...
114→              </div>
115→              {uploadedFile && (
116→                <div className="text-sm text-ink-muted">
117→                  {uploadedFile.name}
118→                </div>
119→              )}
120→            </>
121→          ) : uploadedFile ? (
122→            <>
123→              <div className="text-6xl">✅</div>
124→              <div className="text-lg font-medium text-status-success">
125→                File uploaded successfully!
126→              </div>
127→              <div className="text-sm text-ink-muted">
128→                {uploadedFile.name}
129→              </div>
130→            </>
131→          ) : (
132→            <>
133→              <div className="text-6xl">📁</div>
134→              <div className="text-lg font-medium text-ink">
135→                Drag and drop your file here
136→              </div>
137→              <div className="text-sm text-ink-muted">
138→                or click to browse
139→              </div>
140→              <div className="text-xs text-ink-muted mt-2">
141→                Supported formats: CSV, XLSX, XLS
142→              </div>
143→            </>
144→          )}
145→        </div>
146→      </div>
147→
148→      {/* Error Message */}
149→      {error && (
150→        <div className="bg-red-50 border border-red-200 rounded-lg p-4">

  1→import { useEffect, useState } from 'react';
  2→import LotFormFields from './LotFormFields';
  3→import { buildLotPayload, redirectToCommunity, submitLot, type LotFormValues } from './lotFormUtils';
  4→import { LotFormLoading, LotFormNotFound, LotFormShell } from './LotFormShell';
  5→
  6→type LotFormProps = {
  7→  communityId: string;
  8→  lotId?: string;
  9→  mode: 'add' | 'edit';
 10→};
 11→
 12→type Community = {
 13→  id: string;
 14→  name: string;
 15→};
 16→
 17→type Lot = {
 18→  id: string;
 19→  lot_number: string;
 20→  width: number;
 21→  depth: number;
 22→  premium_cost: number;
 23→  premium_price: number;
 24→  status: 'available' | 'reserved' | 'sold';
 25→  constraints?: string[];
 26→  notes?: string;
 27→};
 28→
 29→function applyLotToForm(lot: Lot, setValues: (values: LotFormValues) => void) {
 30→  setValues({
 31→    lotNumber: lot.lot_number || '',
 32→    width: String(lot.width || ''),
 33→    depth: String(lot.depth || ''),
 34→    premiumCost: String(lot.premium_cost || 0),
 35→    premiumPrice: String(lot.premium_price || 0),
 36→    status: lot.status || 'available',
 37→    constraints: lot.constraints?.join(', ') || '',
 38→    notes: lot.notes || '',
 39→  });
 40→}
 41→
 42→const EMPTY_VALUES: LotFormValues = {
 43→  lotNumber: '',
 44→  width: '',
 45→  depth: '',
 46→  premiumCost: '0',
 47→  premiumPrice: '0',
 48→  status: 'available',
 49→  constraints: '',
 50→  notes: '',
 51→};
 52→
 53→export default function LotForm({ communityId, lotId, mode }: LotFormProps) {
 54→  const [community, setCommunity] = useState<Community | null>(null);
 55→  const [lot, setLot] = useState<Lot | null>(null);
 56→  const [values, setValues] = useState<LotFormValues>(EMPTY_VALUES);
 57→  const [loading, setLoading] = useState(false);
 58→  const [loadingData, setLoadingData] = useState(true);
 59→  const [error, setError] = useState<string | null>(null);
 60→
 61→  useEffect(() => {
 62→    const fetchData = async () => {
 63→      try {
 64→        setLoadingData(true);
 65→        setError(null);
 66→
 67→        const communityResponse = await fetch(`/api/communities/${communityId}`);
 68→        if (!communityResponse.ok) {
 69→          throw new Error('Failed to fetch community');
 70→        }
 71→
 72→        const communityData = (await communityResponse.json()) as Community;
 73→        setCommunity(communityData);
 74→
 75→        if (mode === 'edit') {
 76→          if (!lotId) throw new Error('Missing lot id');
 77→
 78→          const lotResponse = await fetch(`/api/lots/${lotId}`);
 79→          if (!lotResponse.ok) {
 80→            throw new Error('Failed to fetch lot');
 81→          }
 82→
 83→          const lotData = (await lotResponse.json()) as Lot;
 84→          setLot(lotData);
 85→          applyLotToForm(lotData, setValues);
 86→        }
 87→      } catch (err: unknown) {
 88→        setError(err instanceof Error ? err.message : 'Failed to load data');
 89→      } finally {
 90→        setLoadingData(false);
 91→      }
 92→    };
 93→
 94→    fetchData();
 95→  }, [communityId, lotId, mode]);
 96→
 97→  const handleCancel = () => {
 98→    redirectToCommunity(communityId);
 99→  };
100→
101→  const handleSubmit = async (e: React.FormEvent) => {
102→    e.preventDefault();
103→    setError(null);
104→
105→    if (!values.lotNumber || !values.width || !values.depth) {
106→      setError('Please fill in all required fields');
107→      return;
108→    }
109→
110→    try {
111→      setLoading(true);
112→      const payload = buildLotPayload(values);
113→      const isEdit = mode === 'edit';
114→
115→      await submitLot({
116→        url: isEdit ? `/api/lots/${lotId}` : '/api/lots',
117→        method: isEdit ? 'PUT' : 'POST',
118→        payload: isEdit ? payload : { ...payload, community_id: communityId },
119→        fallbackError: isEdit ? 'Failed to update lot' : 'Failed to add lot',
120→      });
121→
122→      redirectToCommunity(communityId);
123→    } catch (err: unknown) {
124→      const fallback = mode === 'edit' ? 'Failed to update lot' : 'Failed to add lot';
125→      setError(err instanceof Error ? err.message : fallback);
126→    } finally {
127→      setLoading(false);
128→    }
129→  };
130→
131→  if (loadingData) {
132→    return <LotFormLoading />;
133→  }
134→
135→  const notFound = !community || (mode === 'edit' && !lot);
136→  if (notFound) {
137→    return (
138→      <LotFormNotFound
139→        title={mode === 'edit' ? 'Lot Not Found' : 'Community Not Found'}
140→        description={mode === 'edit' ? 'Unable to load lot data.' : 'Unable to load community data.'}
141→      />
142→    );
143→  }
144→
145→  const isEdit = mode === 'edit';
146→  const title = isEdit ? `Edit Lot ${lot?.lot_number ?? ''}` : 'Add Lot';
147→  const subtitle = isEdit ? 'Update lot information for {community}' : 'Add a new lot to {community} inventory';
148→
149→  return (
150→    <LotFormShell
151→      communityName={community.name}
152→      title={title}
153→      subtitle={subtitle}
154→      error={error}
155→    >
156→      <form onSubmit={handleSubmit} className="space-y-6">
157→        <LotFormFields
158→          lotNumber={values.lotNumber}
159→          setLotNumber={(lotNumber) => setValues((prev) => ({ ...prev, lotNumber }))}
