import type { ButtonHTMLAttributes, AnchorHTMLAttributes, ReactNode } from 'react';

type ButtonVariant = 'primary' | 'secondary' | 'text' | 'danger';
type ButtonSize = 'sm' | 'md' | 'lg';

type BaseProps = {
  variant?: ButtonVariant;
  size?: ButtonSize;
  loading?: boolean;
  children: ReactNode;
  className?: string;
};

type AsButton = BaseProps &
  Omit<ButtonHTMLAttributes<HTMLButtonElement>, keyof BaseProps> & {
    href?: never;
  };

type AsAnchor = BaseProps &
  Omit<AnchorHTMLAttributes<HTMLAnchorElement>, keyof BaseProps> & {
    href: string;
  };

type ButtonProps = AsButton | AsAnchor;

const VARIANT_CLASSES: Record<ButtonVariant, string> = {
  primary:
    'bg-brand hover:bg-brand-hover text-white font-semibold rounded-lg transition-colors ease-out disabled:opacity-50 disabled:cursor-not-allowed',
  secondary:
    'bg-white border border-gray-300 text-ink font-medium rounded-lg hover:bg-gray-50 transition-colors ease-out disabled:opacity-50 disabled:cursor-not-allowed',
  text: 'text-brand hover:text-brand-hover font-medium transition-colors ease-out disabled:opacity-50',
  danger: 'text-red-700 hover:text-red-900 font-medium transition-colors ease-out disabled:opacity-50',
};

const SIZE_CLASSES: Record<ButtonSize, string> = {
  sm: 'px-3 py-1.5 text-sm',
  md: 'px-4 py-2 text-sm',
  lg: 'px-6 py-3',
};

export default function Button(props: ButtonProps) {
  const {
    variant = 'primary',
    size = 'md',
    loading = false,
    children,
    className = '',
    ...rest
  } = props;

  const classes = `${VARIANT_CLASSES[variant]} ${SIZE_CLASSES[size]} ${className}`.trim();

  const content = loading ? (
    <span className="inline-flex items-center gap-2">
      <span className="inline-block h-4 w-4 animate-spin rounded-full border-2 border-solid border-current border-r-transparent" />
      {children}
    </span>
  ) : (
    children
  );

  if ('href' in props && props.href) {
    const { href, variant: _v, size: _s, loading: _l, ...anchorRest } = props as AsAnchor;
    return (
      <a href={href} className={classes} {...anchorRest}>
        {content}
      </a>
    );
  }

  const { variant: _v, size: _s, loading: _l, ...buttonRest } = rest as Omit<AsButton, keyof BaseProps>;
  return (
    <button
      className={classes}
      disabled={loading || (rest as AsButton).disabled}
      {...buttonRest}
    >
      {content}
    </button>
  );
}

