import { describe, it, expect } from 'vitest';
import { render, screen } from '@testing-library/react';
import PricePositionIndicator from './PricePositionIndicator';

describe('PricePositionIndicator 4-band', () => {
  it('shows "Overpriced" for >+10% difference', () => {
    render(
      <PricePositionIndicator propertyPricePerSqft={222} marketMedianPricePerSqft={200} />
    );
    expect(screen.getByTestId('price-position-badge')).toHaveTextContent('Overpriced');
    expect(screen.getByTestId('price-position-badge')).toHaveTextContent('+11%');
  });

  it('shows "Above Market" for +5% to +10% difference', () => {
    render(
      <PricePositionIndicator propertyPricePerSqft={214} marketMedianPricePerSqft={200} />
    );
    expect(screen.getByTestId('price-position-badge')).toHaveTextContent('Above Market');
    expect(screen.getByTestId('price-position-badge')).toHaveTextContent('+7%');
  });

  it('shows "Aligned" for -5% to +5% difference', () => {
    render(
      <PricePositionIndicator propertyPricePerSqft={204} marketMedianPricePerSqft={200} />
    );
    expect(screen.getByTestId('price-position-badge')).toHaveTextContent('Aligned');
    expect(screen.getByTestId('price-position-badge')).toHaveTextContent('+2%');
  });

  it('shows "Below Market" for <-5% difference', () => {
    render(
      <PricePositionIndicator propertyPricePerSqft={180} marketMedianPricePerSqft={200} />
    );
    expect(screen.getByTestId('price-position-badge')).toHaveTextContent('Below Market');
    expect(screen.getByTestId('price-position-badge')).toHaveTextContent('-10%');
  });

  it('shows "Aligned" at exactly +5% (boundary)', () => {
    render(
      <PricePositionIndicator propertyPricePerSqft={210} marketMedianPricePerSqft={200} />
    );
    expect(screen.getByTestId('price-position-badge')).toHaveTextContent('Aligned');
  });

  it('shows "Above Market" just above +5% boundary', () => {
    render(
      <PricePositionIndicator propertyPricePerSqft={210.2} marketMedianPricePerSqft={200} />
    );
    expect(screen.getByTestId('price-position-badge')).toHaveTextContent('Above Market');
  });

  it('shows "Above Market" at exactly +10% (boundary)', () => {
    render(
      <PricePositionIndicator propertyPricePerSqft={220} marketMedianPricePerSqft={200} />
    );
    expect(screen.getByTestId('price-position-badge')).toHaveTextContent('Above Market');
  });

  it('shows "Overpriced" just above +10% boundary', () => {
    render(
      <PricePositionIndicator propertyPricePerSqft={220.2} marketMedianPricePerSqft={200} />
    );
    expect(screen.getByTestId('price-position-badge')).toHaveTextContent('Overpriced');
  });

  it('shows "Aligned" at exactly -5% (boundary)', () => {
    render(
      <PricePositionIndicator propertyPricePerSqft={190} marketMedianPricePerSqft={200} />
    );
    expect(screen.getByTestId('price-position-badge')).toHaveTextContent('Aligned');
  });

  it('shows "Below Market" just below -5% boundary', () => {
    render(
      <PricePositionIndicator propertyPricePerSqft={189.8} marketMedianPricePerSqft={200} />
    );
    expect(screen.getByTestId('price-position-badge')).toHaveTextContent('Below Market');
  });

  it('applies red styling for overpriced', () => {
    render(
      <PricePositionIndicator propertyPricePerSqft={230} marketMedianPricePerSqft={200} />
    );
    const badge = screen.getByTestId('price-position-badge');
    expect(badge.className).toContain('bg-red-50');
    expect(badge.className).toContain('text-red-700');
  });

  it('applies amber styling for above-market', () => {
    render(
      <PricePositionIndicator propertyPricePerSqft={214} marketMedianPricePerSqft={200} />
    );
    const badge = screen.getByTestId('price-position-badge');
    expect(badge.className).toContain('bg-amber-50');
    expect(badge.className).toContain('text-amber-600');
  });

  it('applies green styling for aligned', () => {
    render(
      <PricePositionIndicator propertyPricePerSqft={200} marketMedianPricePerSqft={200} />
    );
    const badge = screen.getByTestId('price-position-badge');
    expect(badge.className).toContain('bg-green-50');
    expect(badge.className).toContain('text-green-700');
  });

  it('applies blue styling for below-market', () => {
    render(
      <PricePositionIndicator propertyPricePerSqft={180} marketMedianPricePerSqft={200} />
    );
    const badge = screen.getByTestId('price-position-badge');
    expect(badge.className).toContain('bg-blue-100');
    expect(badge.className).toContain('text-blue-500');
  });

  it('shows placeholder when property price is null', () => {
    render(
      <PricePositionIndicator propertyPricePerSqft={null} marketMedianPricePerSqft={200} />
    );
    expect(screen.getByText('—')).toBeInTheDocument();
  });

  it('shows placeholder when market median is null', () => {
    render(
      <PricePositionIndicator propertyPricePerSqft={200} marketMedianPricePerSqft={null} />
    );
    expect(screen.getByText('—')).toBeInTheDocument();
  });

  it('shows placeholder when market median is 0', () => {
    render(
      <PricePositionIndicator propertyPricePerSqft={200} marketMedianPricePerSqft={0} />
    );
    expect(screen.getByText('—')).toBeInTheDocument();
  });
});

