/**
 * Shared status color helpers for consistent badge, icon, and alert styling.
 *
 * Badge text uses high-contrast -700 shades (WCAG AA on light backgrounds).
 * Icon colors use design tokens (acceptable at 3:1 non-text ratio).
 */

export type StatusLevel = 'success' | 'warning' | 'danger' | 'info' | 'neutral';

/** Badge / pill classes — high-contrast text for accessibility. */
export function statusClasses(level: StatusLevel): { bg: string; text: string; border: string } {
  switch (level) {
    case 'success':
      return { bg: 'bg-green-50', text: 'text-green-700', border: 'border-green-200' };
    case 'warning':
      return { bg: 'bg-amber-50', text: 'text-amber-600', border: 'border-amber-200' };
    case 'danger':
      return { bg: 'bg-red-50', text: 'text-red-700', border: 'border-red-200' };
    case 'info':
      return { bg: 'bg-blue-100', text: 'text-blue-700', border: 'border-blue-200' };
    case 'neutral':
      return { bg: 'bg-gray-100', text: 'text-gray-500', border: 'border-gray-200' };
  }
}

/** Icon colors — uses design tokens (lower contrast OK for non-text). */
export const STATUS_ICON_COLORS: Record<StatusLevel, string> = {
  success: 'text-status-success',
  warning: 'text-status-warning',
  danger: 'text-status-danger',
  info: 'text-status-info',
  neutral: 'text-status-neutral',
};

