import { useState, useCallback, createContext, useContext, type Dispatch } from 'react';

type ToastType = 'success' | 'error' | 'info' | 'warning';

interface Toast {
  id: string;
  type: ToastType;
  message: string;
  duration?: number;
}

type ToastPayload = {
  type: ToastType;
  message: string;
  duration?: number;
};

interface ToastContextValue {
  toasts: Toast[];
  showToast: Dispatch<ToastPayload>;
  dismissToast: Dispatch<string>;
}

const ToastContext = createContext<ToastContextValue | null>(null);

export function useToast() {
  const context = useContext(ToastContext);
  if (!context) {
    throw new Error('useToast must be used within a ToastProvider');
  }
  return context;
}

interface ToastProviderProps {
  children: React.ReactNode;
}

export function ToastProvider({ children }: ToastProviderProps) {
  const [toasts, setToasts] = useState<Toast[]>([]);

  const dismissToast = useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  const showToast = useCallback((payload: ToastPayload) => {
    const { type, message, duration = 4000 } = payload;
    const id = `toast-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    const toast: Toast = { id, type, message, duration };

    setToasts((prev) => [...prev, toast]);

    if (duration > 0) {
      setTimeout(() => {
        dismissToast(id);
      }, duration);
    }
  }, [dismissToast]);

  return (
    <ToastContext.Provider value={{ toasts, showToast, dismissToast }}>
      {children}
      <ToastContainer toasts={toasts} onDismiss={dismissToast} />
    </ToastContext.Provider>
  );
}

interface ToastContainerProps {
  toasts: Toast[];
  onDismiss: Dispatch<string>;
}

function ToastContainer({ toasts, onDismiss }: ToastContainerProps) {
  if (toasts.length === 0) return null;

  return (
    <div className="fixed bottom-4 right-4 z-[60] flex flex-col gap-2 max-w-sm">
      {toasts.map((toast) => (
        <ToastItem key={toast.id} toast={toast} onDismiss={onDismiss} />
      ))}
    </div>
  );
}

interface ToastItemProps {
  toast: Toast;
  onDismiss: Dispatch<string>;
}

function ToastItem({ toast, onDismiss }: ToastItemProps) {
  const [isExiting, setIsExiting] = useState(false);

  const handleDismiss = () => {
    setIsExiting(true);
    setTimeout(() => onDismiss(toast.id), 200);
  };

  const getStyles = () => {
    switch (toast.type) {
      case 'success':
        return 'bg-green-50 border-green-200 text-green-700';
      case 'error':
        return 'bg-red-50 border-red-200 text-red-700';
      case 'warning':
        return 'bg-amber-50 border-amber-200 text-amber-600';
      case 'info':
      default:
        return 'bg-blue-50 border-blue-200 text-blue-700';
    }
  };

  const getIcon = () => {
    switch (toast.type) {
      case 'success':
        return (
          <svg className="w-5 h-5 text-status-success" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
          </svg>
        );
      case 'error':
        return (
          <svg className="w-5 h-5 text-status-danger" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
        );
      case 'warning':
        return (
          <svg className="w-5 h-5 text-status-warning" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
          </svg>
        );
      case 'info':
      default:
        return (
          <svg className="w-5 h-5 text-status-info" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
        );
    }
  };

  return (
    <div
      className={`
        flex items-start gap-3 p-4 rounded-lg border shadow-lg
        ${getStyles()}
        ${isExiting ? 'animate-slide-out' : 'animate-slide-in'}
      `}
      role="alert"
      aria-live="polite"
    >
      <span className="flex-shrink-0">{getIcon()}</span>
      <p className="flex-1 text-sm font-medium">{toast.message}</p>
      <button
        onClick={handleDismiss}
        className="flex-shrink-0 opacity-70 hover:opacity-100 transition-opacity ease-out focus-visible:ring-2 focus-visible:ring-brand/40 focus-visible:ring-offset-2 focus-visible:outline-hidden rounded"
        aria-label="Dismiss"
      >
        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
        </svg>
      </button>
    </div>
  );
}

// Standalone toast function for use outside React components
let globalShowToast: ToastContextValue['showToast'] | null = null;

export function setGlobalToastHandler(handler: ToastContextValue['showToast']) {
  globalShowToast = handler;
}

export function toast(payload: ToastPayload) {
  if (globalShowToast) {
    globalShowToast(payload);
  } else {
    console.warn('Toast called before ToastProvider mounted');
  }
}

/**
 * Standalone toast hook that doesn't require a Provider.
 * Use this in components that need toast notifications without wrapping in ToastProvider.
 * Returns: { toasts, showToast, dismissToast, ToastContainer }
 */
export function useLocalToast() {
  const [toasts, setToasts] = useState<Toast[]>([]);

  const dismissToast = useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  const showToast = useCallback((payload: ToastPayload) => {
    const { type, message, duration = 4000 } = payload;
    const id = `toast-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    const newToast: Toast = { id, type, message, duration };

    setToasts((prev) => [...prev, newToast]);

    if (duration > 0) {
      setTimeout(() => {
        dismissToast(id);
      }, duration);
    }
  }, [dismissToast]);

  // Render function for the toast container
  const renderToasts = () => {
    if (toasts.length === 0) return null;
    return (
      <div className="fixed bottom-4 right-4 z-[60] flex flex-col gap-2 max-w-sm">
        {toasts.map((t) => (
          <ToastItem key={t.id} toast={t} onDismiss={dismissToast} />
        ))}
      </div>
    );
  };

  return {
    toasts,
    showToast,
    dismissToast,
    renderToasts,
  };
}

import Tooltip from '../ui/Tooltip';

type PricePositionIndicatorProps = {
  propertyPricePerSqft: number | null;
  marketMedianPricePerSqft: number | null;
  compCount?: number;
};

type PositionCategory = 'overpriced' | 'above-market' | 'aligned' | 'below-market';

function getPositionCategory(percentDiff: number): PositionCategory {
  if (percentDiff > 10) return 'overpriced';
  if (percentDiff > 5) return 'above-market';
  if (percentDiff < -5) return 'below-market';
  return 'aligned';
}

function formatPercentage(percentDiff: number): string {
  const sign = percentDiff >= 0 ? '+' : '';
  return `${sign}${Math.round(percentDiff)}%`;
}

const categoryStyles: Record<PositionCategory, string> = {
  overpriced: 'text-red-700 bg-red-50',
  'above-market': 'text-amber-600 bg-amber-50',
  aligned: 'text-green-700 bg-green-50',
  'below-market': 'text-blue-700 bg-blue-100',
};

const categoryLabels: Record<PositionCategory, string> = {
  overpriced: 'Overpriced',
  'above-market': 'Above Market',
  aligned: 'Aligned',
  'below-market': 'Below Market',
};

export default function PricePositionIndicator({
  propertyPricePerSqft,
  marketMedianPricePerSqft,
  compCount,
}: PricePositionIndicatorProps) {
  // Return placeholder if either value is null
  if (propertyPricePerSqft === null || marketMedianPricePerSqft === null) {
    return <span className="text-gray-400">—</span>;
  }

  // Avoid division by zero
  if (marketMedianPricePerSqft === 0) {
    return <span className="text-gray-400">—</span>;
  }

  // Calculate percentage difference: (property - market) / market * 100
  const percentDiff = ((propertyPricePerSqft - marketMedianPricePerSqft) / marketMedianPricePerSqft) * 100;
  const category = getPositionCategory(percentDiff);

  const tooltip = compCount != null && compCount > 0 ? `vs. ${compCount} comps` : undefined;
  const showLowCompCount = compCount != null && compCount >= 1 && compCount <= 2;

  return (
    <span className="inline-flex items-center gap-1">
      <Tooltip
        content={<>
          <strong className="block mb-1">Price Position vs. Market</strong>
          Price per sqft compared to median of sold comps.
          Overpriced: &gt;10% above market. Above Market: 5–10% above. Aligned: within ±5%. Below Market: &gt;5% below.
          {tooltip && <span className="block mt-1 text-white/70">{tooltip}</span>}
        </>}
        position="top"
        width="w-56"
      >
        <span
          className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${categoryStyles[category]}`}
          data-testid="price-position-badge"
        >
          {categoryLabels[category]} {formatPercentage(percentDiff)}
        </span>
      </Tooltip>
      {showLowCompCount && (
        <span className="text-[10px] text-ink-muted/60 font-normal" data-testid="low-comp-count">
          ({compCount} comp{compCount !== 1 ? 's' : ''})
        </span>
      )}
    </span>
  );
}

