};

type JobLotRow = {
  lot: string | null;
  job: string | null;
  address: string | null;
  lot_premium: number | null;
  lot_information: string | null;
  garage: string | null;
  acres: number | null;
  plan: string | null;
  list_price: number | null;
  status: string | null;
  dom: number | null;
  original_price: number | null;
  sqft: number | null;
  beds: number | null;
  baths: string | null;
};

function getStatusStyle(status: string | null): { color: string } {
  switch (status) {
    case 'Model':
      return { color: 'bg-gray-100 text-gray-600' };
    case 'MLS Pending':
      return { color: 'bg-blue-100 text-blue-700' };
    case 'MLS Active':
      return { color: 'bg-amber-50 text-amber-600' };
    case 'Available':
    default:
      return { color: 'bg-green-50 text-green-700' };
  }
}

export default function CommunityJobLots({ shortCode, onCountChange }: CommunityJobLotsProps) {
  const normalizedShortCode = useMemo(() => shortCode.trim().toUpperCase(), [shortCode]);
  const [rows, setRows] = useState<JobLotRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchData = async () => {
    try {
      setLoading(true);
      setError(null);

      const res = await fetch(`/api/communities/${normalizedShortCode}/job-lots`);

      if (res.status === 401) {
        window.location.href = '/';
        return;
      }

      if (!res.ok) {
        setError('Unable to load job/lot data. Please try again.');
        return;
      }

      const data = (await res.json()) as JobLotRow[];
      setRows(data || []);
      onCountChange?.((data || []).length);
    } catch {
      setError('Unable to load job/lot data. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (!normalizedShortCode) return;
    fetchData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [normalizedShortCode]);

  const columns = useMemo<DataGridColumn<JobLotRow>[]>(() => [
    {
      id: 'lot',
      header: 'Lot',
      format: (v) => (v as string) ?? '—',
    },
    {
      id: 'job',
      header: 'Job',
      format: (v) => (v as string) ?? '—',
    },
    {
      id: 'address',
      header: 'Address',
      format: (v) => (v as string) ?? '—',
      defaultSort: 'asc',
    },
    {
      id: 'status',
      header: 'Status',
      render: (row) => {
        const statusStyle = getStatusStyle(row.status);
        return (
          <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${statusStyle.color}`}>
            {row.status ?? '—'}
          </span>
        );
      },

    },
    {
      id: 'lot_premium',
      header: 'Lot Premium',
      format: (v) => formatUsd(v as number | null),
    },
    {
      id: 'garage',
      header: 'Garage',
      format: (v) => (v as string) ?? '—',
    },
    {
      id: 'acres',
      header: 'Acres',
      format: (v) => v != null ? Number(v).toFixed(2) : '—',
    },
  ], []);

  if (loading) {
    return <LoadingState />;
  }

  if (error) {
    return <ErrorState message={error} actionLabel="Try Again" onAction={fetchData} />;
  }

  if (rows.length === 0) {
    return (
      <div className="bg-white border border-gray-200 rounded-lg p-8 text-center">
        <h3 className="text-lg font-bold text-ink mb-2">No job/lot data</h3>
        <p className="text-ink-muted">This community has no lots in the job/lot staging data.</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div>
          <div className="flex items-center gap-2">
            <h3 className="text-lg font-bold text-ink">Job/Lots</h3>
            <span className="relative group/tip">
              <svg className="w-4 h-4 text-ink-muted/50 group-hover/tip:text-ink-muted cursor-help" fill="none" viewBox="0 0 20 20" stroke="currentColor" strokeWidth="2">
                <circle cx="10" cy="10" r="8" />
                <path d="M10 9v4M10 7h.01" strokeLinecap="round" />
              </svg>
              <span className="pointer-events-none absolute left-1/2 -translate-x-1/2 top-full mt-2 z-50 w-60 rounded-md bg-ink px-3 py-2 text-xs font-normal leading-relaxed text-white shadow-lg opacity-0 group-hover/tip:opacity-100 transition-opacity ease-out">
                Available lots excluding sold, backlog, and on-market specs. Enriched with MLS data where a match exists.
              </span>
            </span>
          </div>
          <p className="text-sm text-ink-muted mt-1">{rows.length} available lots</p>
        </div>
      </div>

      <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
        <DataGrid
          data={rows}
          columns={columns}
          searchable
          maxHeight={rows.length <= 100 ? 'none' : '60vh'}
        />
      </div>
    </div>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { formatCount, formatUsdCompact } from '../../lib/overviewUtils';
import {
  getAgingInventoryLevel,
  getAvgAgeLevel,
  getCarryCostLevel,
  getPaceLevel,
  getThresholdClasses,
  type ThresholdLevel,
} from '../../lib/metricThresholds';
import { computeElapsedFraction } from '../../lib/rossPaceMetrics';
import { navigate, redirectToLogin } from '../../lib/navigate';
import DataGrid, { type DataGridColumn } from '../ui/DataGrid';
import { TooltipIcon } from '../ui/Tooltip';
import { SkeletonTable } from '../ui/Skeleton';
import { ErrorCard } from '../ui/ErrorDisplay';
import EmptyState from '../ui/EmptyState';

type CommunityWithMetrics = {
  shortCode: string;
  name: string | null;
  status: string | null;
  lotsRemaining: number;
  totalPlattedLots: number;
  agingInventory: number;
  carryCost: number;
  avgAgeOfInventory: number | null;
  activeSpecs: number;
  paceActual: number | null;
  paceGoal: number | null;
  pacePercentage: number | null;
  backlogCount: number;
  targetGp: number | null;
};

const getStatusColor = (status: string | null) => {
  if (status === 'Active') return 'bg-green-50 text-green-700';
  if (status === 'Planning') return 'bg-amber-50 text-amber-600';
  return 'bg-gray-100 text-gray-500';
};

const formatPace = (community: CommunityWithMetrics) => {
  if (community.paceGoal === null || community.paceGoal === 0) return '—';
  if (community.paceActual === null) return '—';

  const percentage = Math.round(
    community.pacePercentage ?? (community.paceActual / community.paceGoal) * 100
  );

  return `${formatCount(community.paceActual)} of ${formatCount(community.paceGoal)} (${formatCount(percentage)}%)`;
};

const formatTargetGp = (value: number | null | undefined) => {
  if (value === null || value === undefined) return '—';
  const pct = Math.round(value * 100);
  return `${pct}%`;
};

const pillClasses = (level: ThresholdLevel) => {
  const classes = getThresholdClasses(level);
  return `inline-flex items-center rounded-md border px-2 py-1 text-sm font-medium ${classes.bg} ${classes.text} ${classes.border}`;
};

export default function CommunitiesList() {
  const [communities, setCommunities] = useState<CommunityWithMetrics[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchCommunities = async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await fetch('/api/communities/metrics');
      if (response.status === 401) {
        redirectToLogin();
        return;
      }

      if (!response.ok) {
        setError('Unable to load communities. Please try again.');
        return;
      }

      const data = (await response.json()) as CommunityWithMetrics[];
      setCommunities(data || []);
    } catch {
      setError('Unable to load communities. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCommunities();
  }, []);

  const navigateToCommunity = (shortCode: string) => {
    navigate(`/communities/${shortCode}`);
  };

  // Compute elapsed fraction once for YTD (communities list always uses YTD)
  const elapsedFraction = useMemo(() => computeElapsedFraction('YTD', new Date()), []);

  const mobileCommunities = useMemo(() => {
    return [...communities].sort((a, b) => {
      const aVal = a.carryCost ?? 0;
      const bVal = b.carryCost ?? 0;

      if (aVal === bVal) {
        return a.shortCode.localeCompare(b.shortCode);
      }

      return bVal - aVal;
    });
  }, [communities]);

  const columns = useMemo<DataGridColumn<CommunityWithMetrics>[]>(() => [
    {
      id: 'community',
      header: 'Community',
      getValue: (row) => `${row.name ?? row.shortCode ?? ''} ${row.shortCode ?? ''}`.trim(),
      render: (row) => (
        <button
          type="button"
          onClick={() => navigateToCommunity(row.shortCode)}
          className="flex flex-col text-left cursor-pointer hover:underline"
        >
          <span className="text-ink font-medium">
            {row.name?.trim() ? row.name.trim() : row.shortCode ?? '—'}
          </span>
          <span className="text-xs text-ink-muted">{row.shortCode ?? '—'}</span>
        </button>
      ),

    },
    {
      id: 'status',
      header: 'Status',
      render: (row) => (
        <button
          type="button"
          onClick={() => navigateToCommunity(row.shortCode)}
          className="cursor-pointer"
        >
          <span className={`px-3 py-1 rounded-full text-sm font-medium ${getStatusColor(row.status ?? null)}`}>
            {row.status ?? '—'}
          </span>
        </button>
      ),

    },
    {
      id: 'lotsRemaining',
      header: 'Lots Remaining',
      format: (v) => formatCount((v as number) ?? 0),
      render: (row) => (
        <button
          type="button"
          onClick={() => navigateToCommunity(row.shortCode)}
          className="cursor-pointer w-full text-left"
        >
          <span className="block" title={formatCount(row.lotsRemaining ?? 0)}>
            {formatCount(row.lotsRemaining ?? 0)}
          </span>
        </button>
      ),
    },
    {
      id: 'activeSpecs',
      header: 'Active Specs',
      format: (v) => formatCount((v as number) ?? 0),
      render: (row) => (
        <button
          type="button"
          onClick={() => navigateToCommunity(row.shortCode)}
          className="cursor-pointer w-full text-left"
        >
          <span className="block" title={formatCount(row.activeSpecs ?? 0)}>
            {formatCount(row.activeSpecs ?? 0)}
          </span>
        </button>
      ),
    },
    {
      id: 'agingInventory',
      header: 'Aging Inventory',
      render: (row) => {
        const level = getAgingInventoryLevel(row.agingInventory ?? 0);
        return (
          <button
            type="button"
            onClick={() => navigateToCommunity(row.shortCode)}
            className="cursor-pointer"
          >
            <span data-testid="community-metric-aging-inventory" className={pillClasses(level)}>
              {formatCount(row.agingInventory ?? 0)}
            </span>
          </button>
        );
      },
    },
    {
      id: 'carryCost',
      header: 'Carry Cost',
      headerRender: () => (
        <span className="inline-flex items-center gap-1">
          Carry Cost
          <TooltipIcon content="Monthly all-in carry for aging specs (>60 days). Includes 12% loan interest, 2.5% tax/insurance, and $850/mo fixed costs. Green: ≤$12K, Yellow: ≤$35K, Red: >$35K." testId="carry-cost-header-tooltip" />
        </span>
      ),
      render: (row) => {
        const level = getCarryCostLevel(row.carryCost ?? 0);
        return (
          <button
            type="button"
            onClick={() => navigateToCommunity(row.shortCode)}
            className="cursor-pointer"
          >
            <span data-testid="community-metric-carry-cost" className={pillClasses(level)}>
              {formatUsdCompact(row.carryCost ?? 0)}
            </span>
          </button>
        );
      },
      defaultSort: 'desc',
    },
    {
      id: 'avgAgeOfInventory',
      header: 'Avg Age of Inventory',
      render: (row) => {
        const level = getAvgAgeLevel(row.avgAgeOfInventory ?? null);
        return (
          <button
            type="button"
            onClick={() => navigateToCommunity(row.shortCode)}
            className="cursor-pointer"
          >
            <span data-testid="community-metric-avg-age" className={pillClasses(level)}>
              {row.avgAgeOfInventory == null ? '—' : formatCount(Math.max(0, Math.round(row.avgAgeOfInventory)))}
            </span>
          </button>
        );
      },
    },
    {
      id: 'pace_vs_budget',
      header: 'Pace vs Budget',
      getValue: (row) => row.pacePercentage ?? (row.paceGoal ? (row.paceActual ?? 0) / row.paceGoal * 100 : null),
      render: (row) => {
        const paceLevel =
          row.paceGoal === null || row.paceGoal === 0
            ? 'neutral'
            : getPaceLevel(row.pacePercentage, elapsedFraction);

        return (
          <button
            type="button"
            onClick={() => navigateToCommunity(row.shortCode)}
            className="cursor-pointer"
          >
            <span data-testid="community-metric-pace" className={pillClasses(paceLevel)}>
              {formatPace(row)}
            </span>
          </button>
        );
      },

    },
    {
      id: 'targetGp',
      header: 'Target GP',
      format: (v) => formatTargetGp(v as number | null),
      render: (row) => (
        <button
          type="button"
          onClick={() => navigateToCommunity(row.shortCode)}
          className="cursor-pointer w-full text-left"
        >
          <span className="block" title={formatTargetGp(row.targetGp)}>
            {formatTargetGp(row.targetGp)}
          </span>
        </button>
      ),
    },
    {
      id: 'backlogCount',
      header: 'Backlog',
      format: (v) => formatCount((v as number) ?? 0),
      render: (row) => (
        <button
          type="button"
          onClick={() => navigateToCommunity(row.shortCode)}
          className="cursor-pointer w-full text-left"
        >
          <span className="block" title={formatCount(row.backlogCount ?? 0)}>
            {formatCount(row.backlogCount ?? 0)}
          </span>
        </button>
      ),
    },
  ], [elapsedFraction]);

  return (
    <div className="max-w-7xl mx-auto space-y-6">
      {/* Header Section */}
      <div className="bg-white rounded-lg shadow-sm p-6">
        <div className="flex items-center justify-between">
          <h1 className="text-3xl font-bold text-ink">Communities</h1>
        </div>
        <p className="text-ink-muted mt-2">Portfolio metrics across all communities</p>
      </div>

      {/* Loading State */}
      {loading && (
        <>
          {/* Desktop skeleton */}
          <div className="hidden md:block">
            <SkeletonTable rows={5} columns={10} />
          </div>
          {/* Mobile skeleton */}
          <div className="md:hidden space-y-4">
            {[1, 2, 3].map((i) => (
              <div key={i} className="bg-white rounded-lg shadow-sm p-4 animate-pulse">
                <div className="h-5 bg-gray-200 rounded w-1/2 mb-2"></div>
                <div className="h-4 bg-gray-200 rounded w-1/4 mb-4"></div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="h-4 bg-gray-200 rounded"></div>
                  <div className="h-4 bg-gray-200 rounded"></div>
                </div>
              </div>
            ))}
          </div>
        </>
      )}

      {/* Error State */}
      {error && !loading && (
        <ErrorCard error={error} onRetry={fetchCommunities} />
      )}

      {/* Empty State */}
      {!loading && !error && communities.length === 0 && (
        <div className="bg-white rounded-lg shadow-sm p-12">
          <EmptyState
            icon={
              <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
              </svg>
            }
            message="No community data"
            description="Upload your data files to populate community metrics."
            action={{ label: 'Upload Data', href: '/admin/data-upload' }}
            component="CommunitiesList"
          />
        </div>
      )}

      {/* Mobile Card View */}
      {!loading && !error && communities.length > 0 && (
        <div className="md:hidden space-y-4">
          {mobileCommunities.map((community) => {
            const agingLevel = getAgingInventoryLevel(community.agingInventory);
            const carryCostLevel = getCarryCostLevel(community.carryCost);
            const avgAgeLevel = getAvgAgeLevel(community.avgAgeOfInventory);
            const paceLevel =
              community.paceGoal === null || community.paceGoal === 0
                ? 'neutral'
                : getPaceLevel(community.pacePercentage, elapsedFraction);

            return (
            <button
              key={community.shortCode}
              onClick={() => navigateToCommunity(community.shortCode)}
              className="w-full bg-white rounded-lg shadow-sm p-4 text-left card-hover border border-transparent hover:border-brand"
            >
              <div className="flex items-start justify-between mb-3">
                <div>
                  <h3 className="font-semibold text-ink">
                    {community.name?.trim() || community.shortCode}
                  </h3>
                  <p className="text-xs text-ink-muted">{community.shortCode}</p>
                </div>
                <span className={`px-2 py-1 rounded-full text-xs font-medium ${getStatusColor(community.status)}`}>
                  {community.status || '—'}
                </span>
              </div>
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div>
                  <p className="text-ink-muted">Lots Remaining</p>
                  <p className="font-medium text-ink">{formatCount(community.lotsRemaining)}</p>
                </div>
                <div>
                  <p className="text-ink-muted">Active Specs</p>
                  <p className="font-medium text-ink">{formatCount(community.activeSpecs)}</p>
                </div>
                <div>
                  <p className="text-ink-muted">Aging Inventory</p>
                  <p>
                    <span
                      data-testid="community-metric-aging-inventory"
                      className={pillClasses(agingLevel)}
                    >
                      {formatCount(community.agingInventory)}
                    </span>
                  </p>
                </div>
                <div>
                  <p className="text-ink-muted">Carry Cost</p>
                  <p>
                    <span
                      data-testid="community-metric-carry-cost"
                      className={pillClasses(carryCostLevel)}
                    >
                      {formatUsdCompact(community.carryCost)}
                    </span>
                  </p>
                </div>
                <div>
                  <p className="text-ink-muted">Avg Age of Inventory</p>
                  <p>
                    <span
                      data-testid="community-metric-avg-age"
                      className={pillClasses(avgAgeLevel)}
                    >
                      {community.avgAgeOfInventory === null
                        ? '—'
                        : formatCount(Math.max(0, Math.round(community.avgAgeOfInventory)))}
                    </span>
                  </p>
                </div>
                <div>
                  <p className="text-ink-muted">Pace vs Budget</p>
                  <p>
                    <span data-testid="community-metric-pace" className={pillClasses(paceLevel)}>
                      {formatPace(community)}
                    </span>
                  </p>
                </div>
                <div>
                  <p className="text-ink-muted">Target GP</p>
                  <p className="font-medium text-ink">{formatTargetGp(community.targetGp)}</p>
                </div>
                <div>
                  <p className="text-ink-muted">Backlog</p>
                  <p className="font-medium text-ink">{formatCount(community.backlogCount)}</p>
                </div>
              </div>
            </button>
            );
          })}
        </div>
      )}

      {/* Desktop Table View */}
      {!loading && !error && communities.length > 0 && (
        <div className="hidden md:block bg-white rounded-lg shadow-sm overflow-hidden">
          <DataGrid
            data={communities}
            columns={columns}
            searchable
            maxHeight="60vh"
          />
        </div>
      )}
    </div>
  );
}

