import { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import type { PropertyWithCommunity } from '../../types/property';
import LoadingState from '../ui/LoadingState';

const PROPERTY_STATUS_STYLES: Record<string, string> = {
  Available: 'bg-green-50 text-green-700',
  'Under Construction': 'bg-blue-50 text-blue-700',
  Sold: 'bg-gray-100 text-gray-600',
  'Inventory/Spec': 'bg-amber-50 text-amber-600',
};

const statusPillClass = (status: string | null) =>
  (status && PROPERTY_STATUS_STYLES[status]) || 'bg-gray-100 text-gray-500';

const displayAddress = (property: PropertyWithCommunity) =>
  property.street_address ||
  [property.city, property.state].filter(Boolean).join(', ') ||
  property.city ||
  '—';

type PropertyRowProps = {
  property: PropertyWithCommunity;
  onRowClick: (id: string) => void;
};

const PropertyRow = ({ property, onRowClick }: PropertyRowProps) => (
  <tr
    key={property.id}
    onClick={() => onRowClick(property.id)}
    className="border-t border-gray-200 hover:bg-surface cursor-pointer transition-colors ease-out"
  >
    <td className="px-6 py-4 text-ink font-medium">{property.job_id}</td>
    <td className="px-6 py-4 text-ink-muted truncate max-w-xs">
      {displayAddress(property)}
    </td>
    <td className="px-6 py-4 text-ink-muted">
      {property.model_name || '—'}
    </td>
    <td className="px-6 py-4">
      {property.status ? (
        <span className={`px-3 py-1 rounded-full text-sm font-medium ${statusPillClass(property.status)}`}>
          {property.status}
        </span>
      ) : (
        <span className="text-ink-muted">—</span>
      )}
    </td>
    <td className="px-6 py-4">
      {property.community_name ? (
        <span className="text-ink">{property.community_name}</span>
      ) : (
        <span className="px-3 py-1 bg-gray-100 text-gray-500 rounded-full text-sm font-medium">
          Unlinked
        </span>
      )}
    </td>
  </tr>
);

