          onChange={(id) => setFilter(id as typeof filter)}
          size="md"
        />
      </div>

      {/* Lots Table */}
      <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
        <DataGrid
          data={filteredLots}
          columns={columns}
          maxHeight="none"
        />
      </div>
    </div>
  );
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { Settings2 } from 'lucide-react';
import { dispatchBreadcrumbContext } from '../../lib/breadcrumbUtils';
import { initPostHog, trackError, trackEvent } from '../../lib/posthog';
import EmptyState from '../ui/EmptyState';
import LoadingState from '../ui/LoadingState';
import TabBar from '../ui/TabBar';
import HeroMetricsStrip, { type HeroMetricsData, type HeroMetricId } from './HeroMetricsStrip';
import CommunityOverview from './CommunityOverview';
import CommunityProperties from './CommunityProperties';
import CommunityBacklog from './CommunityBacklog';
import CommunityMarket from './CommunityMarket';
import CommunityJobLots from './CommunityJobLots';
import CommunitySettingsDrawer from './CommunitySettingsDrawer';

type RossCommunityMetrics = {
  shortCode: string;
  name: string | null;
  status: string | null;
  lotsRemaining: number;
  totalPlattedLots: number;
  agingInventory: number;
  carryCost: number;
  avgAgeOfInventory: number | null;
  activeSpecs: number;
  paceActual: number | null;
  paceGoal: number | null;
  pacePercentage: number | null;
  backlogCount: number;
  hasData?: boolean;
};

type RossCommunityDashboardProps = {
  shortCode: string;
};

type TabType = 'overview' | 'properties' | 'backlog' | 'market' | 'job-lots';

const VALID_TABS: Set<string> = new Set<string>([
  'overview', 'properties', 'backlog', 'market', 'job-lots',
]);

type RossTab = {
  id: TabType;
  label: string;
  tooltip: string;
};

type RossMetricsLoadResult =
  | { kind: 'unauthorized' }
  | { kind: 'not_found' }
  | { kind: 'error'; status?: number }
  | { kind: 'ok'; metrics: RossCommunityMetrics };

const getStatusColorClass = (status: string | null): string => {
  switch (status) {
    case 'Active':
      return 'bg-green-50 text-green-700';
    case 'Planning':
      return 'bg-amber-50 text-amber-600';
    default:
      return 'bg-gray-100 text-gray-500';
  }
};


type RossTabsProps = {
  tabs: RossTab[];
  activeTab: TabType;
  onTabChange: (tab: TabType) => void;
  children: React.ReactNode;
};

function RossTabs({ tabs, activeTab, onTabChange, children }: RossTabsProps) {
  return (
    <div className="bg-white rounded-lg shadow-sm">
      <div className="px-4 sm:px-6 pt-3">
        <TabBar
          tabs={tabs}
          activeTab={activeTab}
          onChange={(id) => onTabChange(id as TabType)}
          size="md"
        />
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

async function loadRossMetrics(shortCode: string): Promise<RossMetricsLoadResult> {
  try {
    const response = await fetch(`/api/communities/${shortCode}/metrics?pacePeriod=YTD`);

    if (response.status === 401) return { kind: 'unauthorized' };
    if (response.status === 404) return { kind: 'not_found' };
    if (!response.ok) return { kind: 'error', status: response.status };

    const data = (await response.json()) as RossCommunityMetrics;
    if (data.hasData === false) return { kind: 'not_found' };
    return { kind: 'ok', metrics: data };
  } catch {
    return { kind: 'error' };
  }
}

function buildRossTabs(
  metrics: RossCommunityMetrics | null,
  propertiesCount: number | null,
  jobLotsCount: number | null,
  backlogCount: number,
): RossTab[] {
  return [
    { id: 'overview', label: 'Overview', tooltip: 'Summary metrics for this community' },
    { id: 'properties', label: `Properties${propertiesCount === null ? '' : ` (${propertiesCount})`}`, tooltip: 'Active unsold spec homes with list price, completion date, days in inventory, and price position vs. similar sold homes.' },
    { id: 'job-lots', label: `Job/Lots${jobLotsCount === null ? '' : ` (${jobLotsCount})`}`, tooltip: "Available lots excluding sold, backlog, and on-market specs. Enriched with MLS data where a match exists." },
    { id: 'backlog', label: `Backlog${metrics === null ? '' : ` (${backlogCount})`}`, tooltip: 'Homes currently under contract showing buyer, sales agent, price, sale date, expected close, and contingency status.' },
    { id: 'market', label: 'Market', tooltip: "MLS listings in the community's competitive area filtered by structure type and size. Shows price, DOM, sqft, $/SF, and sale dates." },
  ];
}

type RossContentProps = {
  activeTab: TabType;
  metrics: RossCommunityMetrics;
  onPropertiesCountChange: (count: number | null) => void;
  onBacklogCountChange: (count: number | null) => void;
  onJobLotsCountChange: (count: number | null) => void;
  onCarryCostComputed: (cost: number) => void;
};

function RossContent({
  activeTab,
  metrics,
  onPropertiesCountChange,
  onBacklogCountChange,
  onJobLotsCountChange,
  onCarryCostComputed,
}: RossContentProps) {
  return (
    <>
      <div className={activeTab === 'overview' ? 'block' : 'hidden'}>
        <CommunityOverview
          shortCode={metrics.shortCode}
          onCarryCostComputed={onCarryCostComputed}
        />
      </div>

      <div className={activeTab === 'properties' ? 'block' : 'hidden'}>
        <CommunityProperties
          shortCode={metrics.shortCode}
          onCountChange={onPropertiesCountChange}
        />
      </div>

      {activeTab === 'backlog' && (
        <CommunityBacklog shortCode={metrics.shortCode} onCountChange={onBacklogCountChange} />
      )}
      {activeTab === 'market' && <CommunityMarket shortCode={metrics.shortCode} />}
      <div className={activeTab === 'job-lots' ? 'block' : 'hidden'}>
        <CommunityJobLots shortCode={metrics.shortCode} onCountChange={onJobLotsCountChange} />
      </div>
    </>
  );
}

function RossErrorState({ error }: { error: string }) {
  if (error === 'Community not found') {
    return (
      <div className="max-w-screen-2xl mx-auto space-y-6">
        <div className="bg-white rounded-lg shadow-sm p-12">
          <EmptyState
            message="No community data available"
            description="This community has no data yet. Upload documents to view metrics."
            action={{ label: 'Upload Documents', href: '/admin/data-upload' }}
            component="RossCommunityDashboard"
          />
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-screen-2xl mx-auto space-y-6">
      <div className="bg-white rounded-lg shadow-sm p-12 text-center">
        <h2 className="text-2xl font-bold text-ink mb-2">Unable to load community</h2>
        <p className="text-ink-muted">{error}</p>
      </div>
    </div>
  );
}

export default function RossCommunityDashboard({ shortCode }: RossCommunityDashboardProps) {
  const normalizedShortCode = useMemo(() => shortCode.trim().toUpperCase(), [shortCode]);
  const [metrics, setMetrics] = useState<RossCommunityMetrics | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<TabType>('overview');
  const [propertiesCount, setPropertiesCount] = useState<number | null>(null);
  const [backlogCount, setBacklogCount] = useState<number | null>(null);
  const [jobLotsCount, setJobLotsCount] = useState<number | null>(null);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [overviewCarryCost, setOverviewCarryCost] = useState<number | null>(null);

  useEffect(() => {
    setPropertiesCount(null);
    setBacklogCount(null);
    setJobLotsCount(null);
  }, [normalizedShortCode]);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const tab = params.get('tab');
    if (tab && VALID_TABS.has(tab)) {
      setActiveTab(tab as TabType);
    }
  }, []);

  useEffect(() => {
    let isCancelled = false;
    const fetchRossMetrics = async () => {
      setLoading(true);
      setError(null);
      const result = await loadRossMetrics(normalizedShortCode);
      if (isCancelled) return;

      if (result.kind === 'unauthorized') {
        window.location.href = '/';
        return;
      }

      if (result.kind === 'not_found') {
        setError('Community not found');
        setMetrics(null);
        setLoading(false);
        return;
      }

      if (result.kind === 'error') {
        setError('Unable to load community metrics. Please try again.');
        trackError('community_metrics_load_failed', 'Failed to load community metrics', {
          short_code: normalizedShortCode,
          status: result.status,
        });
        setLoading(false);
        return;
      }

      setMetrics(result.metrics);
      setLoading(false);
      const name = result.metrics.name?.trim() || normalizedShortCode;
      dispatchBreadcrumbContext({ communityName: name });
    };

    if (normalizedShortCode) {
      void fetchRossMetrics();
    }

    return () => {
      isCancelled = true;
    };
  }, [normalizedShortCode]);

  useEffect(() => {
    if (!normalizedShortCode) return;
    initPostHog();
    trackEvent('community_detail_viewed', { short_code: normalizedShortCode });
  }, [normalizedShortCode]);

  useEffect(() => {
    if (!normalizedShortCode) return;
    if (activeTab !== 'backlog') return;
    initPostHog();
    trackEvent('community_backlog_viewed', { short_code: normalizedShortCode });
  }, [activeTab, normalizedShortCode]);

  const handleHeroCardClick = useCallback((metricId: HeroMetricId) => {
    const tabMap: Record<HeroMetricId, TabType> = {
      activeSpecs: 'properties',
      backlog: 'backlog',
      lotsRemaining: 'job-lots',
    };
    const targetTab = tabMap[metricId];
    if (targetTab) {
      setActiveTab(targetTab);
      trackEvent('community_hero_metric_clicked', {
        metric: metricId,
        target_tab: targetTab,
        short_code: normalizedShortCode,
      });
    }
  }, [normalizedShortCode]);

  const displayActiveSpecs = propertiesCount ?? metrics?.activeSpecs ?? 0;
  const displayBacklogCount = backlogCount ?? metrics?.backlogCount ?? 0;

  const rossTabs = useMemo(
    () => buildRossTabs(metrics, propertiesCount, jobLotsCount, displayBacklogCount),
    [metrics, propertiesCount, jobLotsCount, displayBacklogCount],
  );

  if (loading && !metrics) {
    return (
      <div className="max-w-screen-2xl mx-auto space-y-6">
        <div className="bg-white rounded-lg shadow-sm p-12">
          <LoadingState />
        </div>
      </div>
    );
  }

  if (error || !metrics) {
    return <RossErrorState error={error ?? 'Unable to load community metrics. Please try again.'} />;
  }

  const title = metrics.name?.trim() ? metrics.name.trim() : normalizedShortCode;
  const rossStatusColor = getStatusColorClass(metrics.status);

  const heroData: HeroMetricsData = {
    lotsRemaining: metrics.lotsRemaining,
    totalPlattedLots: metrics.totalPlattedLots,
    activeSpecs: displayActiveSpecs,
    agingInventory: metrics.agingInventory,
    avgAgeOfInventory: metrics.avgAgeOfInventory,
    carryCost: overviewCarryCost ?? metrics.carryCost,
    backlogCount: displayBacklogCount,
  };

  return (
    <div className="max-w-screen-2xl mx-auto space-y-4">
      {/* Community header + hero metrics */}
      <div className="bg-white rounded-lg shadow-sm p-4">
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-3 min-w-0">
            <h1 className="text-xl sm:text-2xl font-bold text-ink truncate">{title}</h1>
            <span className="text-ink-muted text-sm hidden sm:inline">{normalizedShortCode}</span>
            {metrics.status && (
              <span className={`shrink-0 inline-block px-2 py-0.5 rounded-full text-xs font-medium ${rossStatusColor}`}>
                {metrics.status}
              </span>
            )}
          </div>
          <button
            data-testid="community-settings-button"
            onClick={() => setSettingsOpen(true)}
            className="shrink-0 text-ink-muted hover:text-ink transition-colors ease-out p-2 rounded-lg hover:bg-gray-100"
            aria-label="Community settings"
          >
            <Settings2 className="w-5 h-5" />
          </button>
        </div>
        <HeroMetricsStrip
          data={heroData}
          loading={loading}
          onCardClick={handleHeroCardClick}
        />
      </div>

      <CommunitySettingsDrawer open={settingsOpen} onOpenChange={setSettingsOpen} />

      <RossTabs
        tabs={rossTabs}
        activeTab={activeTab}
        onTabChange={setActiveTab}
      >
        <RossContent
          activeTab={activeTab}
          metrics={metrics}
          onPropertiesCountChange={setPropertiesCount}
          onBacklogCountChange={setBacklogCount}
          onJobLotsCountChange={setJobLotsCount}
          onCarryCostComputed={setOverviewCarryCost}
        />
      </RossTabs>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import ErrorState from '../ui/ErrorState';
import LoadingState from '../ui/LoadingState';
import type { Property, PropertyStatus } from '../../types/property';

type CommunityPropertiesListProps = {
  communityId: string;
  communityName: string;
};

export default function CommunityPropertiesList({ communityId, communityName }: CommunityPropertiesListProps) {
  const [properties, setProperties] = useState<Property[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchProperties() {
      try {
        setLoading(true);
        const { data: { user }, error: userError } = await supabase.auth.getUser();

        if (userError || !user) {
          setError('Authentication error');
          return;
        }

        const { data, error: fetchError } = await supabase
          .from('properties')
          .select('*')
          .eq('community_id', communityId)
          .eq('user_id', user.id)
          .order('created_at', { ascending: false });

        if (fetchError) {
          setError('Unable to load properties');
          console.error('Error fetching properties:', fetchError);
          return;
        }

        setProperties(data || []);
      } catch (err) {
        setError('Unable to load properties');
        console.error('Unexpected error:', err);
      } finally {
        setLoading(false);
      }
    }

    fetchProperties();
  }, [communityId]);

  const getStatusColor = (status: PropertyStatus | null) => {
    switch (status) {
      case 'Available':
        return 'bg-green-50 text-green-700';
      case 'Under Construction':
        return 'bg-blue-50 text-blue-700';
      case 'Sold':
        return 'bg-gray-100 text-gray-600';
      case 'Inventory/Spec':
        return 'bg-amber-50 text-amber-600';
      default:
        return 'bg-gray-100 text-gray-500';
    }
  };

  const handleAddProperty = () => {
    // Navigate to add property page with community_id pre-filled in URL
    window.location.href = `/properties/add?community_id=${communityId}`;
  };

  const handlePropertyClick = (propertyId: string) => {
    window.location.href = `/properties/${propertyId}`;
  };

  // Loading state
  if (loading) {
    return (
      <div className="bg-white rounded-lg shadow-sm p-6">
        <h3 className="text-lg font-bold text-ink mb-4">Properties</h3>
        <LoadingState className="h-48" />
      </div>
    );
  }

  // Error state
  if (error) {
    return (
      <div className="bg-white rounded-lg shadow-sm p-6">
        <h3 className="text-lg font-bold text-ink mb-4">Properties</h3>
        <ErrorState message={error} className="h-48 bg-surface rounded-lg" />
      </div>
    );
  }

  // Empty state
  if (properties.length === 0) {
    return (
      <div className="bg-white rounded-lg shadow-sm p-6">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-bold text-ink">Properties</h3>
          <button
            onClick={handleAddProperty}
            className="bg-brand hover:bg-brand-hover text-white font-semibold px-4 py-2 rounded-lg transition-colors ease-out text-sm"
          >
            + Add Property
          </button>
        </div>
        <div className="flex flex-col items-center justify-center h-48 bg-surface rounded-lg">
          <p className="text-ink-muted mb-4">No properties in this community yet</p>
          <button
            onClick={handleAddProperty}
            className="text-brand hover:text-brand-hover font-medium transition-colors ease-out"
          >
            Add your first property →
          </button>
        </div>
      </div>
    );
  }

  // Calculate status summary
  const statusCounts = properties.reduce((acc, prop) => {
    const status = prop.status || 'Unknown';
    acc[status] = (acc[status] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  // Main content with properties
  return (
    <div className="bg-white rounded-lg shadow-sm p-6">
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <div>
          <h3 className="text-lg font-bold text-ink">Properties</h3>
          <p className="text-sm text-ink-muted mt-1">
            {properties.length} {properties.length === 1 ? 'property' : 'properties'} in {communityName}
          </p>
        </div>
        <button
          onClick={handleAddProperty}
          className="bg-brand hover:bg-brand-hover text-white font-semibold px-4 py-2 rounded-lg transition-colors ease-out text-sm"
        >
          + Add Property
        </button>
      </div>

      {/* Status Summary */}
      <div className="flex flex-wrap gap-2 mb-4 pb-4 border-b border-gray-200">
        {Object.entries(statusCounts).map(([status, count]) => (
          <span
            key={status}
            className={`inline-block px-3 py-1 rounded-full text-xs font-medium ${getStatusColor(status as PropertyStatus)}`}
          >
            {status}: {count}
          </span>
        ))}
      </div>

      {/* Properties List */}
      <div className="space-y-2 max-h-96 overflow-y-auto">
        {properties.map((property) => (
          <div
            key={property.id}
            onClick={() => handlePropertyClick(property.id)}
            className="p-4 bg-surface hover:bg-gray-100 rounded-lg cursor-pointer transition-colors ease-out group"
          >
            <div className="flex items-center justify-between">
              <div className="flex-1">
                <div className="flex items-center gap-3 mb-2">
                  <h4 className="font-semibold text-ink group-hover:text-brand transition-colors ease-out">
                    Job ID: {property.job_id}
                  </h4>
                  {property.status && (
                    <span className={`inline-block px-2 py-1 rounded-full text-xs font-medium ${getStatusColor(property.status)}`}>
                      {property.status}
                    </span>
                  )}
                </div>
                <div className="flex items-center gap-4 text-sm text-ink-muted">
                  {property.model_name && (
                    <span>Model: {property.model_name}</span>
                  )}
                  {property.bedrooms && property.bathrooms_full && (
                    <span>{property.bedrooms}bd / {property.bathrooms_full}ba</span>
                  )}
                  {property.square_feet && (
                    <span>{property.square_feet.toLocaleString()} sqft</span>
                  )}
                  {property.base_price && (
                    <span className="font-medium text-ink">
                      ${property.base_price.toLocaleString()}
                    </span>
                  )}
                </div>
              </div>
              <svg
                className="w-5 h-5 text-ink-muted group-hover:text-brand transition-colors ease-out"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
              </svg>
            </div>
          </div>
        ))}
      </div>

      {/* View All Link */}
      {properties.length > 5 && (
        <div className="mt-4 pt-4 border-t border-gray-200 text-center">
          <a
            href={`/properties?community_id=${communityId}`}
            className="text-brand hover:text-brand-hover font-medium transition-colors ease-out text-sm"
          >
            View all properties in {communityName} →
          </a>
        </div>
      )}
    </div>
  );
}

