  );
};

type PropertyOptionsSectionProps = {
  options: PropertyOption[];
  editHref: string;
};

const PropertyOptionsSection = ({ options, editHref }: PropertyOptionsSectionProps) => {
  const optionsTotal = options.reduce((sum, option) => sum + (option.price || 0), 0);

