      {/* Loading State */}
      {loading && (
        <div className="bg-white rounded-lg shadow-sm p-12">
          <LoadingState />
        </div>
      )}

      {/* Error State */}
      {error && !loading && (
        <div className="bg-red-50 text-red-600 p-4 rounded-lg">
          {error}
        </div>
