                  property={property}
                  onRowClick={handleRowClick}
                />
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

import { getCompositeLabel } from '../../lib/communityHealthScoring';
import { formatUsdCompact } from '../../lib/formatUtils';
import { TooltipIcon } from '../ui/Tooltip';
import RadialRing from '../ui/RadialRing';
import BulletBar from '../ui/BulletBar';

// ── Shared props interface ──────────────────────────────────────────────────
// Both the overview (CommunityAlertCard) and community detail (CommunityHealthScore)
// build this data and pass it in. One rendering, one source of truth.

export type HealthWidgetData = {
  compositeScore: number | null;
  velocityScore: number | null;
  paceScore: number | null;
  carryScore: number | null;
  velocityDetail: string;
  paceDetail: string;
  carryDetail: string;
  // Raw metrics for display values and target lines
  medianDom: number | null;
  velocityBandDtp: number | null;
  paceDelta: number | null;
  monthlyCarryCost: number;
};

const HEALTHY_THRESHOLD = 65;
const WATCH_THRESHOLD = 40;

function getBadgeClasses(score: number | null): string {
  if (score == null) return 'bg-gray-100 text-gray-500';
  if (score >= HEALTHY_THRESHOLD) return 'bg-green-50 text-green-700';
  if (score >= WATCH_THRESHOLD) return 'bg-amber-50 text-amber-600';
  return 'bg-red-50 text-red-700';
}

function formatDom(days: number | null): string {
  if (days == null) return '—';
  return `${Math.round(days)}d`;
}

function formatPaceDelta(delta: number | null): string {
  if (delta == null) return '—';
  if (Math.abs(delta) < 0.05) return 'on pace';
  const abs = Math.abs(delta);
  const num = abs % 1 === 0 ? String(abs) : abs.toFixed(1);
  return delta > 0 ? `${num} ahead` : `${num} behind`;
}

export default function CommunityHealthWidget({ data }: { data: HealthWidgetData }) {
  const badgeClasses = getBadgeClasses(data.compositeScore);
  const badgeLabel = getCompositeLabel(data.compositeScore);

  return (
    <div>
      {/* Header */}
      <div className="flex items-center justify-between mb-1">
        <div className="text-sm font-semibold text-ink inline-flex items-center gap-1">
          Community Health
          <TooltipIcon
            content="Overall community health on a 0–100 scale, combining velocity band, pace vs budget, and carry cost factors. Higher is healthier. 65–100: Healthy, 40–64: Watch, 0–39: Urgent."
            testId="community-health-tooltip"
          />
        </div>
        <div
          data-testid="alert-badge"
          className={`text-xs px-2 py-0.5 rounded font-semibold ${badgeClasses}`}
        >
          {badgeLabel}
        </div>
      </div>
      <div className="text-xs text-ink-muted mb-4">Based on velocity, pace, and carry cost</div>

      {/* Radial ring + Bullet bars */}
      <div className="flex items-start gap-5">
        <div data-testid="health-gauge">
          <RadialRing score={data.compositeScore} />
        </div>
        <div className="flex-1 space-y-4 pt-1">
          <BulletBar
            label="Velocity Band"
            score={data.velocityScore}
            detail={data.velocityDetail}
            tooltip="Your median days on market vs. the local market benchmark."
            displayValue={formatDom(data.medianDom)}
          />
          <BulletBar
            label="Pace vs Budget"
            score={data.paceScore}
            detail={data.paceDetail}
            tooltip="Sales progress vs. annual budget goal, time-adjusted."
            displayValue={formatPaceDelta(data.paceDelta)}
          />
          <BulletBar
            label="Carry Cost"
            score={data.carryScore}
            detail={data.carryDetail}
            tooltip="Monthly carrying cost for aging inventory (>60 days). Green: ≤$12K/mo. Yellow: ≤$35K/mo. Red: >$35K/mo."
            displayValue={data.monthlyCarryCost > 0 ? `${formatUsdCompact(data.monthlyCarryCost)}/mo` : '$0'}
          />
        </div>
      </div>
    </div>
  );
}

import { useState, useMemo } from 'react';
import type { DrawerProperty, MetricDrawerConfig } from '../../lib/drawerTypes';
import { carryCostMonthly } from '../../lib/carryCost';
import { formatUsdCompact } from '../../lib/formatUtils';
import { trackEvent } from '../../lib/posthog';

type MetricDrawerContentProps = {
  config: MetricDrawerConfig;
  properties: DrawerProperty[];
  isLoading: boolean;
  error: string | null;
  onRetry: () => void;
  isPortfolioLevel?: boolean;
  'data-testid'?: string;
};

function getStatusBadge(row: DrawerProperty): { label: string; classes: string } {
  if (row.scheduledCloseDate) {
    return { label: 'Under Contract', classes: 'bg-blue-100 text-status-info' };
  }
  if (row.daysInInventory != null && row.daysInInventory > 60) {
    return { label: 'At Risk', classes: 'bg-amber-50 text-amber-600' };
  }
  return { label: 'Active', classes: 'bg-green-50 text-green-700' };
}

function sortProperties(
  rows: DrawerProperty[],
  config: MetricDrawerConfig,
): DrawerProperty[] {
  const { getValue, direction } = config.defaultSort;
  return [...rows].sort((a, b) => {
    const aVal = getValue(a);
    const bVal = getValue(b);
    if (aVal == null && bVal == null) return 0;
    if (aVal == null) return 1;
    if (bVal == null) return -1;
    const cmp = typeof aVal === 'string' && typeof bVal === 'string'
      ? aVal.localeCompare(bVal)
      : Number(aVal) - Number(bVal);
    return direction === 'desc' ? -cmp : cmp;
  });
}

export default function MetricDrawerContent({
  config,
  properties,
  isLoading,
  error,
  onRetry,
  isPortfolioLevel = false,
  'data-testid': testId,
}: MetricDrawerContentProps) {
  const [search, setSearch] = useState('');

  const sorted = useMemo(() => sortProperties(properties, config), [properties, config]);

  const filtered = useMemo(() => {
    if (!search.trim()) return sorted;
    const q = search.trim().toLowerCase();
    return sorted.filter(
      (row) =>
        row.address.toLowerCase().includes(q) ||
        (row.planName && row.planName.toLowerCase().includes(q)) ||
        (isPortfolioLevel && row.communityName.toLowerCase().includes(q)),
    );
  }, [sorted, search, isPortfolioLevel]);

  if (isLoading) {
    return (
      <div data-testid={testId} className="space-y-3">
        {Array.from({ length: 6 }).map((_, i) => (
          <div key={i} className="h-12 bg-gray-100 rounded animate-pulse" data-testid="skeleton-row" />
        ))}
      </div>
    );
  }

  if (error) {
    return (
      <div data-testid={testId} className="text-center py-8">
        <p className="text-ink-muted mb-3">{error}</p>
        <button
          type="button"
          onClick={onRetry}
          className="text-brand hover:text-brand-hover font-medium transition-colors ease-out"
        >
          Try again
        </button>
      </div>
    );
  }

  if (properties.length === 0) {
    return (
      <div data-testid={testId} className="text-center py-8">
        <p className="text-ink-muted">No properties match this filter</p>
      </div>
    );
  }

  return (
    <div data-testid={testId} className="space-y-4">
      {/* Summary strip */}
      <div data-testid="summary-strip" className="flex gap-4 pb-3 border-b border-gray-200">
        {config.summaryFields.map((field) => (
          <div key={field.label} className="flex-1">
            <p className="text-xs text-ink-muted">{field.label}</p>
            <p className="text-sm font-semibold text-ink">{field.compute(properties)}</p>
          </div>
        ))}
      </div>

      {/* Search */}
      {properties.length > 10 && (
        <input
          type="search"
          placeholder="Search properties..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="w-full px-3 py-2 border border-gray-200 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-brand/20 focus:border-brand"
          data-testid="drawer-search"
        />
      )}

      {/* Property list */}
      <div className="space-y-1">
        {filtered.map((row) => {
          const badge = getStatusBadge(row);
          const colValue = config.relevantColumn.getValue(row);
          const colDisplay = config.relevantColumn.format
            ? config.relevantColumn.format(colValue)
            : String(colValue ?? '—');

          return (
            <a
              key={row.propertyId}
              href={`/communities/${row.communityShortCode}/what-if/${row.jobId}`}
              target="_blank"
              rel="noopener noreferrer"
              className="flex items-center gap-3 px-3 py-2.5 rounded-md hover:bg-gray-50 transition-colors ease-out group"
              onClick={() => trackEvent('metric_drawer_row_clicked', { metric: config.key, propertyId: row.propertyId })}
              data-testid="property-row"
            >
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-ink truncate group-hover:text-brand transition-colors ease-out">
                  {row.address}
                </p>
                <p className="text-xs text-ink-muted truncate">
                  {row.planName ?? '—'}
                  {isPortfolioLevel && ` · ${row.communityName}`}
                  {row.listPrice != null && ` · ${formatUsdCompact(row.listPrice)}`}
                </p>
              </div>

              <div className="text-right shrink-0">
                <p className="text-sm text-ink">{colDisplay}</p>
              </div>

              <span className={`shrink-0 rounded-full px-2 py-0.5 text-xs font-medium ${badge.classes}`}>
                {badge.label}
              </span>
            </a>
          );
        })}
      </div>
    </div>
  );
}

import { Fragment, useEffect, useMemo, useState } from 'react';
import { formatUsd, formatPricePerSqft, formatNumber, formatBedsBaths } from '../../lib/formatUtils';
import { trackEvent } from '../../lib/posthog';
import type { DiagnosticComp } from '../../lib/diagnosticTypes';
import { matchBadgeClasses, matchLabel } from '../../lib/compBadgeHelpers';
import TabBar from '../ui/TabBar';
import Tooltip, { TooltipIcon } from '../ui/Tooltip';
import EmptyState from '../ui/EmptyState';
import MethodologyLink from './MethodologyLink';

const COL_COUNT = 10; // expand + match + address + price + sqft + $/SF + DOM + beds/baths + subdivision + ranch

type CompetitiveLadderProps = {
  valuationComps: DiagnosticComp[];
  competitiveComps: DiagnosticComp[];
  subjectPrice: number;
  subjectPpsf: number;
  subjectSqft: number;
  subjectDom: number;
  /** 'mls_dom' when MLS match exists, 'inventory_age' otherwise */
  domSource?: 'mls_dom' | 'inventory_age';
  subjectBeds: number | null;
  subjectBathsFull: number | null;
  subjectBathsHalf: number | null;
  subjectSubdivision: string | null;
  subjectIsRanch: boolean | null;
  specId: string;
  shortCode: string;
  initialPool?: 'valuation' | 'competitive';
  scrollNonce?: number;
  iqrExcludedMlsNumbers?: Set<string>;
  iqrBounds?: { lowerBound: number; upperBound: number } | null;
};

type SortKey = 'similarity' | 'price' | 'ppsf' | 'dom' | 'sqft' | 'bedsBaths';
type SortDir = 'asc' | 'desc';

const matchPct = (score: number) => Math.max(0, (1 - score)) * 100;

function filterComps(comps: DiagnosticComp[], subjectPrice: number): DiagnosticComp[] {
  const priceLow = subjectPrice * 0.9;
  const priceHigh = subjectPrice * 1.1;
  const withinRange = comps.filter((c) => c.list_price >= priceLow && c.list_price <= priceHigh);
  const top10 = [...comps].sort((a, b) => a.similarity_score - b.similarity_score).slice(0, 10);
  return withinRange.length >= top10.length ? withinRange : top10;
}

function barColor(matchPercent: number): string {
  if (matchPercent >= 70) return 'bg-green-500';
  if (matchPercent >= 40) return 'bg-yellow-500';
  return 'bg-red-500';
}

// Mode-aware similarity weights (from CompEvidenceDrawer lines 184-211)
const VALUATION_WEIGHTS: Record<string, { label: string; weight: number }> = {
  score_sqft: { label: 'Square Footage', weight: 0.30 },
  score_subdivision: { label: 'Subdivision', weight: 0.20 },
  score_ranch: { label: 'Ranch Style', weight: 0.12 },
  score_recency: { label: 'Recency', weight: 0.10 },
  score_bedbath: { label: 'Beds/Baths', weight: 0.08 },
  score_garage: { label: 'Garage', weight: 0.06 },
  score_acres: { label: 'Lot Size', weight: 0.06 },
  score_basement: { label: 'Basement', weight: 0.04 },
  score_newcon: { label: 'New Construction', weight: 0.04 },
  score_price: { label: 'Price Match', weight: 0.00 },
};

const COMPETITIVE_WEIGHTS: Record<string, { label: string; weight: number }> = {
  score_sqft: { label: 'Square Footage', weight: 0.25 },
  score_price: { label: 'Price Match', weight: 0.20 },
  score_subdivision: { label: 'Subdivision', weight: 0.15 },
  score_ranch: { label: 'Ranch Style', weight: 0.10 },
  score_recency: { label: 'Recency', weight: 0.08 },
  score_bedbath: { label: 'Beds/Baths', weight: 0.08 },
  score_garage: { label: 'Garage', weight: 0.05 },
  score_acres: { label: 'Lot Size', weight: 0.05 },
  score_basement: { label: 'Basement', weight: 0.04 },
  score_newcon: { label: 'New Construction', weight: 0.00 },
};

type BreakdownRow = {
  label: string;
  weightPct: number;
  matchPercent: number;
  contributionPct: number;
};

function computeBreakdown(comp: DiagnosticComp, weights: Record<string, { label: string; weight: number }>): BreakdownRow[] {
  const rows: { label: string; weight: number; matchPercent: number }[] = [];

  for (const [key, { label, weight }] of Object.entries(weights)) {
    if (weight === 0) continue;
    const score = (comp as any)[key] as number | null;
    const mp = score != null ? Math.min(100, Math.max(0, (1 - score) * 100)) : 0;
    rows.push({ label, weight, matchPercent: mp });
  }

  const totalContribution = rows.reduce((sum, r) => sum + r.weight * r.matchPercent, 0);

  return rows.map((r) => ({
    label: r.label,
    weightPct: Math.round(r.weight * 100),
    matchPercent: r.matchPercent,
    contributionPct: totalContribution > 0 ? (r.weight * r.matchPercent / totalContribution) * 100 : 0,
  }));
}

export default function CompetitiveLadder({
  valuationComps,
  competitiveComps,
  subjectPrice,
  subjectPpsf,
  subjectSqft,
  subjectDom,
  domSource,
  subjectBeds,
  subjectBathsFull,
  subjectBathsHalf,
  subjectSubdivision,
  subjectIsRanch,
  specId,
  shortCode,
  initialPool,
  scrollNonce,
  iqrExcludedMlsNumbers,
  iqrBounds,
}: CompetitiveLadderProps) {
  const [activePool, setActivePool] = useState<'valuation' | 'competitive'>(initialPool ?? 'competitive');
  const [sortKey, setSortKey] = useState<SortKey>('similarity');
  const [sortDir, setSortDir] = useState<SortDir>('desc');
  const [expandedMls, setExpandedMls] = useState<string | null>(null);
  const [outlierExpanded, setOutlierExpanded] = useState(false);

  // React to initialPool prop changes (when user clicks scroll link)
  useEffect(() => {
    if (initialPool) {
      setActivePool(initialPool);
      // Scroll after state update renders
      requestAnimationFrame(() => {
        const el = document.getElementById('comp-ladder-section');
        if (el && typeof el.scrollIntoView === 'function') {
          el.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      });
    }
  }, [initialPool, scrollNonce]);

  // Split valuation comps into retained (IQR-included) and excluded (outliers)
  const { retainedComps, excludedComps } = useMemo(() => {
    if (activePool !== 'valuation' || !iqrExcludedMlsNumbers || iqrExcludedMlsNumbers.size === 0) {
      return { retainedComps: valuationComps, excludedComps: [] as DiagnosticComp[] };
    }
    const retained: DiagnosticComp[] = [];
    const excluded: DiagnosticComp[] = [];
    for (const c of valuationComps) {
      if (iqrExcludedMlsNumbers.has(c.mls_number)) {
        excluded.push(c);
      } else {
        retained.push(c);
      }
    }
    return { retainedComps: retained, excludedComps: excluded };
  }, [activePool, valuationComps, iqrExcludedMlsNumbers]);

  const displayComps = useMemo(() => {
    if (activePool === 'competitive') {
      return filterComps(competitiveComps, subjectPrice);
    }
    return retainedComps; // valuation: show only IQR-retained comps in main table
  }, [activePool, competitiveComps, retainedComps, subjectPrice]);

  const activeWeights = activePool === 'valuation' ? VALUATION_WEIGHTS : COMPETITIVE_WEIGHTS;

  // Memoize breakdown rows per comp (includes excluded comps for outlier section)
  const breakdownCache = useMemo(() => {
    const cache = new Map<string, BreakdownRow[]>();
    for (const comp of displayComps) {
      cache.set(comp.mls_number, computeBreakdown(comp, activeWeights));
    }
    for (const comp of excludedComps) {
      cache.set(comp.mls_number, computeBreakdown(comp, activeWeights));
    }
    return cache;
  }, [displayComps, excludedComps, activeWeights]);

  const sortComps = (comps: DiagnosticComp[]) => {
    return [...comps].sort((a, b) => {
      let aVal = 0;
      let bVal = 0;
      switch (sortKey) {
        case 'similarity':
          aVal = matchPct(a.similarity_score);
          bVal = matchPct(b.similarity_score);
          break;
        case 'price':
          aVal = a.list_price;
          bVal = b.list_price;
          break;
        case 'ppsf':
          aVal = a.price_per_sqft;
          bVal = b.price_per_sqft;
          break;
        case 'dom':
          aVal = a.dom;
          bVal = b.dom;
          break;
        case 'sqft':
          aVal = a.sqft;
          bVal = b.sqft;
          break;
        case 'bedsBaths':
          aVal = (a.bedrooms ?? 0) * 10 + ((a.baths_full ?? 0) + 0.5 * (a.baths_half ?? 0));
          bVal = (b.bedrooms ?? 0) * 10 + ((b.baths_full ?? 0) + 0.5 * (b.baths_half ?? 0));
          break;
      }
      const diff = aVal - bVal;
      return sortDir === 'desc' ? -diff : diff;
    });
  };

  const sorted = sortComps(displayComps);

  const handleSort = (key: SortKey) => {
    if (sortKey === key) {
      setSortDir((d) => (d === 'asc' ? 'desc' : 'asc'));
    } else {
      setSortKey(key);
      setSortDir('asc');
    }
  };

  const sortIcon = (key: SortKey) => {
    if (sortKey !== key) return null;
    return sortDir === 'asc' ? (
      <svg className="inline w-3 h-3 ml-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 15l7-7 7 7" /></svg>
    ) : (
      <svg className="inline w-3 h-3 ml-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
    );
  };

  const renderCompRow = (comp: DiagnosticComp) => {
    const isExpanded = expandedMls === comp.mls_number;

    return (
      <Fragment key={comp.mls_number}>
        <tr className="border-b border-gray-100 hover:bg-gray-50">
          <td className="py-1.5 px-1">
            <button
              onClick={() => {
                const nextMls = isExpanded ? null : comp.mls_number;
                setExpandedMls(nextMls);
                if (nextMls) {
                  trackEvent('diagnostic_similarity_expanded', { specId, mlsNumber: comp.mls_number });
                }
              }}
              aria-expanded={isExpanded}
              className="text-ink-muted hover:text-ink text-xs"
              data-testid={`similarity-toggle-${comp.mls_number}`}
              title={isExpanded ? 'Hide similarity breakdown' : 'Show similarity breakdown'}
            >
              {isExpanded ? (
                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
              ) : (
                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
              )}
            </button>
          </td>
          <td className="py-1.5 px-2">
            <span className={`text-xs px-2 py-0.5 rounded-full ${matchBadgeClasses(comp.similarity_score)}`}>
              {matchLabel(comp.similarity_score)}
            </span>
            <span className="text-ink-muted ml-1 text-xs">({matchPct(comp.similarity_score).toFixed(0)}%)</span>
          </td>
          <td className="py-1.5 px-2 text-ink truncate max-w-[200px]">{comp.address ?? comp.mls_number}</td>
          <td className="py-1.5 px-2 text-right">{formatUsd(comp.list_price)}</td>
          <td className="py-1.5 px-2 text-right">{formatNumber(comp.sqft)}</td>
          <td className="py-1.5 px-2 text-right">{formatPricePerSqft(comp.price_per_sqft)}</td>
          <td className="py-1.5 px-2 text-right">{comp.dom}</td>
          <td className="py-1.5 px-2">{formatBedsBaths(comp.bedrooms, comp.baths_full, comp.baths_half)}</td>
          <td className="py-1.5 px-2 text-ink-muted truncate max-w-[140px]" title={comp.subdivision ?? ''}>
            {comp.subdivision ?? '—'}
          </td>
          <td className="py-1.5 px-2 text-center">
            {comp.is_ranch_style == null ? '—' : comp.is_ranch_style ? 'Yes' : 'No'}
          </td>
        </tr>
        {isExpanded && (
          <tr data-testid={`similarity-panel-${comp.mls_number}`}>
            <td colSpan={COL_COUNT} className="py-3 px-4 bg-gray-50">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {/* Left: similarity bars */}
                <div>
                  <h5 className="text-xs font-medium text-ink uppercase tracking-wider mb-2 flex items-center gap-1">
                    Similarity Breakdown
                    <Tooltip content={<>
                      <strong className="block mb-1 text-white">How to read this breakdown:</strong>
                      <strong>Label (Weight%)</strong> — Dimension name and its importance in scoring.<br />
                      <strong>Bar</strong> — Match quality: <span className="text-green-300">green</span> {'\u2265'}70%, <span className="text-yellow-300">yellow</span> 40–69%, <span className="text-red-300">red</span> {'<'}40%.<br />
                      <strong>Match %</strong> — How closely the comp matches on this dimension (100% = identical).<br />
                      <strong className="text-brand/70">+Contribution %</strong> — Share of total similarity score this dimension drives.
                    </>} position="bottom" width="w-72">
                      <span className="inline-flex items-center justify-center w-3.5 h-3.5 rounded-full border border-gray-300 text-[9px] text-ink-muted cursor-help flex-shrink-0">?</span>
                    </Tooltip>
                  </h5>
                  <div className="space-y-1.5">
                    {(breakdownCache.get(comp.mls_number) ?? []).map((row) => (
                      <div key={row.label} className="flex items-center gap-2">
                        <span className="text-xs text-ink w-40 flex-shrink-0" title={`${row.label} (${row.weightPct}%)`}>
                          {row.label} ({row.weightPct}%)
                        </span>
                        <div className="flex-1 h-2 bg-gray-200 rounded-full max-w-[120px]">
                          <div
                            className={`h-full rounded-full ${barColor(row.matchPercent)}`}
                            style={{ width: `${Math.min(row.matchPercent, 100)}%` }}
                          />
                        </div>
                        <span className="text-xs text-ink-muted w-10 text-right">
                          {row.matchPercent.toFixed(0)}%
                        </span>
                        <span className="text-xs text-brand font-medium w-12 text-right flex-shrink-0">
                          +{row.contributionPct.toFixed(1)}%
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
                {/* Right: relevance text */}
                <div>
                  <h5 className="text-xs font-medium text-ink uppercase tracking-wider mb-2">
                    Why This Comp Matters
                  </h5>
                  <p className="text-xs text-ink-muted leading-relaxed" data-testid="comp-relevance">
                    {comp.relevance_text}
                  </p>
                </div>
              </div>
            </td>
          </tr>
        )}
      </Fragment>
    );
  };

  const isEmpty = valuationComps.length === 0 && competitiveComps.length === 0;

  if (isEmpty) {
    return (
      <div data-testid="competitive-ladder-empty">
        <EmptyState message="No comps available." component="CompetitiveLadder" />
      </div>
    );
  }

  return (
    <div id="comp-ladder-section" className="scroll-mt-4" data-testid="competitive-ladder">
      <div className="flex items-center gap-2 mb-2">
        <h4 className="text-xs font-semibold text-ink uppercase tracking-wider">
          Comp Ladder
        </h4>
        <MethodologyLink methodologyId="comp-selection" />
      </div>

      {/* Tab bar */}
      <TabBar
        tabs={[
          { id: 'valuation', label: 'Valuation', count: valuationComps.length },
          { id: 'competitive', label: 'Competitive', count: competitiveComps.length },
        ]}
        activeTab={activePool}
        onChange={(id) => setActivePool(id as 'valuation' | 'competitive')}
        className="mb-3"
        data-testid="ladder-tab-bar"
      />

      <div className="overflow-x-auto">
        <table className="w-full text-xs">
          <thead>
            <tr className="border-b border-gray-200 text-ink-muted">
              <th className="py-1.5 px-1 w-6" />
              <th className="py-1.5 px-2 text-left cursor-pointer hover:text-ink" onClick={() => handleSort('similarity')}>
                <span className="inline-flex items-center gap-1">
                  Match{sortIcon('similarity')}
                  <TooltipIcon
                    content={<>
                      <strong className="block mb-1">Similarity Match</strong>
                      Weighted score based on property characteristics.
                      <strong className="text-green-300"> Strong</strong> (≥85%): highly comparable.
                      <strong className="text-yellow-300"> Good</strong> (70–84%): reasonably comparable.
                      <strong className="text-red-300"> Fair</strong> (&lt;70%): weaker match.
                      Weights vary by mode — valuation emphasizes sqft and subdivision, competitive adds price match.
                    </>}
                    testId="match-tooltip"
                    width="w-64"
                  />
                </span>
              </th>
              <th className="py-1.5 px-2 text-left">Address</th>
              <th className="py-1.5 px-2 text-right cursor-pointer hover:text-ink" onClick={() => handleSort('price')}>
                Price{sortIcon('price')}
              </th>
              <th className="py-1.5 px-2 text-right cursor-pointer hover:text-ink" onClick={() => handleSort('sqft')}>
                Sqft{sortIcon('sqft')}
              </th>
              <th className="py-1.5 px-2 text-right cursor-pointer hover:text-ink" onClick={() => handleSort('ppsf')}>
                $/SF{sortIcon('ppsf')}
              </th>
              <th className="py-1.5 px-2 text-right cursor-pointer hover:text-ink" onClick={() => handleSort('dom')}>
                DOM{sortIcon('dom')}
              </th>
              <th className="py-1.5 px-2 text-left cursor-pointer hover:text-ink" onClick={() => handleSort('bedsBaths')}>
                Beds/Baths{sortIcon('bedsBaths')}
              </th>
              <th className="py-1.5 px-2 text-left">Subdivision</th>
              <th className="py-1.5 px-2 text-center">Ranch</th>
            </tr>
          </thead>
          <tbody>
            {/* Subject row always at top */}
            <tr key="subject" data-testid="subject-row" className="bg-green-50 border-y border-green-200 font-medium text-green-800">
              <td className="py-1.5 px-1" />
              <td className="py-1.5 px-2"><svg className="w-3 h-3 inline" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z" /></svg></td>
              <td className="py-1.5 px-2">Subject Property</td>
              <td className="py-1.5 px-2 text-right">{formatUsd(subjectPrice)}</td>
              <td className="py-1.5 px-2 text-right">{formatNumber(subjectSqft)}</td>
              <td className="py-1.5 px-2 text-right">{formatPricePerSqft(subjectPpsf)}</td>
              <td className="py-1.5 px-2 text-right" title={domSource !== 'mls_dom' ? 'Inventory age (no MLS listing match)' : undefined}>
                {subjectDom}{domSource !== 'mls_dom' && <span className="text-xs text-amber-600 ml-0.5" title="Inventory age — not MLS DOM">*</span>}
              </td>
              <td className="py-1.5 px-2">{formatBedsBaths(subjectBeds, subjectBathsFull, subjectBathsHalf)}</td>
              <td className="py-1.5 px-2 truncate max-w-[140px]" title={subjectSubdivision ?? ''}>
                {subjectSubdivision ?? '—'}
              </td>
              <td className="py-1.5 px-2 text-center">
                {subjectIsRanch == null ? '—' : subjectIsRanch ? 'Yes' : 'No'}
              </td>
            </tr>

            {/* Flat sorted comp list */}
            {sorted.length === 0 && (
              <tr>
                <td colSpan={COL_COUNT} className="py-6 text-center text-xs text-ink-muted italic" data-testid="competitive-empty-state">
                  {activePool === 'competitive'
                    ? 'No third-party competitive listings found in this area.'
                    : 'No sold comps found in this area.'}
                </td>
              </tr>
            )}
            {sorted.map((comp) => renderCompRow(comp))}
          </tbody>
        </table>
      </div>

      {/* Collapsible outlier section — only on valuation pool when IQR excluded comps exist */}
      {activePool === 'valuation' && excludedComps.length > 0 && (
        <div className="mt-2 border-t-2 border-dashed border-gray-300 pt-2" data-testid="outlier-section">
          <button
            type="button"
            onClick={() => setOutlierExpanded((prev) => !prev)}
            className="flex items-center gap-1.5 text-xs text-ink-muted hover:text-ink font-medium"
            data-testid="outlier-toggle"
          >
            <svg className={`w-3 h-3 transition-transform ease-out ${outlierExpanded ? 'rotate-90' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
            Excluded outliers ({excludedComps.length})
            {iqrBounds && (
              <span className="font-normal">
                {' '}— outside {formatPricePerSqft(iqrBounds.lowerBound)}–{formatPricePerSqft(iqrBounds.upperBound)} /SF
              </span>
            )}
          </button>
          {outlierExpanded && (
            <div className="overflow-x-auto mt-1.5">
              <table className="w-full text-xs opacity-60">
                <tbody>
                  {sortComps(excludedComps).map((comp) => renderCompRow(comp))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, type Dispatch } from 'react';
import { checkFeasibility, type FloorPlan } from '../../../lib/p3Engine';

interface Lot {
  id: string;
  lot_number: string;
  width: number;
  depth: number;
  premium_cost: number;
  premium_price: number;
  status: string;
  constraints?: string[];
  notes?: string;
}

interface LotSelectorProps {
  communityId: string;
  floorPlan: FloorPlan;
  selectedLot: Lot | null;
  onSelect: Dispatch<Lot>;
}

export default function LotSelector({ communityId, floorPlan, selectedLot, onSelect }: LotSelectorProps) {
  const [lots, setLots] = useState<Lot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showUnavailable, setShowUnavailable] = useState(false);
  const [sortBy, setSortBy] = useState<'number' | 'size' | 'premium'>('number');

  useEffect(() => {
    if (communityId) {
      fetchLots();
    }
  }, [communityId]);

  async function fetchLots() {
    try {
      setLoading(true);
      const response = await fetch(`/api/lots?communityId=${communityId}`);
      if (!response.ok) throw new Error('Failed to fetch lots');
      const data = await response.json();
      setLots(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load lots');
    } finally {
      setLoading(false);
    }
  }

  // Check compatibility for each lot
  const lotsWithCompatibility = lots.map((lot) => {
    const feasibility = checkFeasibility(floorPlan, lot);
    return {
      ...lot,
      compatible: feasibility.feasible,
      reasons: feasibility.reasons,
    };
  });

  // Filter and sort
  const filteredLots = lotsWithCompatibility
    .filter((lot) => {
      if (!showUnavailable && lot.status !== 'available') return false;
      return true;
    })
    .sort((a, b) => {
      switch (sortBy) {
        case 'size':
          return (b.width * b.depth) - (a.width * a.depth);
        case 'premium':
          return a.premium_price - b.premium_price;
        default:
          return a.lot_number.localeCompare(b.lot_number, undefined, { numeric: true });
      }
    });

  const compatibleLots = filteredLots.filter((lot) => lot.compatible);
  const incompatibleLots = filteredLots.filter((lot) => !lot.compatible);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="inline-block h-8 w-8 animate-spin rounded-full border-4 border-solid border-brand border-r-transparent"></div>
        <span className="ml-3 text-ink-muted">Loading lots...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 border border-red-200 rounded-lg p-4 text-red-700">
        {error}
      </div>
    );
  }

  if (lots.length === 0) {
    return (
      <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-6 text-center">
        <h3 className="text-lg font-medium text-yellow-800 mb-2">No Lots Found</h3>
        <p className="text-yellow-700 mb-4">
          This community doesn't have any lots added yet. Add lots first.
        </p>
        <a
          href={`/communities/${communityId}/lots/add`}
          className="inline-flex items-center px-4 py-2 bg-brand text-white rounded-lg hover:bg-brand-hover transition-colors ease-out"
        >
          Add Lots
        </a>
      </div>
    );
  }

  return (
    <div>
      <h2 className="text-xl font-semibold text-ink mb-2">Select Lot</h2>
      <p className="text-ink-muted mb-4">
        Choose a lot for <span className="font-medium text-ink">{floorPlan.name}</span>.
        {floorPlan.min_lot_width && (
          <span className="text-sm"> Requires min {floorPlan.min_lot_width}'×{floorPlan.min_lot_depth || '?'}' lot.</span>
        )}
      </p>

      {/* Filters */}
      <div className="flex flex-wrap gap-4 mb-6 items-center">
        <div>
          <label className="block text-xs text-ink-muted mb-1">Sort By</label>
          <select
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value as 'number' | 'size' | 'premium')}
            className="px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-brand focus:border-transparent"
          >
            <option value="number">Lot Number</option>
            <option value="size">Size (Largest First)</option>
            <option value="premium">Premium (Lowest First)</option>
          </select>
        </div>
        <label className="flex items-center mt-5">
          <input
            type="checkbox"
            checked={showUnavailable}
            onChange={(e) => setShowUnavailable(e.target.checked)}
            className="w-4 h-4 text-brand border-gray-300 rounded focus:ring-brand"
          />
          <span className="ml-2 text-sm text-ink-muted">Show reserved/sold lots</span>
        </label>
      </div>

      {/* Summary */}
      <div className="bg-gray-50 rounded-lg p-3 mb-6 flex items-center justify-between">
        <span className="text-sm text-ink-muted">
          Showing {compatibleLots.length} compatible lot{compatibleLots.length !== 1 ? 's' : ''}
          {incompatibleLots.length > 0 && ` (${incompatibleLots.length} incompatible)`}
        </span>
      </div>

      {/* Compatible Lots */}
      {compatibleLots.length === 0 ? (
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4 text-center">
          <p className="text-yellow-700">
            No compatible lots available for this floor plan.
            {!showUnavailable && ' Try showing reserved/sold lots.'}
          </p>
        </div>
      ) : (
        <div className="space-y-3 mb-6">
          {compatibleLots.map((lot) => {
            const isSelected = selectedLot?.id === lot.id;
            const sqft = lot.width * lot.depth;

            return (
              <button
                key={lot.id}
                onClick={() => onSelect(lot)}
                disabled={lot.status !== 'available'}
                className={`w-full text-left p-4 rounded-lg border-2 transition-all ease-out ${
                  lot.status !== 'available'
                    ? 'border-gray-200 bg-gray-50 opacity-60 cursor-not-allowed'
                    : isSelected
                    ? 'border-brand bg-brand/5 ring-2 ring-brand/20'
                    : 'border-gray-200 hover:border-brand/50 hover:bg-gray-50'
                }`}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-4">
                    <div>
                      <span className="font-semibold text-ink">Lot {lot.lot_number}</span>
                      {lot.status !== 'available' && (
                        <span className={`ml-2 px-2 py-0.5 text-xs rounded-full ${
                          lot.status === 'reserved' ? 'bg-amber-50 text-amber-600' : 'bg-red-50 text-red-700'
                        }`}>
                          {lot.status}
                        </span>
                      )}
                    </div>
                    <span className="text-sm text-ink-muted">
                      {lot.width}'×{lot.depth}' ({sqft.toLocaleString()} sqft)
                    </span>
                  </div>

                  <div className="flex items-center gap-4">
                    {lot.premium_price > 0 ? (
                      <span className="text-sm font-medium text-ink">
                        +${lot.premium_price.toLocaleString()}
                      </span>
                    ) : (
                      <span className="text-sm text-green-600">No premium</span>
                    )}

                    {isSelected && (
                      <span className="w-5 h-5 bg-brand rounded-full flex items-center justify-center">
                        <svg className="w-3 h-3 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                        </svg>
                      </span>
                    )}
                  </div>
                </div>

                {/* Constraints */}
                {lot.constraints && lot.constraints.length > 0 && (
                  <div className="mt-2 flex flex-wrap gap-1">
                    {lot.constraints.map((constraint, idx) => (
                      <span
                        key={idx}
                        className="px-2 py-0.5 bg-blue-100 text-blue-700 text-xs rounded-full"
                      >
                        {constraint}
                      </span>
                    ))}
                  </div>
                )}
              </button>
            );
          })}
        </div>
      )}

      {/* Incompatible Lots */}
      {incompatibleLots.length > 0 && (
        <div className="mt-6">
          <h3 className="text-sm font-medium text-ink-muted mb-3 flex items-center">
            <svg className="w-4 h-4 mr-1 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M18.364 18.364A9 9 0 005.636 5.636m12.728 12.728A9 9 0 015.636 5.636m12.728 12.728L5.636 5.636" />
            </svg>
            Incompatible Lots ({incompatibleLots.length})
          </h3>
          <div className="space-y-2">
            {incompatibleLots.map((lot) => (
              <div
                key={lot.id}
                className="p-3 rounded-lg border border-gray-200 bg-gray-50 opacity-60"
              >
                <div className="flex items-center justify-between">
                  <div>
                    <span className="font-medium text-ink-muted">Lot {lot.lot_number}</span>
                    <span className="ml-2 text-sm text-gray-400">
                      {lot.width}'×{lot.depth}'
                    </span>
                  </div>
                </div>
                {lot.reasons && lot.reasons.length > 0 && (
                  <p className="text-xs text-red-500 mt-1">{lot.reasons[0]}</p>
                )}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

import { useEffect, useState, type ReactNode } from 'react';

interface Community {
  id: string;
  name: string;
  zip?: string;
  absorption_rate?: number;
  active_listings?: number;
  months_supply?: number;
  avg_price_psf?: number;
  competitive_density?: number;
}

interface AIMarketInsights {
  marketAssessment: string;
  opportunities: string[];
  risks: string[];
  recommendedP3Bias: 'pace' | 'profit' | 'persona' | 'balanced';
  narrative: string;
  cached?: boolean;
  updatedAt?: string;
}

interface MarketInsightsDisplayProps {
  community: Community;
}

type Bias = AIMarketInsights['recommendedP3Bias'];

const BIAS_DETAILS: Record<Bias, { icon: string; label: string }> = {
  pace: { icon: '🚀', label: 'Prioritize Pace' },
  profit: { icon: '💰', label: 'Prioritize Profit' },
  persona: { icon: '🎯', label: 'Prioritize Persona' },
  balanced: { icon: '⚖️', label: 'Balanced Approach' },
};

function getMarketAssessment(community: Community): { label: string; color: string; description: string } {
  const absorption = community.absorption_rate || 0;
  const monthsSupply = community.months_supply || 6;

  if (absorption >= 3 && monthsSupply < 4) {
    return {
      label: 'Hot Market',
      color: 'bg-red-50 text-red-700 border-red-200',
      description: 'High demand, low inventory. Consider prioritizing pace to capture market momentum.',
    };
  } else if (absorption >= 2 && monthsSupply < 6) {
    return {
      label: 'Active Market',
      color: 'bg-amber-50 text-amber-600 border-amber-200',
      description: 'Balanced demand and supply. Good conditions for spec building.',
    };
  } else if (absorption >= 1.5) {
    return {
      label: 'Moderate Market',
      color: 'bg-yellow-50 text-yellow-700 border-yellow-200',
      description: 'Steady activity. Focus on differentiation through persona targeting.',
    };
  } else {
    return {
      label: 'Slow Market',
      color: 'bg-blue-100 text-blue-700 border-blue-200',
      description: 'Lower absorption. Prioritize margins and perfect buyer matching.',
    };
  }
}

function MetricCard({ label, value, subtext, icon }: { label: string; value: string; subtext?: string; icon: ReactNode }) {
  return (
    <div className="bg-white rounded-lg border border-gray-200 p-4">
      <div className="flex items-start justify-between">
        <div>
          <p className="text-sm text-ink-muted mb-1">{label}</p>
          <p className="text-2xl font-bold text-ink">{value}</p>
          {subtext && <p className="text-xs text-ink-muted mt-1">{subtext}</p>}
        </div>
        <div className="text-brand opacity-50">{icon}</div>
      </div>
    </div>
  );
}

function competitiveDensityMessage(value: number): string {
  if (value > 7) return 'High competition - differentiation is critical';
  if (value > 4) return 'Moderate competition - standard positioning should work';
  return 'Low competition - opportunity for premium pricing';
}

type AiInsightsSectionProps = {
  zip?: string;
  insights: AIMarketInsights | null;
  loading: boolean;
  error: string | null;
  onRetry: () => void;
};

function AiInsightsBody({ insights }: { insights: AIMarketInsights }) {
  const biasDetail = insights ? BIAS_DETAILS[insights.recommendedP3Bias] : null;

  return (
    <div className="space-y-4">
      <p className="text-sm text-blue-900">{insights.narrative}</p>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
        {insights.opportunities.length > 0 && (
          <div className="bg-green-50 rounded-lg p-3 border border-green-200">
            <h4 className="text-xs font-semibold text-green-700 uppercase tracking-wide mb-2">Opportunities</h4>
            <ul className="space-y-1">
              {insights.opportunities.map((opportunity, index) => (
                <li key={index} className="text-sm text-green-700 flex items-start">
                  <span className="text-green-500 mr-1">✓</span>
                  {opportunity}
                </li>
              ))}
            </ul>
          </div>
        )}
        {insights.risks.length > 0 && (
          <div className="bg-amber-50 rounded-lg p-3 border border-amber-200">
            <h4 className="text-xs font-semibold text-amber-600 uppercase tracking-wide mb-2">Risks</h4>
            <ul className="space-y-1">
              {insights.risks.map((risk, index) => (
                <li key={index} className="text-sm text-amber-700 flex items-start">
                  <span className="text-amber-500 mr-1">!</span>
                  {risk}
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>

      {biasDetail && (
        <div className="flex items-center justify-between bg-white/50 rounded-lg p-3">
          <div>
            <span className="text-xs font-medium text-blue-700 uppercase tracking-wide">AI Recommendation</span>
            <p className="text-sm font-semibold text-blue-900">
              {biasDetail.icon} {biasDetail.label}
            </p>
          </div>
          <span className="text-xs text-blue-600">Based on current market conditions</span>
        </div>
      )}
    </div>
  );
}

function renderAiSectionContent(
  zip: string | undefined,
  insights: AIMarketInsights | null,
  loading: boolean,
  error: string | null,
  onRetry: () => void,
) {
  if (!zip) {
    return (
      <p className="text-sm text-blue-700">
        Add a ZIP code to this community to enable AI-powered market analysis.
      </p>
    );
  }

  if (loading) {
    return (
      <div className="flex items-center">
        <div className="inline-block h-4 w-4 animate-spin rounded-full border-2 border-solid border-blue-600 border-r-transparent mr-2"></div>
        <span className="text-sm text-blue-700">Analyzing market data...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="text-sm text-red-600">
        {error}
        <button onClick={onRetry} className="ml-2 text-blue-600 hover:text-blue-800 underline">
          Retry
        </button>
      </div>
    );
  }

  if (!insights) {
    return (
      <p className="text-sm text-blue-700">
        AI analysis will appear here once market data is loaded.
      </p>
    );
  }

  return <AiInsightsBody insights={insights} />;
}

function AiInsightsSection({ zip, insights, loading, error, onRetry }: AiInsightsSectionProps) {
  return (
    <div className="mt-6 p-4 bg-gradient-to-r from-blue-50 to-blue-50 border border-blue-200 rounded-lg">
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center">
          <svg className="w-5 h-5 text-blue-600 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" />
          </svg>
          <span className="font-medium text-blue-800">AI Market Analysis</span>
        </div>
        {insights?.cached && (
          <span className="text-xs text-blue-600">
            Updated {insights.updatedAt ? new Date(insights.updatedAt).toLocaleDateString() : 'recently'}
          </span>
        )}
      </div>

      {renderAiSectionContent(zip, insights, loading, error, onRetry)}
    </div>
  );
}

export default function MarketInsightsDisplay({ community }: MarketInsightsDisplayProps) {
  const [aiInsights, setAiInsights] = useState<AIMarketInsights | null>(null);
  const [aiLoading, setAiLoading] = useState(false);
  const [aiError, setAiError] = useState<string | null>(null);

  const assessment = getMarketAssessment(community);
  const hasMarketData = community.absorption_rate || community.months_supply || community.avg_price_psf;

  // Fetch AI insights when community has a zip code
  useEffect(() => {
    if (community.zip) {
      fetchAIInsights(community.zip);
    }
  }, [community.zip]);

  async function fetchAIInsights(zipcode: string) {
    setAiLoading(true);
    setAiError(null);

    try {
      const response = await fetch(`/api/ai/market-insights?zipcode=${zipcode}`);
      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || 'Failed to fetch AI insights');
      }
      const data = await response.json();
      setAiInsights(data);
    } catch (err) {
      setAiError(err instanceof Error ? err.message : 'Failed to load AI insights');
    } finally {
      setAiLoading(false);
    }
  }

  return (
    <div>
      <h2 className="text-xl font-semibold text-ink mb-2">Market Insights</h2>
      <p className="text-ink-muted mb-6">
        Review market conditions for <span className="font-medium text-ink">{community.name}</span>
      </p>

      {!hasMarketData ? (
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-6">
          <h3 className="text-lg font-medium text-yellow-800 mb-2">No Market Data Available</h3>
          <p className="text-yellow-700 mb-4">
            This community doesn't have market metrics set up yet. Consider adding absorption rate,
            months of supply, and average price per square foot in the community settings.
          </p>
          <p className="text-sm text-yellow-600">
            You can continue without market data, but P3 scoring accuracy will be limited.
          </p>
        </div>
      ) : (
        <>
          {/* Market Assessment */}
          <div className={`rounded-lg border-2 p-4 mb-6 ${assessment.color}`}>
            <div className="flex items-center mb-2">
              <span className="text-lg font-bold">{assessment.label}</span>
            </div>
            <p className="text-sm">{assessment.description}</p>
          </div>

          {/* Metrics Grid */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
            <MetricCard
              label="Absorption Rate"
              value={community.absorption_rate ? `${community.absorption_rate}` : 'N/A'}
              subtext="homes/month"
              icon={
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" />
                </svg>
              }
            />
            <MetricCard
              label="Months Supply"
              value={community.months_supply ? `${community.months_supply}` : 'N/A'}
              subtext="inventory months"
              icon={
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
