  all: null,
  Active: ['Active'],
  Pending: ['Pending'],
  Sold: ['Closed'],
};

const buildMarketQueryPart = (
  sqftFilterEnabled: boolean,
  sqftRangeData: SqftRange | null,
) => {
  const params = new URLSearchParams();
  const shouldApplySqftFilter =
    sqftFilterEnabled &&
    (sqftRangeData?.ross_count ?? 0) > 0;

  if (!shouldApplySqftFilter) {
    return '';
  }

  if (sqftRangeData?.market_min_sqft != null) {
    params.set('minSqft', sqftRangeData.market_min_sqft.toString());
  }
  if (sqftRangeData?.market_max_sqft != null) {
    params.set('maxSqft', sqftRangeData.market_max_sqft.toString());
  }

  const queryString = params.toString();
  return queryString ? `?${queryString}` : '';
};

const shouldRedirectForAuth = (...responses: Response[]) =>
  responses.some((response) => response.status === 401);

type MarketLoadResult =
  | { kind: 'unauthorized' }
  | { kind: 'error'; summaryStatus: number; listingsStatus: number }
  | {
      kind: 'ok';
      sqftRangeData: SqftRange | null;
      summaryData: MarketSummary;
      listingsData: MarketListing[];
    };

type MarketFetchContext = {
  normalizedShortCode: string;
  sqftFilterEnabled: boolean;
  setLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
  setSqftRange: (range: SqftRange | null) => void;
  setSummary: (summary: MarketSummary | null) => void;
  setListings: (listings: MarketListing[]) => void;
};

const performMarketFetch = async ({
  normalizedShortCode,
  sqftFilterEnabled,
  setLoading,
  setError,
  setSqftRange,
  setSummary,
  setListings,
}: MarketFetchContext) => {
  try {
    setLoading(true);
    setError(null);

    const result = await loadCommunityMarketData(normalizedShortCode, sqftFilterEnabled);
    if (result.kind === 'unauthorized') {
      window.location.href = '/';
      return;
    }

    if (result.kind === 'error') {
      setError('Unable to load market data. Please try again.');
      trackError('community_market_load_failed', 'Failed to load market data', {
        short_code: normalizedShortCode,
        summaryStatus: result.summaryStatus,
        listingsStatus: result.listingsStatus,
      });
      return;
    }

    setSqftRange(result.sqftRangeData);
    setSummary(result.summaryData);
    setListings(result.listingsData || []);
    trackEvent('community_market_loaded', {
      short_code: normalizedShortCode,
      is_configured: result.summaryData.is_configured,
      count: result.listingsData?.length ?? 0,
      sqft_filter_enabled: sqftFilterEnabled,
      sqft_filter_available: (result.sqftRangeData?.ross_count ?? 0) > 0,
    });
  } catch (err) {
    setError('Unable to load market data. Please try again.');
    trackError('community_market_load_failed', err instanceof Error ? err : 'Fetch failed', {
      short_code: normalizedShortCode,
    });
  } finally {
    setLoading(false);
  }
};

const loadCommunityMarketData = async (
  normalizedShortCode: string,
  sqftFilterEnabled: boolean,
): Promise<MarketLoadResult> => {
  const sqftRangeRes = await fetch(`/api/communities/${normalizedShortCode}/sqft-range`);
  if (sqftRangeRes.status === 401) {
    return { kind: 'unauthorized' };
  }

  let sqftRangeData: SqftRange | null = null;
  if (sqftRangeRes.ok) {
    sqftRangeData = (await sqftRangeRes.json()) as SqftRange;
  }

  const queryPart = buildMarketQueryPart(sqftFilterEnabled, sqftRangeData);
  const [summaryRes, listingsRes] = await Promise.all([
    fetch(`/api/communities/${normalizedShortCode}/market-summary${queryPart}`),
    fetch(`/api/communities/${normalizedShortCode}/market${queryPart}`),
  ]);

  if (shouldRedirectForAuth(summaryRes, listingsRes)) {
    return { kind: 'unauthorized' };
  }

  if (!summaryRes.ok || !listingsRes.ok) {
    return {
      kind: 'error',
      summaryStatus: summaryRes.status,
      listingsStatus: listingsRes.status,
    };
  }

  return {
    kind: 'ok',
    sqftRangeData,
    summaryData: (await summaryRes.json()) as MarketSummary,
    listingsData: (await listingsRes.json()) as MarketListing[],
  };
};

