export default function CommunityMarket({ shortCode }: CommunityMarketProps) {
  const normalizedShortCode = useMemo(() => shortCode.trim().toUpperCase(), [shortCode]);

  const [summary, setSummary] = useState<MarketSummary | null>(null);
  const [listings, setListings] = useState<MarketListing[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [sqftRange, setSqftRange] = useState<SqftRange | null>(null);
  const [sqftFilterEnabled, setSqftFilterEnabled] = useState(true);

  const [statusFilter, setStatusFilter] = useState<StatusFilter>('all');

  const fetchData = async () => {
    await performMarketFetch({
      normalizedShortCode,
      sqftFilterEnabled,
      setLoading,
      setError,
      setSqftRange,
      setSummary,
      setListings,
    });
  };

  useEffect(() => {
    initPostHog();
    fetchData();
    // eslint-disable-next-line react-hooks/exhaustive-deps -- fetchData depends on shortCode and sqftFilterEnabled; keep effect concise
  }, [normalizedShortCode, sqftFilterEnabled]);

  // Filter listings by status
  const filteredListings = useMemo(() => {
    const allowedStatuses = STATUS_FILTER_VALUES[statusFilter];
    if (!allowedStatuses) return listings;
    return listings.filter((l) => l.status != null && allowedStatuses.includes(l.status));
  }, [listings, statusFilter]);

  const handleToggleSqftFilter = () => {
    const newValue = !sqftFilterEnabled;
    setSqftFilterEnabled(newValue);
    trackEvent('market_sqft_filter_toggled', {
      short_code: normalizedShortCode,
      enabled: newValue,
      ross_count: sqftRange?.ross_count ?? 0,
    });
  };

  const columns = useMemo<DataGridColumn<MarketListing>[]>(() => [
    {
      id: 'address',
      header: 'Address',
      getValue: (row) => row.address ?? '',
      render: (row) => (
        <span className={`block ${row.is_garman ? 'font-medium' : ''}`} title={row.address ?? '—'}>
          {row.is_garman ? `★ ${row.address ?? '—'}` : row.address ?? '—'}
        </span>
      ),

    },
    {
      id: 'city',
      header: 'City',
      format: (v) => (v as string) ?? '—',

    },
    {
      id: 'list_price',
      header: 'Price',
      format: (v) => formatUsd(v as number | null),
    },
    {
      id: 'sold_price',
      header: 'Sold Price',
      format: (v) => formatUsd(v as number | null),
    },
    {
      id: 'original_price',
      header: 'Orig Price',
      headerTooltip: 'Original List Price',
      format: (v) => formatUsd(v as number | null),
    },
    {
      id: 'status',
      header: 'Status',
      format: (v) => (v as string) ?? '—',
    },
    {
      id: 'dom',
      header: 'DOM',
      headerTooltip: 'Days on Market',
      format: (v) => (v != null ? String(v) : '—'),
      defaultSort: 'asc',
    },
    {
      id: 'above_grade_sq_ft',
      header: 'Sq Ft',
      format: (v) => formatNumber(v as number | null),
    },
    {
      id: 'price_per_sqft',
      header: '$/SF',
      headerTooltip: 'Price per Square Foot',
      format: (v) => formatPricePerSqft(v as number | null),
    },
    {
      id: 'beds_baths',
      header: 'Bd/Ba',
      headerTooltip: 'Beds / Baths',
      getValue: (row) => formatBedsBaths(row.bedrooms ?? null, row.baths_full ?? null, row.baths_half ?? null),
      searchable: false,
    },
    {
      id: 'structure_type',
      header: 'Structure',
      format: (v) => (v as string) ?? '—',

    },
    {
      id: 'style',
      header: 'Style',
      format: (v) => (v as string) ?? '—',

    },
    {
      id: 'list_date',
      header: 'List Date',
      format: (v) => formatDate(v as string | null),

    },
    {
      id: 'settled_date',
      header: 'Settled Date',
      format: (v) => formatDate(v as string | null),

    },
    {
      id: 'list_office_name',
      header: 'List Office',
      format: (v) => (v as string) ?? '—',
    },
    {
      id: 'list_agent_name',
      header: 'List Agent',
      format: (v) => (v as string) ?? '—',
    },
    {
      id: 'new_construction_yn',
      header: 'New Const',
      headerTooltip: 'New Construction',
      format: (v) => (v == null ? '—' : v ? 'Yes' : 'No'),
    },
    {
      id: 'acres',
      header: 'Acres',
      format: (v) => (v != null ? Number(v).toFixed(2) : '—'),
    },
  ], []);

  // Loading state
  if (loading) {
    return <LoadingState message="Loading market data..." />;
  }

  // Error state
  if (error) {
    return <ErrorState message={error} actionLabel="Try Again" onAction={fetchData} />;
  }

  // Not configured state
  if (!summary?.is_configured) {
    return (
      <div className="bg-white border border-gray-200 rounded-lg p-8 text-center">
        <h3 className="text-lg font-bold text-ink mb-2">Market data not configured for this community</h3>
        <p className="text-ink-muted">
          Contact your administrator to set up MLS area and structure type mappings.
        </p>
      </div>
    );
  }

  return (
    <ConfiguredMarketContent
      summary={summary}
      normalizedShortCode={normalizedShortCode}
      sqftRange={sqftRange}
      sqftFilterEnabled={sqftFilterEnabled}
      listings={listings}
      filteredListings={filteredListings}
      statusFilter={statusFilter}
      onToggleSqftFilter={handleToggleSqftFilter}
      onStatusFilterChange={setStatusFilter}
      columns={columns}
    />
  );
}

