};

// Helper to create mock fetch implementation
const createMockFetch = (overrides: {
  sqftRange?: typeof mockSqftRange | typeof mockSqftRangeNoInventory;
  summary?: typeof mockSummary | { is_configured: false };
  listings?: typeof mockListings;
} = {}) => {
  return (url: string) => {
    if (url.includes('sqft-range')) {
      return Promise.resolve({
        ok: true,
        status: 200,
        json: () => Promise.resolve(overrides.sqftRange ?? mockSqftRange),
      });
    }
    if (url.includes('market-summary')) {
      return Promise.resolve({
        ok: true,
        status: 200,
        json: () => Promise.resolve(overrides.summary ?? mockSummary),
      });
    }
    if (url.includes('velocity-bands')) {
      return Promise.resolve({
        ok: true,
        status: 200,
        json: () => Promise.resolve(mockVelocityBands),
      });
    }
    if (url.includes('/market')) {
      return Promise.resolve({
        ok: true,
        status: 200,
        json: () => Promise.resolve(overrides.listings ?? mockListings),
      });
    }
    return Promise.resolve({
      ok: true,
      status: 200,
      json: () => Promise.resolve([]),
    });
  };
};

