    paceActual: null,
    paceGoal: null,
    agingSpecs: 0,
    medianDom: null,
    velocityBandDtp: null,
  };

  it('renders composite score in radial ring', () => {
    render(<CommunityHealthScore {...healthyProps} />);
    expect(screen.getByTestId('community-health-score')).toBeInTheDocument();
    expect(screen.getByTestId('health-gauge')).toBeInTheDocument();
  });

  it('renders 3 bullet bars with correct labels', () => {
    render(<CommunityHealthScore {...healthyProps} />);
    expect(screen.getByTestId('factor-velocity-band')).toBeInTheDocument();
    expect(screen.getByTestId('factor-pace-vs-budget')).toBeInTheDocument();
    expect(screen.getByTestId('factor-carry-cost')).toBeInTheDocument();
  });

  it('shows "Healthy" badge for high scores', () => {
    render(<CommunityHealthScore {...healthyProps} />);
    const badge = screen.getByTestId('alert-badge');
    expect(badge).toHaveTextContent('Healthy');
    expect(badge.className).toContain('bg-green-50');
    expect(badge.className).toContain('text-green-700');
  });

  it('shows "Watch" badge for mid-range scores', () => {
    render(<CommunityHealthScore {...watchProps} />);
    const badge = screen.getByTestId('alert-badge');
    expect(badge).toHaveTextContent('Watch');
    expect(badge.className).toContain('bg-amber-50');
    expect(badge.className).toContain('text-amber-600');
