  it('shows "Urgent" badge for low scores', () => {
    render(<CommunityHealthScore {...urgentProps} />);
    const badge = screen.getByTestId('alert-badge');
    expect(badge).toHaveTextContent('Urgent');
    expect(badge.className).toContain('bg-red-50');
    expect(badge.className).toContain('text-red-700');
  });

  it('shows "No Data" badge when all inputs are null/zero', () => {
    render(<CommunityHealthScore {...noDataProps} />);
    const badge = screen.getByTestId('alert-badge');
    expect(badge).toHaveTextContent('No Data');
    expect(badge.className).toContain('bg-gray-100');
  });

  it('shows velocity detail context string', () => {
    render(<CommunityHealthScore {...healthyProps} />);
    expect(screen.getByTestId('factor-velocity-band')).toHaveTextContent('1.3x faster than market');
  });

  it('shows pace detail with absolute sales numbers', () => {
    render(<CommunityHealthScore {...healthyProps} />);
    // 6 of 10 sold, salesBehindPace = 0.5*10 - 6 = -1 → clamped to 0 → "on pace"
    expect(screen.getByTestId('factor-pace-vs-budget')).toHaveTextContent('6 of 10 sold YTD');
    expect(screen.getByTestId('factor-pace-vs-budget')).toHaveTextContent('on pace');
  });

  it('shows carry detail context string', () => {
    render(<CommunityHealthScore {...healthyProps} />);
    expect(screen.getByTestId('factor-carry-cost')).toHaveTextContent('No aging inventory');
  });

  it('shows skeleton loading state', () => {
    render(<CommunityHealthScore {...healthyProps} loading />);
    expect(screen.getByTestId('health-score-skeleton')).toBeInTheDocument();
    expect(screen.queryByTestId('community-health-score')).not.toBeInTheDocument();
  });

  it('always uses provided YTD pace — props do not change with period toggle', () => {
    // Render with YTD data (60% pace at 50% elapsed)
    const { rerender } = render(<CommunityHealthScore {...healthyProps} />);
    const badge1 = screen.getByTestId('alert-badge').textContent;

    // Re-render with same props — score should be identical
    rerender(<CommunityHealthScore {...healthyProps} />);
    const badge2 = screen.getByTestId('alert-badge').textContent;
    expect(badge1).toBe(badge2);
  });
});

