import { getCompositeLabel } from '../../lib/communityHealthScoring';
import { formatUsdCompact } from '../../lib/formatUtils';
import { TooltipIcon } from '../ui/Tooltip';
import RadialRing from '../ui/RadialRing';
import BulletBar from '../ui/BulletBar';

// ── Shared props interface ──────────────────────────────────────────────────
// Both the overview (CommunityAlertCard) and community detail (CommunityHealthScore)
// build this data and pass it in. One rendering, one source of truth.

export type HealthWidgetData = {
  compositeScore: number | null;
  velocityScore: number | null;
  paceScore: number | null;
  carryScore: number | null;
  velocityDetail: string;
  paceDetail: string;
  carryDetail: string;
  // Raw metrics for display values and target lines
  medianDom: number | null;
  velocityBandDtp: number | null;
  paceDelta: number | null;
  monthlyCarryCost: number;
};

const HEALTHY_THRESHOLD = 65;
const WATCH_THRESHOLD = 40;

function getBadgeClasses(score: number | null): string {
  if (score == null) return 'bg-gray-100 text-gray-500';
  if (score >= HEALTHY_THRESHOLD) return 'bg-green-50 text-green-700';
  if (score >= WATCH_THRESHOLD) return 'bg-amber-50 text-amber-700';
  return 'bg-red-50 text-red-700';
}

function formatDom(days: number | null): string {
  if (days == null) return '—';
  return `${Math.round(days)}d`;
}

function formatPaceDelta(delta: number | null): string {
  if (delta == null) return '—';
  if (Math.abs(delta) < 0.05) return 'on pace';
  const abs = Math.abs(delta);
  const num = abs % 1 === 0 ? String(abs) : abs.toFixed(1);
  return delta > 0 ? `${num} ahead` : `${num} behind`;
}

export default function CommunityHealthWidget({ data }: { data: HealthWidgetData }) {
  const badgeClasses = getBadgeClasses(data.compositeScore);
  const badgeLabel = getCompositeLabel(data.compositeScore);

  return (
    <div>
      {/* Header */}
      <div className="flex items-center justify-between mb-1">
        <div className="text-sm font-semibold text-ink inline-flex items-center gap-1">
          Community Health
          <TooltipIcon
            content="Overall community health on a 0–100 scale, combining velocity band, pace vs budget, and carry cost factors. Higher is healthier. 65–100: Healthy, 40–64: Watch, 0–39: Urgent."
            testId="community-health-tooltip"
          />
        </div>
        <div
          data-testid="alert-badge"
          className={`text-xs px-2 py-0.5 rounded font-semibold ${badgeClasses}`}
        >
          {badgeLabel}
        </div>
      </div>
      <div className="text-xs text-ink-muted mb-4">Based on velocity, pace, and carry cost</div>

      {/* Radial ring + Bullet bars */}
      <div className="flex items-start gap-5">
        <div data-testid="health-gauge">
          <RadialRing score={data.compositeScore} />
        </div>
        <div className="flex-1 space-y-4 pt-1">
          <BulletBar
            label="Velocity Band"
            score={data.velocityScore}
            detail={data.velocityDetail}
            tooltip="Your median days on market vs. the local market benchmark."
            displayValue={formatDom(data.medianDom)}
          />
          <BulletBar
            label="Pace vs Budget"
            score={data.paceScore}
            detail={data.paceDetail}
            tooltip="Sales progress vs. annual budget goal, time-adjusted."
            displayValue={formatPaceDelta(data.paceDelta)}
          />
          <BulletBar
            label="Carry Cost"
            score={data.carryScore}
            detail={data.carryDetail}
            tooltip="Monthly carrying cost for aging inventory (>60 days). Green: ≤$12K/mo. Yellow: ≤$35K/mo. Red: >$35K/mo."
            displayValue={data.monthlyCarryCost > 0 ? `${formatUsdCompact(data.monthlyCarryCost)}/mo` : '$0'}
          />
        </div>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useState } from 'react';
import DataGrid, { type DataGridColumn } from '../ui/DataGrid';
import ErrorState from '../ui/ErrorState';
import LoadingState from '../ui/LoadingState';
import TabBar from '../ui/TabBar';

type CommunityLotsProps = {
  communityId: string;
};

type Lot = {
  id: string;
  lot_number: string;
  width: number;
  depth: number;
  premium_cost: number;
  premium_price: number;
  status: 'available' | 'reserved' | 'sold';
  constraints?: string[];
  notes?: string;
};

const getStatusColor = (status: string) => {
  switch (status) {
    case 'available':
      return 'bg-green-50 text-green-700';
    case 'reserved':
      return 'bg-amber-50 text-amber-700';
    case 'sold':
      return 'bg-gray-100 text-gray-500';
    default:
      return 'bg-gray-100 text-gray-500';
  }
};

const formatCurrency = (value: number) => {
  if (value === 0) return '-';
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    maximumFractionDigits: 0,
  }).format(value);
};

export default function CommunityLots({ communityId }: CommunityLotsProps) {
  const [lots, setLots] = useState<Lot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filter, setFilter] = useState<'all' | 'available' | 'reserved' | 'sold'>('all');

  useEffect(() => {
    fetchLots();
  }, [communityId]);

  const fetchLots = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/lots?communityId=${communityId}`);

      if (!response.ok) {
        throw new Error('Failed to fetch lots');
      }

      const data = await response.json();
      setLots(data || []);
    } catch (err) {
      setError('Unable to load lots');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const filteredLots = useMemo(() => {
    return lots.filter((lot) => {
      if (filter === 'all') return true;
      return lot.status === filter;
    });
  }, [lots, filter]);

  const lotsByStatus = {
    available: lots.filter((l) => l.status === 'available').length,
    reserved: lots.filter((l) => l.status === 'reserved').length,
    sold: lots.filter((l) => l.status === 'sold').length,
  };

  const columns = useMemo<DataGridColumn<Lot>[]>(() => [
    {
      id: 'lot_number',
      header: 'Lot #',
      format: (v) => v ? `Lot ${v}` : '—',

    },
    {
      id: 'dimensions',
      header: 'Dimensions',
      getValue: (row) => `${row.width}' × ${row.depth}'`,
      render: (row) => (
        <div>
          <span className="text-sm text-ink-muted">
            {row.width}' × {row.depth}'
          </span>
          <br />
          <span className="text-xs text-ink-muted">
            ({(row.width * row.depth).toLocaleString()} SF)
          </span>
        </div>
      ),

    },
    {
      id: 'premium_cost',
      header: 'Premium Cost',
      format: (v) => formatCurrency((v as number) ?? 0),

    },
    {
      id: 'premium_price',
      header: 'Premium Price',
      format: (v) => formatCurrency((v as number) ?? 0),

    },
    {
      id: 'constraints',
      header: 'Features',
      searchable: false,
      render: (row) => {
        const constraints = row.constraints;
        if (constraints && constraints.length > 0) {
          return (
            <div className="flex flex-wrap gap-1">
              {constraints.map((constraint, idx) => (
                <span
                  key={`${constraint}-${idx}`}
                  className="inline-block px-2 py-1 bg-blue-100 text-blue-700 text-xs rounded"
                >
                  {constraint}
                </span>
              ))}
            </div>
          );
        }
        return <span className="text-sm text-ink-muted">-</span>;
      },

    },
    {
      id: 'status',
      header: 'Status',
      render: (row) => (
        <span className={`inline-block px-3 py-1 rounded-full text-xs font-medium ${getStatusColor(row.status ?? '')}`}>
          {(row.status ?? '').toUpperCase() || '—'}
        </span>
      ),

    },
    {
      id: 'actions',
      header: 'Actions',
      sortable: false,
      searchable: false,
      render: (row) => (
        <button
          onClick={() => {
            if (row.id) {
              window.location.href = `/communities/${communityId}/lots/edit/${row.id}`;
            }
          }}
          className="text-brand hover:text-brand-hover font-medium"
        >
          Edit
        </button>
      ),

    },
  ], [communityId]);

  if (loading) {
    return <LoadingState />;
  }

  if (error) {
    return <ErrorState message={error} actionLabel="Try Again" onAction={fetchLots} />;
  }

  if (lots.length === 0) {
    return (
      <div className="text-center py-12">
        <div className="mb-6">
          <svg
            className="mx-auto h-12 w-12 text-gray-400"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M9 20l-5.447-2.724A1 1 0 013 16.382V5.618a1 1 0 011.447-.894L9 7m0 13l6-3m-6 3V7m6 10l4.553 2.276A1 1 0 0021 18.382V7.618a1 1 0 00-.553-.894L15 4m0 13V4m0 0L9 7"
            />
          </svg>
        </div>
        <h3 className="text-lg font-medium text-ink mb-2">No Lots Added</h3>
        <p className="text-ink-muted mb-6">Add lot inventory to start tracking availability</p>
        <button
          onClick={() => {
            window.location.href = `/communities/${communityId}/lots/add`;
          }}
          className="bg-brand hover:bg-brand-hover text-white font-semibold px-6 py-3 rounded-lg transition-colors ease-out"
        >
          + Add Lot
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6">
        {/* Header & Stats */}
      <div>
        <div className="flex items-center justify-between mb-6">
          <div>
            <h2 className="text-xl font-bold text-ink">Lot Inventory</h2>
            <p className="text-ink-muted mt-1">{lots.length} total lots</p>
          </div>
          <button
            onClick={() => {
              window.location.href = `/communities/${communityId}/lots/add`;
            }}
            className="bg-brand hover:bg-brand-hover text-white font-semibold px-6 py-2 rounded-lg transition-colors ease-out"
          >
            + Add Lot
          </button>
        </div>

        {/* Status Summary */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
          <div className="bg-green-50 border-2 border-green-200 rounded-lg p-4">
            <p className="text-sm text-green-700 mb-1">Available</p>
            <p className="text-2xl font-bold text-green-900">{lotsByStatus.available}</p>
          </div>
          <div className="bg-orange-50 border-2 border-orange-200 rounded-lg p-4">
            <p className="text-sm text-orange-700 mb-1">Reserved</p>
            <p className="text-2xl font-bold text-orange-900">{lotsByStatus.reserved}</p>
          </div>
          <div className="bg-gray-50 border-2 border-gray-200 rounded-lg p-4">
            <p className="text-sm text-gray-700 mb-1">Sold</p>
            <p className="text-2xl font-bold text-gray-900">{lotsByStatus.sold}</p>
          </div>
        </div>

        {/* Filter Tabs */}
        <TabBar
          tabs={[
            { id: 'all', label: 'All Lots', count: lots.length },
            { id: 'available', label: 'Available', count: lotsByStatus.available },
            { id: 'reserved', label: 'Reserved', count: lotsByStatus.reserved },
            { id: 'sold', label: 'Sold', count: lotsByStatus.sold },
          ]}
          activeTab={filter}
          onChange={(id) => setFilter(id as typeof filter)}
          size="md"
        />
      </div>

      {/* Lots Table */}
      <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
        <DataGrid
          data={filteredLots}
          columns={columns}
          maxHeight="none"
        />
      </div>
    </div>
  );
}

