export default function PropertiesList() {
  const [properties, setProperties] = useState<PropertyWithCommunity[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showOnlyUnlinked, setShowOnlyUnlinked] = useState(false);

  useEffect(() => {
    async function fetchProperties() {
      try {
        setLoading(true);
        const { data: { user }, error: userError } = await supabase.auth.getUser();

        if (userError || !user) {
          window.location.href = '/';
          return;
        }

        // Fetch properties with community names via join
        const { data, error: fetchError } = await supabase
          .from('properties')
          .select(`
            *,
            communities (
              name
            )
          `)
          .eq('user_id', user.id)
          .order('created_at', { ascending: false });

        if (fetchError) {
          setError('Unable to load properties. Please try again.');
          return;
        }

        // Transform data to include community_name
        const transformedData = (data || []).map((property: any) => ({
          ...property,
          community_name: property.communities?.name || null,
        }));

        setProperties(transformedData);
      } catch {
        setError('Unable to load properties. Please try again.');
      } finally {
        setLoading(false);
      }
    }

    fetchProperties();
  }, []);

  const handleRowClick = (id: string) => {
    window.location.href = `/properties/${id}`;
  };

  const filteredProperties = showOnlyUnlinked
    ? properties.filter(p => !p.community_id)
    : properties;

  return (
    <div className="max-w-7xl mx-auto space-y-6">
      {/* Header Section */}
      <div className="bg-white rounded-lg shadow-sm p-6">
        <div className="flex items-center justify-between mb-4">
          <h1 className="text-3xl font-bold text-ink">Properties</h1>
          <div className="flex items-center space-x-4">
            <a
              href="/properties/add"
              className="bg-brand hover:bg-brand-hover text-white font-semibold px-6 py-3 rounded-lg transition-colors ease-out"
            >
              + Add Property
            </a>
            <a
              href="/admin/import"
              className="border-2 border-brand text-brand hover:bg-brand hover:text-white font-semibold px-6 py-3 rounded-lg transition-colors ease-out"
            >
              📁 Import from ERP
            </a>
          </div>
        </div>

        <UnlinkedFilterToggle
          propertiesCount={properties.length}
          showOnlyUnlinked={showOnlyUnlinked}
          setShowOnlyUnlinked={setShowOnlyUnlinked}
        />
      </div>

      {/* Loading State */}
      {loading && (
        <div className="bg-white rounded-lg shadow-sm p-12">
          <LoadingState />
        </div>
      )}

      {/* Error State */}
      {error && !loading && (
        <div className="bg-red-50 text-red-600 p-4 rounded-lg">
          {error}
        </div>
      )}

      {/* Empty State */}
      {!loading && !error && properties.length === 0 && (
        <div className="bg-white rounded-lg shadow-sm p-12 text-center">
          <div className="text-6xl mb-4">🏠</div>
          <h2 className="text-2xl font-bold text-ink mb-2">No Properties Yet</h2>
          <p className="text-ink-muted mb-8 max-w-2xl mx-auto">
            Get started by adding your first property to track details, options, and insights.
            You can add properties individually or upload multiple at once via CSV.
          </p>
          <div className="flex items-center justify-center space-x-4">
            <a
              href="/properties/add"
              className="bg-brand hover:bg-brand-hover text-white font-semibold px-8 py-3 rounded-lg transition-colors ease-out"
            >
              + Add Your First Property
            </a>
            <a
              href="/admin/import"
              className="border-2 border-brand text-brand hover:bg-brand hover:text-white font-semibold px-8 py-3 rounded-lg transition-colors ease-out"
            >
              📁 Import from ERP
            </a>
          </div>
        </div>
      )}

      {/* Empty State for Filtered View */}
      {!loading && !error && properties.length > 0 && filteredProperties.length === 0 && (
        <div className="bg-white rounded-lg shadow-sm p-12 text-center">
          <div className="text-6xl mb-4">🔍</div>
          <h2 className="text-2xl font-bold text-ink mb-2">No Unlinked Properties</h2>
          <p className="text-ink-muted mb-4">
            All your properties are currently linked to communities.
          </p>
        </div>
      )}

      {/* Table View */}
      {!loading && !error && filteredProperties.length > 0 && (
        <div className="bg-white rounded-lg shadow-sm overflow-hidden">
          <table className="w-full">
            <thead className="bg-surface">
              <tr>
                <th className="px-6 py-4 text-left text-sm font-semibold text-ink">Job ID</th>
                <th className="px-6 py-4 text-left text-sm font-semibold text-ink">Address/Location</th>
                <th className="px-6 py-4 text-left text-sm font-semibold text-ink">Model</th>
                <th className="px-6 py-4 text-left text-sm font-semibold text-ink">Status</th>
                <th className="px-6 py-4 text-left text-sm font-semibold text-ink">Community</th>
              </tr>
            </thead>
            <tbody>
              {filteredProperties.map((property) => (
                <PropertyRow
                  key={property.id}
                  property={property}
                  onRowClick={handleRowClick}
                />
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

