export default function PropertyDashboard({ id }: PropertyDashboardProps) {
  const [property, setProperty] = useState<PropertyWithCommunity | null>(null);
  const [options, setOptions] = useState<PropertyOption[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchProperty() {
      try {
        setLoading(true);
        const { data: { user }, error: userError } = await supabase.auth.getUser();

        if (userError || !user) {
          window.location.href = '/';
          return;
        }

        // Fetch property with community name
        const { data: propertyData, error: fetchError } = await supabase
          .from('properties')
          .select(`
            *,
            communities (
              name
            )
          `)
          .eq('id', id)
          .eq('user_id', user.id)
          .single();

        if (fetchError || !propertyData) {
          setError('Property not found');
          return;
        }

        // Transform data
        const transformedProperty: PropertyWithCommunity = {
          ...propertyData,
          community_name: propertyData.communities?.name || null,
        };
        setProperty(transformedProperty);
        const addr = [transformedProperty.street_address, transformedProperty.city, transformedProperty.state]
          .filter(Boolean).join(', ');
        if (addr) dispatchBreadcrumbContext({ propertyAddress: addr });

        // Fetch property options
        const { data: optionsData, error: optionsError } = await supabase
          .from('property_options')
          .select('*')
          .eq('property_id', id)
          .order('created_at');

        if (!optionsError && optionsData) {
          setOptions(optionsData);
        }
      } catch {
        setError('Unable to load property. Please try again.');
      } finally {
        setLoading(false);
      }
    }

    if (id) {
      fetchProperty();
    }
  }, [id]);

  const editHref = `/properties/${id}/edit`;

