import { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import ErrorState from '../ui/ErrorState';
import LoadingState from '../ui/LoadingState';
import type { Property, PropertyStatus } from '../../types/property';

type CommunityPropertiesListProps = {
  communityId: string;
  communityName: string;
};

export default function CommunityPropertiesList({ communityId, communityName }: CommunityPropertiesListProps) {
  const [properties, setProperties] = useState<Property[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchProperties() {
      try {
        setLoading(true);
        const { data: { user }, error: userError } = await supabase.auth.getUser();

        if (userError || !user) {
          setError('Authentication error');
          return;
        }

        const { data, error: fetchError } = await supabase
          .from('properties')
          .select('*')
          .eq('community_id', communityId)
          .eq('user_id', user.id)
          .order('created_at', { ascending: false });

        if (fetchError) {
          setError('Unable to load properties');
          console.error('Error fetching properties:', fetchError);
          return;
        }

        setProperties(data || []);
      } catch (err) {
        setError('Unable to load properties');
        console.error('Unexpected error:', err);
      } finally {
        setLoading(false);
      }
    }

    fetchProperties();
  }, [communityId]);

  const getStatusColor = (status: PropertyStatus | null) => {
    switch (status) {
      case 'Available':
        return 'bg-green-50 text-green-700';
      case 'Under Construction':
        return 'bg-blue-50 text-blue-700';
      case 'Sold':
        return 'bg-gray-100 text-gray-600';
      case 'Inventory/Spec':
        return 'bg-amber-50 text-amber-700';
      default:
        return 'bg-gray-100 text-gray-500';
    }
  };

  const handleAddProperty = () => {
    // Navigate to add property page with community_id pre-filled in URL
    window.location.href = `/properties/add?community_id=${communityId}`;
  };

  const handlePropertyClick = (propertyId: string) => {
    window.location.href = `/properties/${propertyId}`;
  };

  // Loading state
  if (loading) {
    return (
      <div className="bg-white rounded-lg shadow-sm p-6">
        <h3 className="text-lg font-bold text-ink mb-4">Properties</h3>
        <LoadingState className="h-48" />
      </div>
    );
  }

  // Error state
  if (error) {
    return (
      <div className="bg-white rounded-lg shadow-sm p-6">
        <h3 className="text-lg font-bold text-ink mb-4">Properties</h3>
        <ErrorState message={error} className="h-48 bg-surface rounded-lg" />
      </div>
    );
  }

  // Empty state
  if (properties.length === 0) {
    return (
      <div className="bg-white rounded-lg shadow-sm p-6">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-bold text-ink">Properties</h3>
          <button
            onClick={handleAddProperty}
            className="bg-brand hover:bg-brand-hover text-white font-semibold px-4 py-2 rounded-lg transition-colors ease-out text-sm"
          >
            + Add Property
          </button>
        </div>
        <div className="flex flex-col items-center justify-center h-48 bg-surface rounded-lg">
          <p className="text-ink-muted mb-4">No properties in this community yet</p>
          <button
            onClick={handleAddProperty}
            className="text-brand hover:text-brand-hover font-medium transition-colors ease-out"
          >
            Add your first property →
          </button>
        </div>
      </div>
    );
  }

  // Calculate status summary
  const statusCounts = properties.reduce((acc, prop) => {
    const status = prop.status || 'Unknown';
    acc[status] = (acc[status] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  // Main content with properties
  return (
    <div className="bg-white rounded-lg shadow-sm p-6">
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <div>
          <h3 className="text-lg font-bold text-ink">Properties</h3>
          <p className="text-sm text-ink-muted mt-1">
            {properties.length} {properties.length === 1 ? 'property' : 'properties'} in {communityName}
          </p>
        </div>
        <button
          onClick={handleAddProperty}
          className="bg-brand hover:bg-brand-hover text-white font-semibold px-4 py-2 rounded-lg transition-colors ease-out text-sm"
        >
          + Add Property
        </button>
      </div>

      {/* Status Summary */}
      <div className="flex flex-wrap gap-2 mb-4 pb-4 border-b border-gray-200">
        {Object.entries(statusCounts).map(([status, count]) => (
          <span
            key={status}
            className={`inline-block px-3 py-1 rounded-full text-xs font-medium ${getStatusColor(status as PropertyStatus)}`}
          >
            {status}: {count}
          </span>
        ))}
      </div>

      {/* Properties List */}
      <div className="space-y-2 max-h-96 overflow-y-auto">
        {properties.map((property) => (
          <div
            key={property.id}
            onClick={() => handlePropertyClick(property.id)}
            className="p-4 bg-surface hover:bg-gray-100 rounded-lg cursor-pointer transition-colors ease-out group"
          >
            <div className="flex items-center justify-between">
              <div className="flex-1">
                <div className="flex items-center gap-3 mb-2">
                  <h4 className="font-semibold text-ink group-hover:text-brand transition-colors ease-out">
                    Job ID: {property.job_id}
                  </h4>
                  {property.status && (
                    <span className={`inline-block px-2 py-1 rounded-full text-xs font-medium ${getStatusColor(property.status)}`}>
                      {property.status}
                    </span>
                  )}
                </div>
                <div className="flex items-center gap-4 text-sm text-ink-muted">
                  {property.model_name && (
                    <span>Model: {property.model_name}</span>
                  )}
                  {property.bedrooms && property.bathrooms_full && (
                    <span>{property.bedrooms}bd / {property.bathrooms_full}ba</span>
                  )}
                  {property.square_feet && (
                    <span>{property.square_feet.toLocaleString()} sqft</span>
                  )}
                  {property.base_price && (
                    <span className="font-medium text-ink">
                      ${property.base_price.toLocaleString()}
                    </span>
                  )}
                </div>
              </div>
              <svg
                className="w-5 h-5 text-ink-muted group-hover:text-brand transition-colors ease-out"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
              </svg>
            </div>
          </div>
        ))}
      </div>

      {/* View All Link */}
      {properties.length > 5 && (
        <div className="mt-4 pt-4 border-t border-gray-200 text-center">
          <a
            href={`/properties?community_id=${communityId}`}
            className="text-brand hover:text-brand-hover font-medium transition-colors ease-out text-sm"
          >
            View all properties in {communityName} →
          </a>
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import ErrorState from '../ui/ErrorState';
import LoadingState from '../ui/LoadingState';

type CommunityFloorPlansProps = {
  communityId: string;
  communityName: string;
};

type FloorPlan = {
  id: string;
  name: string;
  square_feet: number;
  bedrooms: number;
  bathrooms_full: number;
  bathrooms_half: number;
  stories: number;
};

type CommunityFloorPlan = {
  id: string;
  base_cost: number;
  base_price: number;
  target_persona?: string;
  status: string;
  estimated_build_days?: number;
  standard_option_ids: string[];
  floor_plan: FloorPlan;
};

export default function CommunityFloorPlans({ communityId, communityName }: CommunityFloorPlansProps) {
  const [floorPlans, setFloorPlans] = useState<CommunityFloorPlan[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchFloorPlans();
  }, [communityId]);

  const fetchFloorPlans = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/community-floor-plans?communityId=${communityId}`);

      if (!response.ok) {
        throw new Error('Failed to fetch floor plans');
      }

      const data = await response.json();
      setFloorPlans(data || []);
    } catch (err) {
      setError('Unable to load floor plans');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active':
        return 'bg-green-50 text-green-700';
      case 'coming_soon':
        return 'bg-blue-100 text-blue-700';
      case 'sold_out':
        return 'bg-gray-100 text-gray-500';
      case 'discontinued':
        return 'bg-red-50 text-red-700';
      default:
        return 'bg-gray-100 text-gray-500';
    }
  };

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      maximumFractionDigits: 0,
    }).format(value);
  };

  const calculateMargin = (cost: number, price: number) => {
    const margin = ((price - cost) / price) * 100;
    return margin.toFixed(1);
  };

  if (loading) {
    return <LoadingState />;
  }

  if (error) {
    return <ErrorState message={error} actionLabel="Try Again" onAction={fetchFloorPlans} />;
  }

  if (floorPlans.length === 0) {
    return (
      <div className="text-center py-12">
        <div className="mb-6">
          <svg
            className="mx-auto h-12 w-12 text-gray-400"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"
            />
          </svg>
        </div>
        <h3 className="text-lg font-medium text-ink mb-2">
          No Floor Plans Assigned
        </h3>
        <p className="text-ink-muted mb-6">
          Assign floor plans to this community to start building specs
        </p>
        <button
          onClick={() => {
            window.location.href = `/communities/${communityId}/floor-plans/assign`;
          }}
          className="bg-brand hover:bg-brand-hover text-white font-semibold px-6 py-3 rounded-lg transition-colors ease-out"
        >
          Assign Floor Plan
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6">
        {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold text-ink">
            Floor Plans for {communityName}
          </h2>
          <p className="text-ink-muted mt-1">
            {floorPlans.length} {floorPlans.length === 1 ? 'plan' : 'plans'} assigned
          </p>
        </div>
        <button
          onClick={() => {
            window.location.href = `/communities/${communityId}/floor-plans/assign`;
          }}
          className="bg-brand hover:bg-brand-hover text-white font-semibold px-6 py-2 rounded-lg transition-colors ease-out"
        >
          + Assign Floor Plan
        </button>
      </div>

      {/* Floor Plans Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {floorPlans.map((cfp) => (
          <div
            key={cfp.id}
            className="bg-white border-2 border-gray-200 rounded-lg p-6 hover:border-brand hover:shadow-lg transition-all ease-out cursor-pointer"
          >
            {/* Status Badge */}
            <div className="flex items-center justify-between mb-4">
              <span className={`inline-block px-3 py-1 rounded-full text-xs font-medium ${getStatusColor(cfp.status)}`}>
                {cfp.status.replace('_', ' ').toUpperCase()}
              </span>
              {cfp.target_persona && (
                <span className="text-xs text-ink-muted">{cfp.target_persona}</span>
              )}
            </div>

            {/* Floor Plan Name */}
            <h3 className="text-lg font-bold text-ink mb-2">
              {cfp.floor_plan.name}
            </h3>

            {/* Specs */}
            <div className="flex items-center space-x-4 text-sm text-ink-muted mb-4">
              <span>{cfp.floor_plan.square_feet.toLocaleString()} SF</span>
              <span>•</span>
              <span>{cfp.floor_plan.bedrooms} Bed</span>
              <span>•</span>
              <span>
                {cfp.floor_plan.bathrooms_full}
                {cfp.floor_plan.bathrooms_half > 0 && `.${cfp.floor_plan.bathrooms_half}`} Bath
              </span>
            </div>

            {/* Pricing */}
            <div className="space-y-2 mb-4">
              <div className="flex items-center justify-between text-sm">
                <span className="text-ink-muted">Base Cost</span>
                <span className="font-medium text-ink">{formatCurrency(cfp.base_cost)}</span>
              </div>
              <div className="flex items-center justify-between text-sm">
                <span className="text-ink-muted">Base Price</span>
                <span className="font-medium text-ink">{formatCurrency(cfp.base_price)}</span>
              </div>
              <div className="flex items-center justify-between text-sm border-t border-gray-200 pt-2">
                <span className="text-ink-muted font-medium">Margin</span>
                <span className="font-bold text-status-success">
                  {calculateMargin(cfp.base_cost, cfp.base_price)}%
                </span>
              </div>
            </div>

            {/* Standard Options Count */}
            {cfp.standard_option_ids && cfp.standard_option_ids.length > 0 && (
              <div className="text-xs text-ink-muted mb-4">
                {cfp.standard_option_ids.length} standard {cfp.standard_option_ids.length === 1 ? 'option' : 'options'} included
              </div>
            )}

            {/* Build Time */}
            {cfp.estimated_build_days && (
              <div className="text-xs text-ink-muted mb-4">
                Est. {cfp.estimated_build_days} days to build
              </div>
            )}

            {/* Actions */}
            <div className="flex items-center space-x-2">
              <button
                onClick={() => {
                  window.location.href = `/communities/${communityId}/floor-plans/edit/${cfp.id}`;
                }}
                className="flex-1 bg-white border border-gray-300 text-ink font-medium px-4 py-2 rounded-lg hover:border-brand hover:text-brand transition-colors ease-out text-sm"
              >
                Edit Pricing
              </button>
              <button className="flex-1 bg-brand hover:bg-brand-hover text-white font-medium px-4 py-2 rounded-lg transition-colors ease-out text-sm">
                View Details
              </button>
