        ))}
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { dispatchBreadcrumbContext } from '../../lib/breadcrumbUtils';
import { supabase } from '../../lib/supabase';
import LoadingState from '../ui/LoadingState';
import TabBar from '../ui/TabBar';
import CommunityPropertiesList from './CommunityPropertiesList';
import CommunityFloorPlans from './CommunityFloorPlans';
import CommunityLots from './CommunityLots';
import CommunitySpecDecisions from './CommunitySpecDecisions';

type Community = {
  id: string;
  name: string;
  address: string;
  city?: string;
  state?: string;
  zip_code?: string;
  status: 'Active' | 'Planning' | 'In Development' | 'Close Out';
  total_lots: number;
  lots_under_control: number;
  absorption_rate?: number;
  active_listings?: number;
  months_supply?: number;
  avg_price_psf?: number;
  competitive_density?: number;
  created_at: string;
};

type LegacyCommunityDashboardProps = {
  id: string;
};

type TabType = 'overview' | 'floor-plans' | 'lots' | 'properties' | 'spec-decisions';

const VALID_TABS: Set<string> = new Set<string>([
  'overview', 'floor-plans', 'lots', 'properties', 'spec-decisions',
]);

const LEGACY_TABS: { id: TabType; label: string }[] = [
  { id: 'overview', label: 'Overview' },
  { id: 'floor-plans', label: 'Floor Plans' },
  { id: 'lots', label: 'Lots' },
  { id: 'properties', label: 'Properties' },
  { id: 'spec-decisions', label: 'Spec Decisions' },
];

const STATUS_COLORS: Record<Community['status'], string> = {
  Active: 'bg-green-50 text-green-700',
  Planning: 'bg-amber-50 text-amber-700',
  'In Development': 'bg-blue-100 text-blue-700',
  'Close Out': 'bg-gray-100 text-gray-500',
};

type CommunityLoadResult =
  | { kind: 'unauthorized' }
  | { kind: 'not_found' }
  | { kind: 'error'; message: string }
  | { kind: 'ok'; community: Community };

async function loadCommunity(id: string): Promise<CommunityLoadResult> {
  try {
    const { data: { user }, error: userError } = await supabase.auth.getUser();

    if (userError || !user) {
      return { kind: 'unauthorized' };
    }

    const { data, error: fetchError } = await supabase
      .from('communities')
      .select('*')
      .eq('id', id)
      .eq('user_id', user.id)
      .single();

    if (fetchError || !data) {
      return { kind: 'not_found' };
    }

    return { kind: 'ok', community: data as Community };
  } catch {
    return { kind: 'error', message: 'Unable to load community. Please try again.' };
  }
}

type LegacyHeaderProps = {
  community: Community;
  onEdit: () => void;
};

function LegacyHeader({ community, onEdit }: LegacyHeaderProps) {
  return (
    <div className="bg-white rounded-lg shadow-sm p-6">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-3xl font-bold text-ink">{community.name}</h1>
          {community.city && community.state && (
            <p className="text-ink-muted mt-1">{community.city}, {community.state}</p>
          )}
        </div>
        <button
          onClick={onEdit}
          className="bg-white border-2 border-brand text-brand font-semibold px-6 py-2 rounded-lg hover:bg-brand hover:text-white transition-colors ease-out"
        >
          Edit Community
        </button>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
        <div className="bg-surface rounded-lg p-4">
          <p className="text-sm text-ink-muted mb-1">Status</p>
          <span className={`inline-block px-3 py-1 rounded-full text-sm font-medium ${STATUS_COLORS[community.status] ?? 'bg-gray-100 text-gray-500'}`}>
            {community.status}
          </span>
        </div>

        <div className="bg-surface rounded-lg p-4">
          <p className="text-sm text-ink-muted mb-1">Lots Remaining</p>
          <p className="text-ink font-medium text-xl">{community.total_lots}</p>
        </div>

        {community.absorption_rate && (
          <div className="bg-surface rounded-lg p-4">
            <p className="text-sm text-ink-muted mb-1">Absorption Rate</p>
            <p className="text-ink font-medium text-xl">{community.absorption_rate}<span className="text-sm text-ink-muted">/mo</span></p>
          </div>
        )}

        {community.avg_price_psf && (
          <div className="bg-surface rounded-lg p-4">
            <p className="text-sm text-ink-muted mb-1">Avg Price/SF</p>
            <p className="text-ink font-medium text-xl">${community.avg_price_psf}</p>
          </div>
        )}

        {community.months_supply && (
          <div className="bg-surface rounded-lg p-4">
            <p className="text-sm text-ink-muted mb-1">Months Supply</p>
            <p className="text-ink font-medium text-xl">{community.months_supply}</p>
          </div>
        )}
      </div>
    </div>
  );
}

function LegacyOverviewTab({ community }: { community: Community }) {
  return (
    <div className="space-y-6">
      <div className="bg-gradient-to-r from-brand to-brand-hover rounded-lg shadow-lg p-8 text-center">
        <h2 className="text-2xl font-bold text-white mb-2">Ready to Run the Smart Spec Wizard?</h2>
        <p className="text-white/90 mb-4">
          Get AI-powered spec recommendations based on P3 scoring
        </p>
        <button className="bg-white text-brand font-semibold px-6 py-3 rounded-lg hover:bg-gray-100 transition-colors ease-out">
          Launch Wizard
        </button>
      </div>

      {(community.absorption_rate || community.avg_price_psf || community.months_supply) && (
        <div>
          <h3 className="text-lg font-bold text-ink mb-4">Market Metrics</h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {community.absorption_rate && (
              <div className="bg-surface rounded-lg p-4">
                <p className="text-sm text-ink-muted mb-1">Absorption Rate</p>
                <p className="text-ink font-medium text-2xl">{community.absorption_rate}</p>
                <p className="text-xs text-ink-muted">homes per month</p>
              </div>
            )}

            {community.active_listings && (
              <div className="bg-surface rounded-lg p-4">
                <p className="text-sm text-ink-muted mb-1">Active Listings</p>
                <p className="text-ink font-medium text-2xl">{community.active_listings}</p>
                <p className="text-xs text-ink-muted">current inventory</p>
              </div>
            )}

            {community.months_supply && (
              <div className="bg-surface rounded-lg p-4">
                <p className="text-sm text-ink-muted mb-1">Months Supply</p>
                <p className="text-ink font-medium text-2xl">{community.months_supply}</p>
                <p className="text-xs text-ink-muted">market balance</p>
              </div>
            )}
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white border border-gray-200 rounded-lg p-6">
          <h3 className="text-lg font-bold text-ink mb-4">Analytics</h3>
          <div className="flex items-center justify-center h-32 bg-surface rounded-lg">
            <p className="text-ink-muted">No performance data available</p>
          </div>
        </div>

        <div className="bg-white border border-gray-200 rounded-lg p-6">
          <h3 className="text-lg font-bold text-ink mb-4">Alerts</h3>
          <div className="flex items-center justify-center h-32 bg-surface rounded-lg">
            <p className="text-ink-muted">No active alerts</p>
          </div>
        </div>
      </div>
    </div>
  );
}

type LegacyTabContentProps = {
  activeTab: TabType;
  community: Community;
};

function LegacyTabContent({ activeTab, community }: LegacyTabContentProps) {
  if (activeTab === 'overview') return <LegacyOverviewTab community={community} />;
  if (activeTab === 'floor-plans') return <CommunityFloorPlans communityId={community.id} communityName={community.name} />;
  if (activeTab === 'lots') return <CommunityLots communityId={community.id} />;
  if (activeTab === 'properties') return <CommunityPropertiesList communityId={community.id} communityName={community.name} />;
  return <CommunitySpecDecisions communityId={community.id} />;
}

function ErrorState({ message }: { message: string }) {
  return (
    <div className="max-w-screen-2xl mx-auto space-y-6">
      <div className="bg-white rounded-lg shadow-sm p-12 text-center">
        <h2 className="text-2xl font-bold text-ink mb-2">Community Not Found</h2>
        <p className="text-ink-muted">{message}</p>
      </div>
    </div>
  );
}

export default function LegacyCommunityDashboard({ id }: LegacyCommunityDashboardProps) {
  const [community, setCommunity] = useState<Community | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<TabType>('overview');

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const tab = params.get('tab');
    if (tab && VALID_TABS.has(tab)) {
      setActiveTab(tab as TabType);
    }
  }, []);

  useEffect(() => {
    let isCancelled = false;

    const fetchCommunity = async () => {
      setLoading(true);
      setError(null);
      const result = await loadCommunity(id);
      if (isCancelled) return;

      if (result.kind === 'unauthorized') {
        window.location.href = '/';
        return;
      }

      if (result.kind === 'not_found') {
        setError('The community you\'re looking for doesn\'t exist or you don\'t have access to it.');
      } else if (result.kind === 'error') {
        setError(result.message);
      } else {
        setCommunity(result.community);
        dispatchBreadcrumbContext({ communityName: result.community.name });
      }

      setLoading(false);
    };

    if (id) {
      void fetchCommunity();
    }

    return () => {
      isCancelled = true;
    };
  }, [id]);

  const handleEdit = () => {
    window.location.href = `/communities/${id}/edit`;
  };

  if (loading) {
    return (
      <div className="max-w-screen-2xl mx-auto space-y-6">
        <div className="bg-white rounded-lg shadow-sm p-12">
          <LoadingState />
        </div>
      </div>
    );
  }

  if (error || !community) {
    return <ErrorState message={error ?? 'Unable to load community. Please try again.'} />;
  }

  return (
    <div className="max-w-screen-2xl mx-auto space-y-6">
      <LegacyHeader community={community} onEdit={handleEdit} />

      <div className="bg-white rounded-lg shadow-sm">
        <div className="px-6 pt-4">
          <TabBar
            tabs={LEGACY_TABS}
            activeTab={activeTab}
            onChange={(tabId) => setActiveTab(tabId as TabType)}
            size="md"
          />
        </div>

        <div className="p-6">
          <LegacyTabContent activeTab={activeTab} community={community} />
        </div>
      </div>
    </div>
  );
}

